--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "QLPN_SUOI_HAI"."CHART_THONG_KE" ("NAM", "TS") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  select to_char(ngay_den_trai,'yyyy') nam,count(*) ts
from pn_lai_lich
group by to_char(ngay_den_trai,'yyyy')

;
--------------------------------------------------------
