--------------------------------------------------------
--  DDL for View CONV_PN_QHGD
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "QLPN_SUOI_HAI"."CONV_PN_QHGD" ("PN_ID", "HO_TEN_BO", "DC_BO", "HO_TEN_ME", "DC_ME", "HO_TEN_VC", "DC_VC", "GHI_CHU_TIEN_SU") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  select t.pn_id,
       bo.ho_ten_qhgd ho_ten_bo,
       bo.noi_o dc_bo,
       me.ho_ten_qhgd ho_ten_me,
       me.noi_o dc_me,
       vc.ho_ten_qhgd ho_ten_vc,
       vc.noi_o dc_vc,
       ts.ghi_chu_ts ghi_chu_tien_su
  from pn_lai_lich t,
  (select pn_id, ho_ten_qhgd, noi_o from pn_quan_he_gia_dinh where ma_quan_he='121') bo,
  (select pn_id, ho_ten_qhgd, noi_o from pn_quan_he_gia_dinh where ma_quan_he='122') me,
  (select pn_id, ho_ten_qhgd, noi_o from pn_quan_he_gia_dinh where ma_quan_he='132') vc,
  (select pn_id, ghi_chu_ts from pn_tien_su where ghi_chu_ts is not null) ts
  where t.pn_id=bo.pn_id(+)
  and t.pn_id=me.pn_id(+)
  and t.pn_id=vc.pn_id(+)
  and t.pn_id=ts.pn_id(+)

;
--------------------------------------------------------
--  DDL for View DS_AN_GIAM
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "QLPN_SUOI_HAI"."DS_AN_GIAM" ("PN_ID", "SO_HSLD", "HO_TEN", "MA_GIOI_TINH", "ND_GIOI_TINH", "NAM_SINH", "DC_TT", "MA_TOI_DANH", "ND_TOI_DANH", "NGAY_BAT", "MA_MUC_AN_PHAT", "ND_MUC_AN_PHAT", "NGAY_DEN_TRAI", "MA_PHAN_DOI", "PHAN_DOI", "MA_TRAI_GIAM", "ND_TRAI_GIAM", "NGAY_RA_TRAI", "ND_TINH_TRANG", "MA_TINH_TRANG", "SO_QD", "NGAY_QD", "GHI_CHU") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  (select
a.pn_id,
so_hsld,
