  CREATE OR REPLACE FORCE EDITIONABLE VIEW "QLPN_SUOI_HAI"."DS_TRON_TRAI" ("PN_ID", "SO_HSLD", "HO_TEN", "ND_GIOI_TINH", "NAM_SINH", "DC_TT", "ND_TOI_DANH", "NGAY_BAT", "ND_MUC_AN_PHAT", "NGAY_DEN_TRAI", "MA_PHAN_DOI", "PHAN_DOI", "MA_TRAI_GIAM", "ND_TRAI_GIAM", "NGAY_RA_TRAI", "ND_TINH_TRANG", "MA_TINH_TRANG", "NGAY_TRON", "TRUONG_HOP_TRON", "NOI_TRON", "NGAY_BAT_LAI", "DON_VI_BAT", "TRUONG_HOP_BAT", "HINH_THUC_XL") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  (select
a.pn_id,
so_hsld,
ho_ten,
countma('ma_gioi_tinh',ma_gioi_tinh) nd_gioi_tinh,
to_number(substr(ngay_sinh_pn,length(ngay_sinh_pn)-3)) nam_sinh,
get_dia_chi(dc_tt_thon_pho,dc_tt_phuong_xa,countma('ma_dp',ma_dp_dc_tt))dc_tt,
u_count_mas('ma_toi_danh',ma_toi_danh) nd_toi_danh,
ngay_bat,
countma('ma_muc_thoi_gian',ma_muc_an_phat) nd_muc_an_phat,
ngay_den_trai,
ma_phan_doi,
countma('ma_phan_doi_pn',ma_phan_doi) phan_doi,
ma_trai_giam,
countma('ma_trai_giam',ma_trai_giam)  nd_trai_giam,
ngay_ra_trai,
countma('ma_tinh_trang_pn',ma_tinh_trang)nd_tinh_trang,
ma_tinh_trang,
b.ngay_tron,
countma('ma_th_tron',b.ma_th_tron)truong_hop_tron,
b.noi_tron,
b.ngay_bat_lai,
b.don_vi_bat,
countma('ma_truong_hop_bat',b.ma_th_bat) truong_hop_bat,
countma('ma_htxl_bat',b.ma_htxl_bat)hinh_thuc_xl
FROM pn_lai_lich a, pn_tt_tron_trai b
where a.pn_id=b.pn_id
)

;
