--------------------------------------------------------
--  DDL for View LOV_MA_DP_BAT
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "QLPN_SUOI_HAI"."LOV_MA_DP_BAT" ("MA", "ND") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  select '%' ma,'T?t c?' nd from dual
union
select ma,nd from ma_dp b
where exists (select a.ma_dp_rl_bat from pn_lai_lich a where a.ma_dp_rl_bat=b.ma)
union
select ma,nd from ma_dp b
where ma in (select substr(a.ma_dp_rl_bat,1,3)||'00' from pn_lai_lich a )
;
--------------------------------------------------------
--  DDL for View LOV_MA_DP_QDTHAN
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "QLPN_SUOI_HAI"."LOV_MA_DP_QDTHAN" ("MA", "ND") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  select '%' ma,'T?t c?' nd from dual
union
select ma,nd from ma_dp b
where exists (select a.ma_dp_toa_qd from pn_lai_lich a where a.ma_dp_toa_qd=b.ma)
union
select ma,nd from ma_dp b
where ma in (select substr(a.ma_dp_toa_qd,1,3)||'00' from pn_lai_lich a )
;
--------------------------------------------------------
--  DDL for View LOV_MA_DP_TT
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "QLPN_SUOI_HAI"."LOV_MA_DP_TT" ("MA", "ND") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  select '%' ma,'T?t c?' nd from dual
union
select ma,nd from ma_dp b
where exists (select a.ma_dp_dc_tt from pn_lai_lich a where a.ma_dp_dc_tt=b.ma)
union
select ma,nd from ma_dp b
where exists (select a.ma_dp_dc_ve from pn_lai_lich a where a.ma_dp_dc_ve=b.ma)
union
select ma,nd from ma_dp b
where ma in (select substr(a.ma_dp_dc_tt,1,3)||'00' from pn_lai_lich a )
;
--------------------------------------------------------
--  DDL for View LOV_MA_DP_XA_PHUONG
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "QLPN_SUOI_HAI"."LOV_MA_DP_XA_PHUONG" ("MA", "ND") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  select t.ma ma, t.nd||', '||d.nd nd from ma_dp_xa_phuong t, ma_dp d
where t.ma_qh=d.ma and d.ma_hien_trang='1'
;
--------------------------------------------------------
--  DDL for View LOV_MA_PHAN_DOI
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "QLPN_SUOI_HAI"."LOV_MA_PHAN_DOI" ("MA", "ND") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  select '%' ma,'T?t c?' nd from dual
union
select ma,nd from ma_phan_doi_pn a
where ma in (select ma_phan_doi from pn_lai_lich a where a.ma_tinh_trang like '11%')
union
select b.ma||'%' ma,b.nd from ma_phan_doi_pn a,ma_phan_trai b
where  substr(a.ma,1,3)=b.ma and a.ma in (select ma_phan_doi from pn_lai_lich a where a.ma_tinh_trang like '11%')
;

   COMMENT ON TABLE "QLPN_SUOI_HAI"."LOV_MA_PHAN_DOI"  IS 'Danh m?c phan tr?i, phan d?i'
;
--------------------------------------------------------
--  DDL for View LOV_MA_TINH_TRANG
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "QLPN_SUOI_HAI"."LOV_MA_TINH_TRANG" ("MA", "ND") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  select '%' ma,'T?t c?' nd from dual
union
select ma,nd from ma_tinh_trang_pn a
where ma in (select distinct ma_tinh_trang from pn_lai_lich a )
union
select '11%' ma,'Dang ? tr?i(T?t c?)' nd from dual
union
select '12%' ma,'D? ra tr?i(T?t c?)' nd from dual
;
--------------------------------------------------------
--  DDL for View LOV_MA_TRAI
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "QLPN_SUOI_HAI"."LOV_MA_TRAI" ("MA", "ND") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  select '%' ma,'T?t c?' nd from dual
union
select '10' ma,'TR?I GIAM THU?C BCA' nd from dual
union
select '21' ma,'TR?I T?M GIAM THU?C BCA' nd from dual
union
select '22' ma,'TR?I T?M GIAM THU?C CA T?NH' nd from dual
union
select ma,nd from ma_trai_giam a
where ma in (select distinct ma_trai_giam from pn_lai_lich a )
;
--------------------------------------------------------
--  DDL for View MA_QD_DIEU_CHUYEN
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "QLPN_SUOI_HAI"."MA_QD_DIEU_CHUYEN" ("MA", "ND", "SO_QD_DC", "NGAY_QD_DC", "MA_CQ_DN_DC", "MA_DP_DN_DC") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  select So_Qd_Dc||':'||to_char(ngay_qd_dc,'dd/mm/yy')||'-'||ma_cq_dn_dc||':'||ma_dp_dn_dc ma,
'QD:'||So_Qd_Dc||' ngay '||to_char(ngay_qd_dc,'dd/mm/yy')||'; '||decode(ma_cq_dn_dc,'1','CA',countma('ma_cq',ma_cq_dn_dc))||' '||countma('ma_dp',ma_dp_dn_dc)||'; TS '||ts||' PN' nd,
So_Qd_Dc,
ngay_qd_dc,
ma_cq_dn_dc,
ma_dp_dn_dc
from (
select t.So_Qd_Dc, nvl(t.ngay_qd_dc,'01-JAN-2000') ngay_qd, t.ngay_qd_dc,t.ma_cq_dn_dc, t.ma_dp_dn_dc, count(*) ts from pn_lai_lich t
group by t.So_Qd_Dc, t.ngay_qd_dc, t.ma_cq_dn_dc, t.ma_dp_dn_dc
order by 2 desc)
;
--------------------------------------------------------
--  DDL for View MA_TOI_DANH_TAT
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "QLPN_SUOI_HAI"."MA_TOI_DANH_TAT" ("MA", "ND") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  select ma, get_chucaidau(nd) nd from ma_toi_danh
;
--------------------------------------------------------
--  DDL for View MA_TOI_DANH_TT
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "QLPN_SUOI_HAI"."MA_TOI_DANH_TT" ("MA", "ND") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  select ma ma, nvl(nd_tt,nd) nd from ma_toi_Danh
;
--------------------------------------------------------
--  DDL for View TK_HPBS_TT07
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "QLPN_SUOI_HAI"."TK_HPBS_TT07" ("NAM_NOP", "TONG_SO", "DA_NOP", "CON_LAI") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  (select
to_char(b.ngay_nop,'yyyy') nam_nop,
sum(nvl(tong_tien_phat,0)) tong_so,
sum(nvl(b.so_tien_nop,0))  da_nop,
(sum(nvl(tong_tien_phat,0))-sum(nvl(b.so_tien_nop,0))) con_lai
FROM pn_hpbs_hinh_phat a,pn_hpbs_thuc_hien b
where a.ma_pn_hpbshp=b.ma_pn_hpbshp and b.ma_ghi_chu_hpbs_th is not null
group by to_char(b.ngay_nop,'yyyy')
)
;
