  CREATE OR REPLACE FORCE EDITIONABLE VIEW "QLPN_SUOI_HAI"."V_DS_HS_QUAN_TAM" ("PN_ID", "SO_HSLD", "HO_TEN", "NGAY_BAT", "NGAY_RA_TRAI") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  select pn_id,so_hsld, ho_ten, ngay_bat, ngay_ra_trai from pn_lai_lich where pn_id in (
(select pn_id from pn_lai_lich where ma_tinh_trang like '11%'
minus
select pn_id from pn_lai_lich where pn_get.ma_tinh_trang(pn_id) like '11%')
union
(select pn_id from pn_lai_lich where pn_get.ma_tinh_trang(pn_id) like '11%'
minus
select pn_id from pn_lai_lich where ma_tinh_trang like '11%')
)
;
