  when b.du_dieu_kien_dx>2000 and a.ma_ghi_chu_dx>=900 then 1999
  when b.du_dieu_kien_dx<2000 and a.ma_ghi_chu_dx<900 then  2999
  when countstr(a.ma_toi_danh)>1 then 3130  -- 3 toi tro len
  when nvl(a.so_tien_an,0)>0 and instr(u_count_mas('ma_toi_danh',a.ma_toi_danh),'V? ?')=0 then 3140 -- Muc 3p
  when get_thang(a.ma_muc_an_phat)>=7*12 and getstr(a.ma_toi_danh,1)
        in ('133','133x','133z','136','136x','136y','134','193','194','194c','194d','194e','194f','194g','194i','195') then 3090 -- Muc 3i
  when get_thang(a.ma_muc_an_phat)>=10*12 and d.ma_chuong='12' then 3080 -- Muc 3h
  when instr(pn_dx.get_chuoi_xlct_dx_quy(a.pn_id,para_ngay_dac_xa),'C')>0 then 2280 -- Trung binh
  when instr(pn_dx.get_chuoi_xlct_dx_quy(a.pn_id,para_ngay_dac_xa),'D')>0 then 2280 -- Kem
  when instr(pn_dx.get_chuoi_xlct_dx_quy(a.pn_id,para_ngay_dac_xa),'E')>0 then 2280 -- Khong xep loai
else b.du_dieu_kien_dx
end) du_dieu_kien_dx
from pn_lai_lich a,pn_ky_dac_xa b, ma_trai_giam c,ma_toi_danh d
where a.pn_id=b.pn_id
and a.ma_trai_giam=c.ma
and getstr(a.ma_toi_danh,1)=d.ma
;
