  CREATE OR REPLACE FORCE EDITIONABLE VIEW "QLPN_SUOI_HAI"."V_HPBS_GON" ("PN_ID", "MA_HINH_PHAT", "HINH_PHAT_BS", "NOI_DUNG_PHAT", "TONG_TIEN_PHAT", "MA_MUC_THOI_HAN", "MUC_THOI_HAN", "MA_HE_SO_TIEN", "HE_SO_TIEN", "GHI_CHU_HPBS", "SO_TIEN_NOP") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  (select
b.pn_id                                                pn_id,
b.ma_hinh_phat                                          ma_hinh_phat,
countma('ma_hinh_phat_bs',b.ma_hinh_phat)                 hinh_phat_bs,
b.noi_dung_phat                                           noi_dung_phat,
b.tong_tien_phat                                          tong_tien_phat,
b.ma_muc_thoi_han,
countma('ma_muc_thoi_gian',ma_muc_thoi_han)               muc_thoi_han,
b.ma_he_so_tien,
countma('ma_he_so_tien',b.ma_he_so_tien)                  he_so_tien,
ghi_chu_hpbs_hp                                           ghi_chu_hpbs,
(select sum(so_tien_nop) from pn_hpbs_thuc_hien where ma_pn_hpbshp=b.ma_pn_hpbshp) so_tien_nop
FROM pn_hpbs_hinh_phat b
)
;
--------------------------------------------------------
--  DDL for View V_HPBS_THUC_HIEN
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "QLPN_SUOI_HAI"."V_HPBS_THUC_HIEN" ("PN_ID", "MA_HINH_PHAT", "HINH_PHAT_BS", "TONG_TIEN_PHAT", "HE_SO_TIEN", "NOP_TIEN", "NOP_TIEN_TRUOC", "NOP_TIEN_SAU", "CON_LAI", "GHI_CHU_HPBS") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  select l.pn_id,
      ma_hinh_phat,
      countma('ma_hinh_phat_bs',ma_hinh_phat) hinh_phat_bs,
      tong_tien_phat,
      decode(ma_he_so_tien,'10','d?ng',countma('ma_he_so_tien',ma_he_so_tien)) he_so_tien,
      (select sum(nvl(so_tien_nop,0)) from pn_hpbs_thuc_hien c
           where c.ma_pn_hpbshp=b.ma_pn_hpbshp
             group by ma_pn_hpbshp) nop_tien,
      (select sum(nvl(so_tien_nop,0)) from pn_hpbs_thuc_hien c
           where c.ma_pn_hpbshp=b.ma_pn_hpbshp and nvl(c.ngay_nop,sysdate)<l.ngay_den_trai
             group by ma_pn_hpbshp) nop_tien_truoc,
      (select sum(nvl(so_tien_nop,0)) from pn_hpbs_thuc_hien d
           where d.ma_pn_hpbshp=b.ma_pn_hpbshp and nvl(d.ngay_nop,sysdate)>=l.ngay_den_trai
             group by ma_pn_hpbshp) nop_tien_sau,
      tong_tien_phat-nvl((select nvl(sum(nvl(so_tien_nop,0)),0) from pn_hpbs_thuc_hien c
           where c.ma_pn_hpbshp=b.ma_pn_hpbshp
             group by ma_pn_hpbshp),0) con_lai,
      decode(ghi_chu_hpbs_hp,null,null,' '||ghi_chu_hpbs_hp) ghi_chu_hpbs
from pn_hpbs_hinh_phat b, pn_lai_lich l
where b.pn_id=l.pn_id and b.ma_hinh_phat like '2%'
;
