--------------------------------------------------------
--  DDL for View V_PN_DU_DK_GTH
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "QLPN_SUOI_HAI"."V_PN_DU_DK_GTH" ("PN_ID") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  (
(
select a.pn_id
from pn_lai_lich a, pn_ket_qua_cai_tao b
where a.pn_id=b.pn_id
and a.ma_tinh_trang='111' and get_thang(pn_get.ma_tg_chap_hanh(a.pn_id,para_ngay_xet_giam))>=(get_thang(ma_muc_an_phat)/3)
and nvl(b.ma_xep_loai_q4,nvl(b.ma_xep_loai_q3,nvl(b.ma_xep_loai_q2,b.ma_xep_loai_q1))) in ('110','120')
and get_thang(ma_muc_an_phat)<3*12
and to_char(b.nam_xl)=to_char(para_ngay_xet_giam,'yyyy')
union all
select a.pn_id
from pn_lai_lich a, pn_ket_qua_cai_tao b
where a.pn_id=b.pn_id
and a.ma_tinh_trang='111' and get_thang(pn_get.ma_tg_chap_hanh(a.pn_id,para_ngay_xet_giam))>=(get_thang(ma_muc_an_phat)/3)
and nvl(b.ma_xep_loai_cuoi,b.ma_xep_loai_dau) in ('110','120')
and get_thang(ma_muc_an_phat) between 4*12 and 5*12
and to_char(b.nam_xl)=to_char(para_ngay_xet_giam,'yyyy')
union all
select a.pn_id
from pn_lai_lich a, pn_ket_qua_cai_tao b
where a.pn_id=b.pn_id
and a.ma_tinh_trang='111' and get_thang(pn_get.ma_tg_chap_hanh(a.pn_id,para_ngay_xet_giam))>=(get_thang(ma_muc_an_phat)/3)
and b.ma_xep_loai_ca in ('110','120')
and get_thang(ma_muc_an_phat) between 6*12 and 10*12
and to_char(b.nam_xl)=to_char(para_ngay_xet_giam,'yyyy')
union all
select a.pn_id
from pn_lai_lich a, pn_ket_qua_cai_tao b
where a.pn_id=b.pn_id
and a.ma_tinh_trang='111' and get_thang(pn_get.ma_tg_chap_hanh(a.pn_id,para_ngay_xet_giam))>=(get_thang(ma_muc_an_phat)/3)
and b.ma_xep_loai_ca in ('110','120')
and get_thang(ma_muc_an_phat) between 11*12 and 15*12
and to_number(to_char(b.nam_xl)) between to_number(to_char(para_ngay_xet_giam,'yyyy')) and to_number(to_char(sysdate,'yyyy'))+1
union all
select a.pn_id
from pn_lai_lich a, pn_ket_qua_cai_tao b
where a.pn_id=b.pn_id
and a.ma_tinh_trang='111' and get_thang(pn_get.ma_tg_chap_hanh(a.pn_id,para_ngay_xet_giam))>=(get_thang(ma_muc_an_phat)/3)
and b.ma_xep_loai_ca in ('110','120')
and get_thang(ma_muc_an_phat) between 16*12 and 30*12
and to_number(to_char(b.nam_xl)) between to_number(to_char(para_ngay_xet_giam,'yyyy')) and to_number(to_char(sysdate,'yyyy'))+2
union all
select a.pn_id
from pn_lai_lich a, pn_ket_qua_cai_tao b
where a.pn_id=b.pn_id
and a.ma_tinh_trang='111' and get_thang(pn_get.ma_tg_chap_hanh(a.pn_id,sysdate))>=(get_thang(ma_muc_an_phat)/3)
and b.ma_xep_loai_ca in ('110','120')
and ma_muc_an_phat='911000'
and to_number(to_char(b.nam_xl)) between to_number(to_char(para_ngay_xet_giam,'yyyy')) and to_number(to_char(para_ngay_xet_giam,'yyyy'))+3
)
minus
select pn_id from pn_giam_thoi_han where ngay_xet>=(select min(ngay_xet) from (select distinct ngay_xet from pn_giam_thoi_han order by ngay_xet desc) where rownum<3)
)

;
--------------------------------------------------------
--  DDL for View V_PN_KQCT_DOC
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "QLPN_SUOI_HAI"."V_PN_KQCT_DOC" ("PN_ID", "NAM_XL", "TT", "NGAY_XL", "KY_XL", "KY_XEP_LOAI", "KY", "MA_XEP_LOAI", "XL", "XEP_LOAI") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  select pn_id,nam_xl,1 TT,to_date('25-FEB-'||to_char(nam_xl)) ngay_xl,'Q1' KY_XL, ' Quy 1' KY_XEP_LOAI,' Q1' KY,
decode(MA_XEP_LOAI_Q1,'110','A','120','B','130','C','140','D','E') MA_XEP_LOAI,
countma('ma_xep_loai',MA_XEP_LOAI_Q1) xl, countma('ma_xep_loai_cai_tao',MA_XEP_LOAI_Q1) xep_loai
from PN_KET_QUA_CAI_TAO where MA_XEP_LOAI_Q1 is not null
union all
select pn_id,nam_xl,2 TT,to_date('25-MAY-'||to_char(nam_xl)) ngay_xl,'Q2' KY_XL,  ' Quy 2' KY_XEP_LOAI,' Q2' KY,
decode(MA_XEP_LOAI_Q2,'110','A','120','B','130','C','140','D','E') MA_XEP_LOAI ,
countma('ma_xep_loai',MA_XEP_LOAI_Q2) xl , countma('ma_xep_loai_cai_tao',MA_XEP_LOAI_Q2) xep_loai
from PN_KET_QUA_CAI_TAO where MA_XEP_LOAI_Q2 is not null
