--------------------------------------------------------
--  DDL for View V_TK_TIEN_HPBS
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "QLPN_SUOI_HAI"."V_TK_TIEN_HPBS" ("MA_HINH_PHAT", "SUM_TRUOC_KHI_XU", "SUM_SAU_KHI_XU", "SUM_KHI_CHAPT") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  select ma_hinh_phat,sum(sum_truoc_khi_xu) sum_truoc_khi_xu,sum(sum_sau_khi_xu) sum_sau_khi_xu,sum(sum_khi_chapt) sum_khi_chapt
from
(
select
ma_hinh_phat,
sum(so_tien_nop) sum_truoc_khi_xu,
0                sum_sau_khi_xu,
0                sum_khi_chapt
from pn_hpbs_hinh_phat a,pn_hpbs_thuc_hien b, pn_lai_lich c
where a.pn_id=c.pn_id and a.ma_pn_hpbshp=b.ma_pn_hpbshp and b.ngay_nop>c.ngay_xu
group by ma_hinh_phat
union all
select
ma_hinh_phat,
0                sum_truoc_khi_xu,
sum(so_tien_nop) sum_sau_khi_xu,
0                sum_khi_chapt
from pn_hpbs_hinh_phat a,pn_hpbs_thuc_hien b, pn_lai_lich c
where a.pn_id=c.pn_id and a.ma_pn_hpbshp=b.ma_pn_hpbshp and b.ngay_nop<=c.ngay_xu
group by ma_hinh_phat
union all
select
ma_hinh_phat,
0                sum_truoc_khi_xu,
0                sum_sau_khi_xu,
sum(so_tien_nop)  sum_khi_chapt
from pn_hpbs_hinh_phat a,pn_hpbs_thuc_hien b, pn_lai_lich c
where a.pn_id=c.pn_id and a.ma_pn_hpbshp=b.ma_pn_hpbshp and b.ngay_nop<=c.ngay_den_trai
group by ma_hinh_phat)
group by ma_hinh_phat

;
--------------------------------------------------------
--  DDL for View V_TK_TONG_HOP
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "QLPN_SUOI_HAI"."V_TK_TONG_HOP" ("STT", "TEN_TK", "TS", "FRM") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  select STT, ten_tk, ts,frm from
(
select 1 STT,' 1. Dang ch?p hanh an' ten_tk, count(*) ts, 'DS_CHAP_HANH' frm from pn_lai_lich t where t.ma_tinh_trang in ('111','112')
union
select 2 STT,'    Trong do giam rieng' ten_tk, count(distinct pn_id) ts,'DS_GIAM_RIENG' frm from ds_giam_rieng where ma_tinh_trang like '112'
union
select 3 STT,' 2. B?t bu?c ch?a b?nh' ten_tk, count(*) ts,'DS_CHUA_BENH' frm from ds_chua_benh_bat_buoc a where ma_tinh_trang like '113'
union
select 4 STT,' 3. Trich xu?t ch?a tr? l?i' ten_tk, count(*) ts,'DS_TRICH_XUAT_DI' frm from ds_trich_xuat_di
where ngay_tra_lai is null and ma_tinh_trang in ('141','142') and ma_lenh_tx='1'
union
select 5 STT,' 4. T?m dinh ch? ch?a tr? l?i' ten_tk, count(*) ts,'DS_TAM_DINH_CHI' frm from ds_tam_dinh_chi tdc
where ma_tinh_trang in ('151','152','157') and tdc.ma_lenh_tdc='1'
union
select 6 STT,' 5. Tha tr??c th?i h?n cdk' ten_tk, count(*) ts, 'danh_sach_tha_co_dk' frm from pn_lai_lich where ma_tinh_trang='126'
union
select 7 STT,' 6. Ra tr?i hom nay' ten_tk, count(*) ts, 'DS_DA_RA_TRAI' frm from pn_lai_lich where ngay_ra_trai=trunc(sysdate)
union
select 8 STT,' 7. Ra tr?i hom sau' ten_tk, count(*) ts, 'TB_NGAY_CHXHPT' frm from pn_lai_lich
where ngay_ra_trai=trunc(sysdate+1) and ma_tinh_trang like '11%'
union
select 9 STT,' 8. Ra tr?i tr??c 2 thang' ten_tk, count(*) ts, 'TB_NGAY_CHXHPT' frm from pn_lai_lich where ngay_ra_trai
between trunc(sysdate+1) and add_months(trunc(sysdate+1),+2) and ma_tinh_trang in ('111','112')
union
select 10 STT,' 9. D??c d?c xa' ten_tk, count(*) ts, 'DS_DAC_XA' frm from pn_lai_lich where ma_tinh_trang='123'
union
select 11 STT,' 10. Chuy?n tr?i khac' ten_tk, count(*) ts,'DS_CHUYEN_TRAI' frm from ds_chuyen_trai
union
select 12 STT,' 11. Ch?t trong nam' ten_tk, count(*) ts,'DS_CHET' frm from ds_chet c
       where c.ngay_chet>=trunc(sysdate,'YYYY') and to_number(nvl(c.ma_th_chet,'00'))<=21
union
select 13 STT,' 12. Tr?n ch?a b?t l?i ' ten_tk, count(*) ts,'DS_TRON_TRAI' frm from ds_tron_trai where ngay_bat_lai is null
union
select 14 STT,' 13. H?y an' ten_tk, count(*) ts,'DS_HUY_AN' frm from ds_huy_an where ngay_tra_tudo is not null
union
select 15 STT,' 14. Mi?n hinh ph?t' ten_tk, count(*) ts,'DS_MIEN_HINH_PHAT' frm from ds_mien_hinh_phat where ngay_tra_tu_do is not null
union
select 16 STT,' 15. Ho?n thi hanh an' ten_tk, count(*) ts,'DS_HOAN_THI_HANH_AN' frm from ds_hoan_thi_hanh_an
union
select 17 STT,' 16. Ph?m t?i m?i ' ten_tk, count(*) ts,'DS_PHAM_TOI_MOI' frm from ds_pham_toi_moi
union
select 18 STT,' 17. An gi?m' ten_tk, count(*) ts, 'DS_AN_GIAM' frm from ds_an_giam
union
select 19 STT,' 18. Sinh nh?t hom sau' ten_tk, count(*) ts, 'DS_PN_SINH_NHAT' frm from pn_lai_lich
where substr(ngay_sinh_pn,1,5) like to_char(to_date(sysdate)+1,'dd/mm') and ma_tinh_trang like '11%'
)
;
