         decode(b.ma_xep_loai_q2,null,null,'Q2:'||countma('ma_xep_loai',b.ma_xep_loai_q2)||'; '),
         'DN:'||countma('ma_xep_loai',b.ma_xep_loai_dau)||'; ')||
decode(b.ma_xep_loai_cuoi,null,
         decode(b.ma_xep_loai_q3,null,null,'Q3:'||countma('ma_xep_loai',b.ma_xep_loai_q3)||';')||
         decode(b.ma_xep_loai_q4,null,null,'Q4:'||countma('ma_xep_loai',b.ma_xep_loai_q4)||';'),
         'CN:'||countma('ma_xep_loai',b.ma_xep_loai_cuoi)||'; ')||
decode(b.ma_xep_loai_ca,null,null,'C? nam:'||countma('ma_xep_loai',b.ma_xep_loai_ca)) xep_loai_gon,
dieu_kien_xlct,
a.ma_quoc_tich,
a.co_quan_bao_tin_khac
FROM pn_lai_lich a, pn_ket_qua_cai_tao b
where a.pn_id=b.pn_id)
;
