--  DDL for Procedure COMPILE_OBJECTS
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN_SUOI_HAI"."COMPILE_OBJECTS" is
 cCount number;
 ---
 procedure dich is
 begin
  for obj in (select object_name,object_type
  	from user_objects
  		where OBJECT_TYPE in ('FUNCTION','PROCEDURE','VIEW') and status='INVALID')
  loop
  	execute immediate 'alter '||obj.object_type||' '||obj.object_name||' compile';
  end loop;
 end;
 ---
Begin
	loop
		dich;
	  select count(*) into cCount from user_objects where OBJECT_TYPE in ('FUNCTION','PROCEDURE','VIEW') and status='INVALID';
	  if cCount=0 then
	  	exit;
	  end if;
	end loop;
End;

