--------------------------------------------------------
--  DDL for Procedure CONVERT_PHAN_LOAI
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN_SUOI_HAI"."CONVERT_PHAN_LOAI" is
v_loai varchar2(100);
function get_tu_phan_loai(v_pn_id varchar2,v_ngay_phan_loai date)  return varchar2 is
v_ma_pl varchar2(50);
begin
	  select v_tu.ma_den_loai into v_ma_pl
	  	from  pn_phan_loai_giam_giu v_tu,pn_phan_loai_giam_giu v_den
  			where v_tu.pn_id=v_den.pn_id
  				and v_den.pn_id=v_pn_id
  				 and v_den.ngay_phan_loai=v_ngay_phan_loai
  				  and v_tu.ngay_phan_loai<v_den.ngay_phan_loai
  					 and v_tu.ngay_phan_loai=
  					 	(select max(ngay_phan_loai)
  					 		from pn_phan_loai_giam_giu k where pn_id=v_pn_id and k.ngay_phan_loai<v_den.ngay_phan_loai) ;
     return v_ma_pl;
exception
	when no_data_found then return null;
	when others then return null;
end;
Begin
  update pn_phan_loai_giam_giu set ma_den_loai=ma_phan_loai;
  update pn_phan_loai_giam_giu set ngay_phan_loai=ngay_bien_ban;
  update pn_phan_loai_giam_giu a set ma_loai_phan_loai=1
  	where ngay_phan_loai=(select min(ngay_phan_loai) from pn_phan_loai_giam_giu where pn_id=a.pn_id);
  --
  -- Update ma phan loai tu
  --
  update pn_phan_loai_giam_giu set ma_tu_loai=null where ma_loai_phan_loai=1;
  for obj in (select * from pn_phan_loai_giam_giu where ngay_phan_loai is not null) loop
  	v_loai:=get_tu_phan_loai(obj.pn_id,obj.ngay_phan_loai);
  	update pn_phan_loai_giam_giu set ma_tu_loai=v_loai
  	where pn_id=obj.pn_id and ngay_phan_loai=obj.ngay_phan_loai and ngay_phan_loai is not null ;
  end loop;
  --
  -- Update nang loai
  --
  update pn_phan_loai_giam_giu set ma_loai_phan_loai=2 where ma_den_loai<ma_tu_loai;
  --
  -- Update ha loai
  --
  update pn_phan_loai_giam_giu set ma_loai_phan_loai=3 where ma_den_loai>ma_tu_loai;
  --
  -- Update giu loai
  --
  update pn_phan_loai_giam_giu set ma_loai_phan_loai=4 where ma_den_loai=ma_tu_loai;
 commit;
end;


