--------------------------------------------------------
--  DDL for Procedure CREATEJOB_BACKUP_EXP
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN_SUOI_HAI"."CREATEJOB_BACKUP_EXP" (jobname varchar2,
                                                 jobaction varchar2,
                                                 userid varchar2,
                                                 vbyhour varchar2 default '0',
                                                 vbyminute varchar2 default '0',
                                                 vbysecond varchar2 default '0') is
BEGIN
begin
DBMS_SCHEDULER.DROP_JOB (jobname);
exception
when others then null;
end;
DBMS_SCHEDULER.CREATE_JOB(
   job_name             => jobname,
   job_type             => 'EXECUTABLE',
   number_of_arguments  => 3,
   job_action           => jobaction,
   repeat_interval      => 'FREQ=DAILY; BYHOUR='||vbyhour||'; byminute='||vbyminute||'; bysecond='||vbysecond||';',
   auto_drop            => FALSE);
DBMS_SCHEDULER.SET_JOB_ARGUMENT_VALUE(jobname,1,userid);
DBMS_SCHEDULER.SET_JOB_ARGUMENT_VALUE(jobname,2,'qlcp');
DBMS_SCHEDULER.SET_JOB_ARGUMENT_VALUE(jobname,3,'qlcp_job');
DBMS_SCHEDULER.ENABLE(jobname);
END;

/
--------------------------------------------------------
--  DDL for Procedure CREATEJOB_DATA_BACKUP_EXP
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN_SUOI_HAI"."CREATEJOB_DATA_BACKUP_EXP" is
ma_trai varchar2(10):=get_tham_so('MA_TRAI');
BEGIN
begin
DBMS_SCHEDULER.DROP_JOB ('DATA_EXPORT');
exception
when others then null;
end;
DBMS_SCHEDULER.CREATE_JOB(
   job_name             => 'DATA_EXPORT',
   job_type             => 'EXECUTABLE',
   number_of_arguments  => 3,
   job_action           => 'C:\Windows\system32\cmd.exe /c E:\QLPN\Forms\backup_exp.bat',
   repeat_interval      => 'FREQ=DAILY; BYHOUR=15; byminute=0; bysecond=0;',
   auto_drop            => FALSE);
DBMS_SCHEDULER.SET_JOB_ARGUMENT_VALUE('DATA_EXPORT',1,'QLPN/QLPN@TC8');
DBMS_SCHEDULER.SET_JOB_ARGUMENT_VALUE('DATA_EXPORT',2,'QLPN');
DBMS_SCHEDULER.SET_JOB_ARGUMENT_VALUE('DATA_EXPORT',3,'QLPN_'||ma_trai||'_DATA_Job');
DBMS_SCHEDULER.ENABLE('DATA_EXPORT');
END;

