--------------------------------------------------------
--  DDL for Procedure CREATEJOB_DON_DL
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN_SUOI_HAI"."CREATEJOB_DON_DL" (v_mahieutrai varchar2) is
BEGIN
begin
DBMS_SCHEDULER.DROP_JOB ('DON_DL_'||v_mahieutrai);
exception
when others then null;
end;

sys.dbms_scheduler.create_job(
job_name => 'DON_DL_'||v_mahieutrai,
job_type => 'PLSQL_BLOCK',
job_action => 'begin
   pn_tdl.all_tab('''||v_mahieutrai||''');
end;',
start_date => sysdate+1/1440,
job_class => 'DEFAULT_JOB_CLASS',
auto_drop => FALSE,
enabled => FALSE);
sys.dbms_scheduler.set_attribute( name => 'DON_DL_'||v_mahieutrai, attribute => 'logging_level', value => DBMS_SCHEDULER.LOGGING_OFF);
sys.dbms_scheduler.set_attribute( name => 'DON_DL_'||v_mahieutrai, attribute => 'job_weight', value => 1);
sys.dbms_scheduler.enable('DON_DL_'||v_mahieutrai);
END;

