--------------------------------------------------------
--  DDL for Procedure DISABLE_CONSTRAINT
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN_SUOI_HAI"."DISABLE_CONSTRAINT" (Flag varchar2) IS
  i number:=0;
  ddl_str varchar2(200);
  dml_str varchar2(200);
Begin
  for obj in (select distinct a.table_name table_name, a.constraint_name contraint_name 
  							from user_constraints a,user_constraints b
									where b.constraint_name=a.r_constraint_name
										and a.constraint_type='R'
											and b.table_name='TV_TRAI_VIEN')
	loop
		if Flag='OFF' then
			ddl_str:='alter table '||obj.table_name||' disable constraint '||obj.contraint_name;
			execute immediate ddl_str;
		end if;
		if Flag='ON' then
			ddl_str:='alter table '||obj.table_name||' enable constraint '||obj.contraint_name;
			execute immediate ddl_str;
		end if;
	end loop;
End;

/
--------------------------------------------------------
--  DDL for Procedure DISABLE_TRIGGER
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN_SUOI_HAI"."DISABLE_TRIGGER" (vFlag varchar2 default 'ON') IS
  ddl_str varchar2(2000);
BEGIN
  for obj in (select trigger_name from user_triggers where table_name is not null)
  loop
  	if vFlag = 'ON' then
  		ddl_str:='alter trigger '||obj.trigger_name||' enable';
  	else
  		ddl_str:='alter trigger '||obj.trigger_name||' disable';
  	end if;
  	execute immediate ddl_str;
  end loop;
exception
  when no_data_found then null;		
END;

