--------------------------------------------------------
--  DDL for Procedure DONG_BO_DATA
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN_SUOI_HAI"."DONG_BO_DATA" is
Begin
  --
  -- Dong bo bang lai lich
  --
  update pn_lai_lich set ma_tinh_trang='100' where substr(ma_tinh_trang,1,1) in ('2','3');
  update pn_lai_lich set ma_gioi_tinh='1' where ma_gioi_tinh is null;
  update pn_lai_lich set ma_dan_toc='1' where ma_dan_toc is null;
	update pn_lai_lich set chi_tiet_hv=tom_tat_hv where chi_tiet_hv is null;
	update pn_lai_lich a
		set ghi_chu_cac_con =(select ghi_chu_qhgd
															from pn_quan_he_gia_dinh
																where pn_id=a.pn_id and bo_dau(ho_ten_qhgd)='CACCON' and rownum<2)
  	where ghi_chu_cac_con is null;
  update pn_lai_lich set ma_tai_pham='0' where ma_tai_pham is null;
	update pn_lai_lich set ma_nghe_nghiep=99 where ma_nghe_nghiep not in  (select ma from ma_nghe_nghiep);
	update pn_lai_lich set ma_phan_doi='99999' where ma_phan_doi is null;
	update pn_gr_giam_rieng set ma_lenh_giam_rieng=1 where ma_lenh_giam_rieng is null;
	update pn_lai_lich set order_ho_ten=order_hoten(ho_ten) where order_ho_ten is null;
	--
	-- Dong bo lai ket qua cai tao
	--
  update pn_ket_qua_cai_tao set ma_xep_loai_q1='110' where ma_xep_loai_q1='210';
  update pn_ket_qua_cai_tao set ma_xep_loai_q1='120' where ma_xep_loai_q1='220';
  update pn_ket_qua_cai_tao set ma_xep_loai_q1='130' where ma_xep_loai_q1='230';
  update pn_ket_qua_cai_tao set ma_xep_loai_q1='140' where ma_xep_loai_q1='240';

  update pn_ket_qua_cai_tao set ma_xep_loai_q2='110' where ma_xep_loai_q2='210';
  update pn_ket_qua_cai_tao set ma_xep_loai_q2='120' where ma_xep_loai_q2='220';
  update pn_ket_qua_cai_tao set ma_xep_loai_q2='130' where ma_xep_loai_q2='230';
  update pn_ket_qua_cai_tao set ma_xep_loai_q2='140' where ma_xep_loai_q2='240';


  update pn_ket_qua_cai_tao set ma_xep_loai_dau='110' where ma_xep_loai_dau='210';
  update pn_ket_qua_cai_tao set ma_xep_loai_dau='120' where ma_xep_loai_dau='220';
  update pn_ket_qua_cai_tao set ma_xep_loai_dau='130' where ma_xep_loai_dau='230';
  update pn_ket_qua_cai_tao set ma_xep_loai_dau='140' where ma_xep_loai_dau='240';

  update pn_ket_qua_cai_tao set ma_xep_loai_q3='110' where ma_xep_loai_q3='210';
  update pn_ket_qua_cai_tao set ma_xep_loai_q3='120' where ma_xep_loai_q3='220';
  update pn_ket_qua_cai_tao set ma_xep_loai_q3='130' where ma_xep_loai_q3='230';
  update pn_ket_qua_cai_tao set ma_xep_loai_q3='140' where ma_xep_loai_q3='240';

  update pn_ket_qua_cai_tao set ma_xep_loai_q4='110' where ma_xep_loai_q4='210';
  update pn_ket_qua_cai_tao set ma_xep_loai_q4='120' where ma_xep_loai_q4='220';
  update pn_ket_qua_cai_tao set ma_xep_loai_q4='130' where ma_xep_loai_q4='230';
  update pn_ket_qua_cai_tao set ma_xep_loai_q4='140' where ma_xep_loai_q4='240';


  update pn_ket_qua_cai_tao set ma_xep_loai_cuoi='110' where ma_xep_loai_cuoi='210';
  update pn_ket_qua_cai_tao set ma_xep_loai_cuoi='120' where ma_xep_loai_cuoi='220';
  update pn_ket_qua_cai_tao set ma_xep_loai_cuoi='130' where ma_xep_loai_cuoi='230';
  update pn_ket_qua_cai_tao set ma_xep_loai_cuoi='140' where ma_xep_loai_cuoi='240';

  update pn_ket_qua_cai_tao set ma_xep_loai_ca='110' where ma_xep_loai_ca='210';
  update pn_ket_qua_cai_tao set ma_xep_loai_ca='120' where ma_xep_loai_ca='220';
  update pn_ket_qua_cai_tao set ma_xep_loai_ca='130' where ma_xep_loai_ca='230';
  update pn_ket_qua_cai_tao set ma_xep_loai_ca='140' where ma_xep_loai_ca='240';

  delete pn_ket_qua_cai_tao where	ma_xep_loai_q1 is null and ma_xep_loai_q2 is null	and ma_xep_loai_dau is null
	and ma_xep_loai_q3 is null and ma_xep_loai_q4 is null	and ma_xep_loai_cuoi is null and ma_xep_loai_ca is null;

	--
	-- Tam dinh chi
	--
	update pn_tdc_tam_dinh_chi set ngay_de_nghi=ngay_qd where ngay_de_nghi is null;

	update pn_tdc_tam_dinh_chi set ma_lenh_tdc=1 where ma_lenh_tdc is null;

	update pn_tdc_tam_dinh_chi  set 	ngay_de_nghi=ngay_qd where ngay_de_nghi is null;

	update pn_tdc_tam_dinh_chi tdc set tdc.ma_lenh_tdc='1' where tdc.ma_lenh_tdc is null;

	update pn_tdc_tam_dinh_chi tdc
	set tdc.ma_tinh_trang_tdc='30'
	where  tdc.pn_id in
	       (select a.pn_id from pn_pnc_chet a, pn_tdc_tam_dinh_chi b where a.pn_id=b.pn_id)
	and tdc.ma_lenh_tdc='1' and tdc.ngay_qd=(select max(ngay_qd) from pn_tdc_tam_dinh_chi c where c.pn_id=tdc.pn_id and ma_lenh_tdc='1')
	and tdc.ngay_lai is null;

	Update pn_tdc_tam_dinh_chi set  ngay_tdc=tu_ngay where ngay_tdc is null;
	--
	-- Trich xuat
	--
	update pn_tx_trich_xuat set ma_lenh_tx=1 where ma_lenh_tx is null;

	update pn_tx_trich_xuat set ma_cq_tx_ve=ma_cq_dn_tx where ma_cq_tx_ve is null;

	update pn_tx_trich_xuat set ma_dp_tx_ve=ma_dp_dn_tx where ma_dp_tx_ve is null;

	update pn_tx_trich_xuat set ma_lenh_tx='1' where ma_lenh_tx is null;

	update pn_tx_trich_xuat tx
	set tx.ma_tinh_trang_tx='40'
	where  tx.pn_id in
	       (select a.pn_id from pn_pnc_chet a, pn_tx_trich_xuat b where a.pn_id=b.pn_id)
	and tx.ma_lenh_tx='1' and tx.ngay_lenh_tx=(select max(ngay_lenh_tx) from pn_tx_trich_xuat c where c.pn_id=tx.pn_id and ma_lenh_tx='1')
	and tx.ngay_tra_lai is null;

	update pn_tx_trich_xuat tx --	-- Trich xuat chap hanh xong
  set tx.ma_tinh_trang_tx='90'
  where  tx.pn_id in
         (select a.pn_id from pn_tx_trich_xuat a, pn_ra_trai b where a.pn_id=b.pn_id and a.ngay_tra_lai is null)
  and tx.ngay_lenh_tx=(select max(ngay_lenh_tx) from pn_tx_trich_xuat c where c.pn_id=tx.pn_id)
  and tx.ngay_tra_lai is null;

	update pn_tx_trich_xuat tx -- Trich xuat dac xa
  set tx.ma_tinh_trang_tx='80'
  where  tx.pn_id in
         (select a.pn_id from pn_tx_trich_xuat a, pn_dx_dac_xa b where a.pn_id=b.pn_id and a.ngay_tra_lai is null)
  and tx.ngay_lenh_tx=(select max(ngay_lenh_tx) from pn_tx_trich_xuat c where c.pn_id=tx.pn_id)
  and tx.ngay_tra_lai is null;
  if  upper(bo_dau(para_don_vi_thuong))='TRAITAMGIAM' then
  	update pn_lai_lich set ma_phan_doi='99900' where ma_phan_doi='99999';
  end if;
	--
	--Giam thoi han
	--
	Update pn_giam_thoi_han set ma_muc_dn_giam_v26=ma_muc_dn_giam_tg where ma_muc_dn_giam_v26 is null;

	Update pn_giam_thoi_han set ma_muc_qd_giam_toa_an='000000' where ma_muc_qd_giam_toa_an is null;

	Update pn_giam_thoi_han set ngay_xet=ngay_qd_giam where ngay_xet is null and ngay_qd_giam is not null;
	--
	-- dong bo HPBS
	--
	Dong_Bo_HPBS;
	--
	-- Ra trai
	--
	delete s_update_ratrai where trunc(ngay_cap_nhat)=trunc(sysdate);
	--
	-- Khen thuong
	--
  update pn_khen_thuong a set a.ngay_de_nghi=a.ngay_khen where ngay_de_nghi is null;

	--
	-- Dong bo mo ky
	--
	update pn_open_dot_dac_xa set action='open' where action is null;
	update pn_open_ky_xep_loai set action='open' where action is null;
	update pn_open_ky_giam_thoi_han set action='open' where action is null;
  --
	-- Dong bo bang ma
	--
  Delete ma_tinh_trang_pn where substr(ma,1,1) in ('2','3');

  Delete ma_xep_loai_cai_tao where ma in ('210','220','230','240');

	Syn_Bang_Ma;

	Update_NdBlank_Bangma;


  Commit;
end;

