  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN_SUOI_HAI"."GET_NGUOI_THAN" (v_pn_id varchar2,v_ho_ten out varchar2,v_dia_chi out varchar2) is
begin
 select ho_ten_qhgd,noi_o
 	into v_ho_ten,v_dia_chi
