--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN_SUOI_HAI"."PUT_DIEU_KIEN_TIM_KIEM" (strSQL varchar2) is
cCount number;
Begin
	select count(*) into cCount from pn_tim_kiem;
	if cCount=0 then
		execute immediate 'insert into pn_tim_kiem(pn_id) select pn_id from pn_lai_lich where pn_id in ('||strSQL||')';
	else
		execute immediate 'delete pn_tim_kiem where pn_id not in ('||strSQL||')';
	end if;
	commit;
End;

