--------------------------------------------------------
--  DDL for Procedure SYN_BANG_MA
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN_SUOI_HAI"."SYN_BANG_MA" is
str varchar2(1000):='';
i number;
v_stt number:=0;
Begin
--
-- Dong bo bang ma tinh trang tam dinh chi
--
update pn_tdc_tam_dinh_chi a set a.ma_tinh_trang_tdc='10' where a.ma_tinh_trang_tdc is null;
update pn_tdc_tam_dinh_chi a set a.ma_tinh_trang_tdc='20' where a.ma_tinh_trang_tdc='54';
update pn_tdc_tam_dinh_chi a set a.ma_tinh_trang_tdc='30' where a.ma_tinh_trang_tdc='51';
update pn_tdc_tam_dinh_chi a set a.ma_tinh_trang_tdc='40' where a.ma_tinh_trang_tdc='52';
update pn_tdc_tam_dinh_chi a set a.ma_tinh_trang_tdc='50' where a.ma_tinh_trang_tdc='53';
delete ma_tinh_trang_tdc a where a.ma in ('51','52','53','54');
--
-- Dong bo bang ma tinh trang trich xuat
--
update pn_tx_trich_xuat a set a.ma_tinh_trang_tx= '10' where a.ma_tinh_trang_tx is null;
update pn_tx_trich_xuat a set a.ma_tinh_trang_tx= '20' where a.ma_tinh_trang_tx='41';
update pn_tx_trich_xuat a set a.ma_tinh_trang_tx= '30' where a.ma_tinh_trang_tx='42';
update pn_tx_trich_xuat a set a.ma_tinh_trang_tx= '40' where a.ma_tinh_trang_tx='43';
update pn_tx_trich_xuat a set a.ma_tinh_trang_tx= '60' where a.ma_tinh_trang_tx='44';
update pn_tx_trich_xuat a set a.ma_tinh_trang_tx= '80' where a.ma_tinh_trang_tx='45';
delete ma_tinh_trang_tx a where a.ma in ('41','42','43','44','45');

--
-- Dong bo ma co quan
--
str:=null;
for obj in (select ma,nd from ma_cq where nd in (select nd from ma_cq group by nd having count(*)>1) order by nd)
loop
  str:=null;
  for obj_i in (select ma from ma_cq where nd=obj.nd) loop
    update ma_cq set nd=nd||str   where ma=obj_i.ma;
    str:=str||'.';
  end loop;
end loop;
--
-- Dong bo ma dia phuong
--
str:=null;
for obj in (select ma,nd from ma_dp where nd in (select nd from ma_dp group by nd having count(*)>1) order by nd)
loop
  str:=null;
  for obj_i in (select ma from ma_dp where nd=obj.nd) loop
    update ma_dp set nd=nd||str   where ma=obj_i.ma;
    str:=str||'.';
  end loop;
end loop;

--
-- Dong bo ma dan toc
--
str:=null;
for obj in (select ma,nd from ma_dan_toc where nd in (select nd from ma_dan_toc group by nd having count(*)>1) order by nd)
loop
  str:=null;
  for obj_i in (select ma from ma_dan_toc where nd=obj.nd) loop
    update ma_dan_toc set nd=nd||str   where ma=obj_i.ma;
    str:=str||'.';
  end loop;
end loop;

--
-- Dong bo ma quoc tich
--
str:=null;
for obj in (select ma,nd from ma_quoc_tich where nd in (select nd from ma_quoc_tich group by nd having count(*)>1) order by nd)
loop
  str:=null;
  for obj_i in (select ma from ma_quoc_tich where nd=obj.nd) loop
    update ma_quoc_tich set nd=nd||str   where ma=obj_i.ma;
    str:=str||'.';
  end loop;
end loop;
--
-- Dong bo ma trai giam
--
str:=null;
for obj in (select ma,nd from ma_trai_giam where nd in (select nd from ma_trai_giam group by nd having count(*)>1) order by nd)
loop
  str:=null;
  for obj_i in (select ma from ma_trai_giam where nd=obj.nd) loop
    update ma_trai_giam set nd=nd||str   where ma=obj_i.ma;
    str:=str||'.';
  end loop;
end loop;
--
-- Nghe nghiep
str:=null;
for obj in (select ma,nd from ma_nghe_nghiep where nd in (select nd from ma_nghe_nghiep group by nd having count(*)>1) order by nd)
loop
  str:=null;
  for obj_i in (select ma from ma_nghe_nghiep where nd=obj.nd) loop
    update ma_nghe_nghiep set nd=nd||str   where ma=obj_i.ma;
    str:=str||'.';
  end loop;
end loop;
--
-- Hoc van
--
str:=null;
for obj in (select ma,nd from ma_hoc_van where nd in (select nd from ma_hoc_van group by nd having count(*)>1) order by nd)
loop
  str:=null;
  for obj_i in (select ma from ma_hoc_van where nd=obj.nd) loop
    update ma_hoc_van set nd=nd||str   where ma=obj_i.ma;
    str:=str||'.';
  end loop;
end loop;
--
-- Toi danh
--
str:=null;
for obj in (select ma,nd from ma_toi_danh where nd in (select nd from ma_toi_danh group by nd having count(*)>1) order by nd)
loop
  str:=null;
  for obj_i in (select ma from ma_toi_danh where nd=obj.nd) loop
    update ma_toi_danh set nd=nd||str   where ma=obj_i.ma;
    str:=str||'.';
  end loop;
end loop;
--
-- Danh muc ghi chu rieng
--
str:=null;
for obj in (select ma,nd from ma_ghi_chu_rieng where nd in (select nd from ma_ghi_chu_rieng group by nd having count(*)>1) order by nd)
loop
  str:=null;
  for obj_i in (select ma from ma_ghi_chu_rieng where nd=obj.nd) loop
    update ma_ghi_chu_rieng set nd=nd||str   where ma=obj_i.ma;
    str:=str||'.';
  end loop;
end loop;
--
-- Danh muc tinh trang tam dinh chi
--
str:=null;
for obj in (select ma,nd from ma_tinh_trang_tdc where nd in (select nd from ma_tinh_trang_tdc group by nd having count(*)>1) order by nd)
loop
  str:=null;
  for obj_i in (select ma from ma_tinh_trang_tdc where nd=obj.nd) loop
    update ma_tinh_trang_tdc set nd=nd||str   where ma=obj_i.ma;
    str:=str||'.';
  end loop;
end loop;

--
-- Danh muc tinh trang trich xuat
--
str:=null;
for obj in (select ma,nd from ma_tinh_trang_tx where nd in (select nd from ma_tinh_trang_tx group by nd having count(*)>1) order by nd)
loop
  str:=null;
  for obj_i in (select ma from ma_tinh_trang_tx where nd=obj.nd) loop
    update ma_tinh_trang_tx set nd=nd||str   where ma=obj_i.ma;
    str:=str||'.';
  end loop;
end loop;

commit;
End;

