--  DDL for Procedure UPDATE_KY_XLCT
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN_SUOI_HAI"."UPDATE_KY_XLCT" (v_pn_id varchar2, v_ky_xlct varchar2,v_xep_loai varchar2,v_year number) is
 strSQL varchar2(2000);
 cCount number;
 xl varchar2(7):=v_xep_loai;
begin
 strSQL:='Select count(*) from pn_ket_qua_cai_tao where nam_xl='||v_year||' and pn_id='''||v_pn_id||'''';
 execute immediate strSql into cCount;
 if cCount=0 then
  strSQL:='insert into pn_ket_qua_cai_tao(pn_id,nam_xl,'||v_ky_xlct||') values('''||v_pn_id||''','||v_year||','''||v_xep_loai||''')';
 else
 if xl='999' then xl:=null; end if;
  if xl is not null then
     strSQL:='update pn_ket_qua_cai_tao set '||v_ky_xlct||'='''||xl||''' where pn_id='''||v_pn_id||''' and nam_xl='||v_year;
  else
     strSQL:='update pn_ket_qua_cai_tao set '||v_ky_xlct||'=null where pn_id='''||v_pn_id||''' and nam_xl='||v_year;
  end if;
 end if;
 execute immediate strSql;
 commit;
end;

