--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN_SUOI_HAI"."UPDATE_NDBLANK_BANGMA" is
sqlstr varchar2(2000);
Begin
  for obj in (select distinct table_name from user_tab_columns where table_name like 'MA_%' and column_name like 'ND%')
  loop
   Begin
    sqlstr:='update '||obj.table_name||' set nd=ltrim(rtrim(nd))';
    execute immediate  sqlstr;
    commit;
   exception
   when others then null;
   end;
  end loop;
end;

/
--------------------------------------------------------
--  DDL for Procedure UPDATE_QHGD
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN_SUOI_HAI"."UPDATE_QHGD" IS
v_ho_ten   varchar2(200);
v_dia_chi  varchar2(500);
BEGIN
	for obj in (select pn_id,ma_gioi_tinh from pn_lai_lich)
	loop
	 	update pn_lai_lich set ho_ten_bo=v_ho_ten,dc_bo=v_dia_chi where pn_id=obj.pn_id;
		get_qhgd(obj.pn_id,'122',v_ho_ten,v_dia_chi);
		update pn_lai_lich set ho_ten_me=v_ho_ten,dc_me=v_dia_chi where pn_id=obj.pn_id;
		if obj.ma_gioi_tinh=1 then
			get_qhgd(obj.pn_id,'132',v_ho_ten,v_dia_chi);
		else
			get_qhgd(obj.pn_id,'131',v_ho_ten,v_dia_chi);
		end if;
		update pn_lai_lich set ho_ten_vc=v_ho_ten,dc_me=v_dia_chi where pn_id=obj.pn_id;
	end loop;
END;

