--------------------------------------------------------
--  DDL for Procedure UPDATE_TG_DACXA
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN_SUOI_HAI"."UPDATE_TG_DACXA" is
begin
--update pn_dx_dac_xa x set x.ma_muc_tg_chap_hanh_dx=(select t.ma from ma_muc_thoi_gian t where t.ma_cu=x.ma_muc_tg_chap_hanh_dx);
update pn_dx_dac_xa x set x.ma_muc_tg_con_lai_dx=(select t.ma from ma_muc_thoi_gian t where t.ma_cu=x.ma_muc_tg_con_lai_dx);
update pn_dx_dac_xa x set x.ma_muc_tg_tron=(select t.ma from ma_muc_thoi_gian t where t.ma_cu=x.ma_muc_tg_tron);
update pn_dx_dac_xa x set x.ma_muc_tg_tdc=(select t.ma from ma_muc_thoi_gian t where t.ma_cu=x.ma_muc_tg_tdc);
end;

