--  DDL for Procedure UPDATE_TIEN_LDSX
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN_SUOI_HAI"."UPDATE_TIEN_LDSX" (v_pn_id varchar2, v_ky_xlct varchar2,v_so_tien varchar2,v_year number) is
 strSQL varchar2(2000);
 cCount number;
begin
 strSQL:='Select count(*) from pn_tien_cong_sx where nam_sx='||v_year||' and pn_id='''||v_pn_id||'''';
 execute immediate strSql into cCount;
 if cCount=0 then
  strSQL:='insert into pn_tien_cong_sx(pn_id,nam_sx,'||v_ky_xlct||') values('''||v_pn_id||''','||v_year||','||v_so_tien||')';
 else
  if v_so_tien is not null then
     strSQL:='update pn_tien_cong_sx set '||v_ky_xlct||'='||v_so_tien||' where pn_id='''||v_pn_id||''' and nam_sx='||v_year;
  else
     strSQL:='update pn_tien_cong_sx set '||v_ky_xlct||'=null where pn_id='''||v_pn_id||''' and nam_sx='||v_year;
  end if;
 end if;
 execute immediate strSql;
 commit;
end;

