--------------------------------------------------------
--  DDL for Procedure U_CREATE_INDEX
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN_SUOI_HAI"."U_CREATE_INDEX" (tabname varchar2, sortname varchar2 default null) Is
   sort_name varchar2(100):=sortname;
   index_already_exist exception;
   ident_is_too_long exception;
   column_list_already_indexed exception;
   pragma exception_init(index_already_exist,-00955);
   pragma exception_init(ident_is_too_long,-00972);
   pragma exception_init(column_list_already_indexed,-01408);
Begin
 for obj in (select column_name, substr(column_name,1,5) scol_name
 	from user_tab_columns 
 		where table_name=upper(tabname)
 			and column_name not in ('PN_ID'))
 loop
  begin
		if sort_name is null then sort_name:=tabname; end if;
 		execute immediate 'create index '||sort_name||'_'||obj.scol_name||' on '||tabname||'('||obj.column_name||') tablespace indx';
 	exception
 		when index_already_exist then null;
 		when ident_is_too_long then null;
 		when column_list_already_indexed then null;
 	end;	
 end loop;
End;

/
--------------------------------------------------------
--  DDL for Procedure U_CREATE_TRIGGER
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN_SUOI_HAI"."U_CREATE_TRIGGER" Is
 str varchar2(1000);
 t number;
Begin
	for obj in (select table_name from user_tables where table_name like 'TV_%') 
	loop
			select count(*) into t from user_tab_columns 
				where table_name=upper(obj.table_name) 
					and (column_name='ID' or column_name='SO_HSLD');
			if t=2 then
				str:='create or replace trigger '||obj.table_name||'_log
				after insert or delete or update
				on '||obj.table_name||'
				for each row 
				begin
				if inserting then
				  insert into s_log_data values('''||obj.table_name||''',:new.rowid,trunc(sysdate));
				elsif updating then
				  insert into s_log_data values('''||obj.table_name||''',:old.rowid,trunc(sysdate));
				elsif deleting then
				  insert into s_log_dele values('''||obj.table_name||''',:old.so_hsld,:old.id,trunc(sysdate));
				end if;
				end '||obj.table_name||'_log;';
				execute immediate str;
			end if;
			if t=1 then
				str:='create or replace trigger '||obj.table_name||'_log
				after insert or delete or update
				on '||obj.table_name||'
				for each row 
				begin
				if inserting then
				  insert into s_log_data values('''||obj.table_name||''',:new.rowid,trunc(sysdate));
				elsif updating then
				  insert into s_log_data values('''||obj.table_name||''',:old.rowid,trunc(sysdate));
				elsif deleting then
				  insert into s_log_dele values('''||obj.table_name||''',:old.so_hsld,null,trunc(sysdate));
				end if;
				end '||obj.table_name||'_log;';
				execute immediate str;
			end if;
	end loop;
End;

