--  DDL for Procedure U_GET_TIEN_AN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN_SUOI_HAI"."U_GET_TIEN_AN" (v_pn_id varchar2,v_num number,out_nam_xu out varchar2,out_muc_an out varchar2,out_toa_xu out varchar2) is
	str_nam_xu varchar2(3000);
	str_muc_an varchar2(3000);
	str_toa_xu varchar2(3000);
  cCount   number:=0;
begin
  for obj in (select nam_xu,ma_muc_an_ta,ma_toi_danh_ta, rownum recno
               from pn_tien_an
                 where pn_id=v_pn_id) loop
		cCount:=cCount+1;
    if cCount between v_num and v_num+2 then
      str_nam_xu:=str_nam_xu||chr(10)||obj.nam_xu;
      str_muc_an:=str_muc_an||chr(10)||countma('ma_muc_thoi_gian',obj.ma_muc_an_ta);
      str_toa_xu:=str_toa_xu||chr(10)||u_count_mas('ma_toi_danh_tt',obj.ma_toi_danh_ta);
    end if;
	end loop;
	out_nam_xu:=substr(str_nam_xu,2);
  out_muc_an:=substr(str_muc_an,2);
  out_toa_xu:=substr(str_toa_xu,2);
end;

