--------------------------------------------------------
--  DDL for Procedure U_UPDATE_RATRAI
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN_SUOI_HAI"."U_UPDATE_RATRAI" is
 ma_tt varchar2(10);
 cCount number;
begin
select count(*) into cCount from s_update_ratrai where trunc(ngay_cap_nhat)=trunc(sysdate);
if cCount=0 then
  for j in (select pn_id,l.ngay_ra_trai from pn_lai_lich l
              where pn_id in
             (select pn_id from pn_lai_lich where l.ma_tinh_trang like '11%'
               and trunc(l.ngay_ra_trai)<=trunc(sysdate)
               union
               (select pn_id from pn_lai_lich where ma_tinh_trang like '12%'
                and trunc(ngay_ra_trai)<=trunc(sysdate)
                minus
                select pn_id from pn_ra_trai where trunc(ngay_tha)<=trunc(sysdate)
               )
              )
             )
    loop
       delete pn_ra_trai where pn_id=j.pn_id;
       insert into pn_ra_trai(pn_id,ma_th_tha,ngay_tha,ngay_trinh_dien)
       values(j.pn_id,'21',j.ngay_ra_trai,j.ngay_ra_trai+7);
       ma_tt:=get_tinh_trang(j.pn_id);
       update pn_ra_trai set ma_th_tha=decode(ma_tt,'121','21','122','22','123','23','147','23','155','23','20') where pn_id=j.pn_id;
       update pn_lai_lich c set c.ma_tinh_trang=ma_tt where c.pn_id=j.pn_id;
    end loop;

  --==========================================
  for d in (select pn_id from pn_ra_trai
            intersect
            select pn_id from pn_lai_lich
                   where to_number(substr(ma_tinh_trang,1,2))>'12')
  loop
     delete pn_ra_trai where pn_id=d.pn_id;
  end loop;
  commit;
  insert into s_update_ratrai values(sysdate);
  commit;
end if;
--exception
  -- when others then null;
end;

