Function cadd_months(vNgay date, vSo number) Return Date Is
	vDate date;
	dRet  date;
Begin
	if vNgay is null then
		return null;
	end if;
	vDate:=add_months(vNgay,vSo);
	if to_char(vNgay,'dd')<to_char(vDate,'dd') then
  	vDate:=to_date(to_char(vNgay,'dd')||'/'||to_char(vDate,'mm/yyyy'),'dd/mm/yyyy');
	end if;
  return vDate;
End;  -- of CADD_MONTHS
-------------------
Function Date_Minus(vDate1 date, vDate2 date, vPart char) Return number Is
	vSonam1 		number;
	vSothang1 	number;
	vSongay1 		number;
	vSonam2 		number;
	vSothang2 	number;
	vSongay2 		number;
	vSonam	 		number;
	vSothang	 	number;
	vSongay 		number;
	Date1				date;
	Date2				date;
Begin
	if vDate1 is null or vDate2 is null then
		return null;
	end if;
	if vDate1>=vDate2 then
		Date1:=vDate1;
		Date2:=vDate2;
	else
		Date2:=vDate1;
		Date1:=vDate2;
	end if;
	vSongay1:=to_number(to_char(Date1,'dd'));
	vSothang1:=to_number(to_char(Date1,'mm'));
  vSonam1:=to_number(to_char(Date1,'yyyy'));
  vSongay2:=to_number(to_char(Date2,'dd'));
	vSothang2:=to_number(to_char(Date2,'mm'));
  vSonam2:=to_number(to_char(Date2,'yyyy'));
  if vSongay1<vSongay2 then
  	vSongay1:=vSongay1+30;
  	vSothang1:=vSothang1-1;
  	vSongay:=vSongay1-vSongay2;
  else
  	vSongay:=vSongay1-vSongay2;
  end if;
  if vSothang1<vSothang2 then
  	vSothang1:=vSothang1+12;
  	vSonam1:=vSonam1-1;
  	vSothang:=vSothang1-vSothang2;
  else
  	vSothang:=vSothang1-vSothang2;
  end if;
    vSonam:=vSonam1-vSonam2;
  if upper(vPart)='D' then
  	return vSongay;
  elsif upper(vPart)='M' then
  	return vSothang;
  elsif upper(vPart)='Y' then
  	return vSonam;
  elsif upper(vPart)='MF' then
  	return vSonam*12+vSothang;
  end if;
  End; -- of Date_Minus
  -----------------
