/************ GET_TO_DATE function *********************
 Function: L?y m?t ngay ?ich theo m?t ngay m?c va m?c th?i h?n
 N?u khong co thi tr? v? NULL
*/

Function GET_TO_DATE_from_ma(p_FROM_DATE date,P_MA_MUC_THOI_HAN varchar2,p_toan_tu varchar2 default null) RETURN Date is
-- Created: Nguyen Van Khuyen
-- Date:    Mon, Jun 09, 2007
-- Function: Lay ngay tiep theo
-- Value return: a date, NULL neu khong co
	p_ngay_den date;
	p_so_thang number(4);
	p_so_ngay number(4);
BEGIN
	if p_ma_Muc_thoi_han is null then return null;end if;
	if length(p_ma_muc_thoi_han)<>7 then return null;end if;
	if p_from_date is null then return null;end if;
	if to_number(p_ma_muc_thoi_han)>9000000 then return null;end if;
	p_so_thang:=nvl(to_number(substr(p_ma_muc_thoi_han,2,2)),0)*12+nvl(to_number(substr(p_ma_muc_thoi_han,4,2)),0);
	p_so_ngay:=nvl(to_number(substr(p_ma_muc_thoi_han,6,2)),0);
	if p_toan_tu='-' then
		p_ngay_den:=add_months(p_from_date,-p_so_thang)-p_so_ngay;
	else
		p_ngay_den:=add_months(p_from_date,p_so_thang)+p_so_ngay;
	end if;
	return p_ngay_den;
End;  -- of get_to_Date_from_ma

/************ GET_TO_DATE function *********************
 Function: Lay dinh dang theo ngay thang Viet Nam
 */

Function GET_TO_VNDATE(p_DATE date,p_format varchar2 default null) RETURN char is
-- Created: Nguyen Van Khuyen
-- Date:    Mon, Jun 09, 2007
-- Function: Lay ngay tiep theo
-- Value return: a date, NULL neu khong co
	p_thang number(4);
	p_ngay_moi varchar2(20);
	p_thang_moi varchar2(20);
	p_nam_moi varchar2(20);
	p_ngay_thang_moi varchar2(20);
BEGIN
	if p_date is null then return null;end if;
	---p_ngay_moi:=to_char(p_date,'dd');
	p_thang:=to_number(to_char(p_date,'mm'));
	---p_nam_moi=to_char(p_date,'yyyy');
	if p_thang<3 then
		p_thang_moi:='0'||to_char(p_thang);
	else
		p_thang_moi:=to_char(p_thang);
	end if;
	if upper(p_format)='DD/MM/YY' then
		return to_char(p_date,'dd')||'/'||p_thang_moi||'/'||to_char(p_date,'yy');
	end if;
	if upper(p_format)='LD' then
		return 'ngay '||to_char(p_date,'dd')||' thang '||p_thang_moi||' nam '||to_char(p_date,'yyyy');
	end if;
	return to_char(p_date,'dd')||'/'||p_thang_moi||'/'||to_char(p_date,'yyyy');
End;  -- of get_to_Date_from_ma

/************ GET_TO_DATE_FROM_CHARDATE function *********************
 Function: Lay dinh dang theo ngay thang Viet Nam
 */

Function GET_TO_VNDATE_FROM_CHARDATE(p_CHARDATE varchar2,p_format varchar2 default null) RETURN char is
-- Created: Nguyen Van Khuyen
-- Date:    Mon, Jun 09, 2007
-- Function: Lay ngay tiep theo
-- Value return: a date, NULL neu khong co
	p_thang number(4);
	p_ngay_moi number(4);
	p_thang_moi number(4);
	p_nam_moi varchar2(20);
	p_ngay_thang_moi varchar2(20);
BEGIN
	if p_chardate is null then return null;end if;

	if length(p_CharDate)<=4 then
		return p_CharDate;
	elsif length(p_CharDate)=7 then
		p_thang_moi:=to_number(substr(p_CharDate,1,2));
		if p_thang_moi<3 then
			return p_CharDate;
		else
			return to_char(p_thang_moi)||substr(p_CharDate,length(p_CharDate)-3);
		end if;
	elsif length(p_CharDate)=10 then
		---p_thang_moi:=to_number(substr(p_CharDate,1,2));
		p_thang_moi:=to_number(substr(p_CharDate,4,2));
		if p_thang_moi<3 then
			return p_CharDate;
		else
			return substr(p_CharDate,1,2)||'/'||to_char(p_thang_moi)||'/'||substr(p_CharDate,length(p_CharDate)-3);
		end if;
	end if;
	return p_CharDate;
End;  -- of get_to_Date_from_ma

END; -- of PN_DATE Package Body 07/07/2010

