/************ GET_KQCT_DIEU_KIEN_XGTH function *********************
 Function: Lay ket qua cai tao
*/
Function GET_KQCT_DIEU_KIEN_XGTH(P_PN_ID varchar2,p_ngay_xet date) return char IS
-- Created by: Nguyen Van Khuyen
-- Date: Sat, DEC 16, 2006
-- Function:
Cursor KQCT_CUR is
  	select nam_XL nam_xet
  				,decode(to_number(substr(MA_XEP_LOAI_Q1,2,1)),null,'A',1,'B',2,'C',3,'D',4,'E') QUY1
  				,decode(to_number(substr(MA_XEP_LOAI_Q2,2,1)),null,'A',1,'B',2,'C',3,'D',4,'E') QUY2
  				,decode(to_number(substr(MA_XEP_LOAI_DAU,2,1)),null,'A',1,'B',2,'C',3,'D',4,'E') DAU_NAM
  				,decode(to_number(substr(MA_XEP_LOAI_Q3,2,1)),null,'A',1,'B',2,'C',3,'D',4,'E') QUY3
  				,decode(to_number(substr(MA_XEP_LOAI_Q4,2,1)),null,'A',1,'B',2,'C',3,'D',4,'E') QUY4
  				,decode(to_number(substr(MA_XEP_LOAI_CUOI,2,1)),null,'A',1,'B',2,'C',3,'D',4,'E') CUOI_NAM
  				,decode(to_number(substr(MA_XEP_LOAI_CA,2,1)),null,'A',1,'B',2,'C',3,'D',4,'E') CA_NAM
--  				,decode(nhan_xet,null,'',nhan_xet||'.') nhan_xet
  	from PN_KET_QUA_CAI_TAO
  	where pn_id=p_PN_ID 	and nam_XL<=to_number(to_char(p_ngay_Xet,'YYYY'))
  	order by nam_xet;
  KQCT_REC KQCT_CUR%rowtype;
  Len number(4):=0;
  p_data varchar2(100);
  --p_Nam_xet number(4);
BEGIN
	for KQCT_REC in KQCT_CUR
	loop
		if p_data is null then
			if kqct_rec.dau_nam='A' then
				if kqct_rec.cuoi_nam<>'A' then
					p_data:=KQCT_REC.CUOI_NAM;
				end if;
			else
				if kqct_rec.cuoi_nam='A' then
					p_data:=KQCT_REC.DAU_NAM;
				else
					p_data:=KQCT_REC.DAU_NAM||KQCT_REC.CUOI_NAM;
				end if;
			end if;
		else
			if kqct_rec.dau_nam='A' then
				if kqct_rec.cuoi_nam<>'A' then
					p_data:=p_data||KQCT_REC.CUOI_NAM;
				end if;
			else
				if kqct_rec.cuoi_nam='A' then
					p_data:=p_data||KQCT_REC.DAU_NAM;
				else
					p_data:=p_data||KQCT_REC.DAU_NAM||KQCT_REC.CUOI_NAM;
				end if;
			end if;
		---p_nam_xet:=kqct_rec.nam_xet;
		end if;
	end loop;
	---if p_nam_xet<to_number(to_char(p_ngay_xet,'yyyy')) then return null;end if;
  return P_DATA;
	End; --- of GET_KQCT_DIEU_KIEN_XGTH

/************ GET_DIEU_KIEN_XGTH_KQCT function *********************
 Function: Ki?m tra ph?m nhan ?? ?i?u ki?n gi?m an theo k?t qu? c?i t?o
*/
function GET_DIEU_KIEN_XGTH_KQCT(p_PN_ID varchar2,p_ngay_xet date,P_MA_MUC_AN_PHAT varchar2) return number IS
-- Created: Nguyen Van Khuyen
-- Date: Sat, Dec 16, 2006


p_PN_KET_QUA_CAI_TAO varchar2(100);
p_PN_KET_QUA_CAI_TAO_quy number(4);
so_thang_an_phat number(4);
so_lan_giam number(4);
P_DIEU_KIEN number(4);
LenStr number(4):=0;
p_data varchar2(100);
Function get_PN_KET_QUA_CAI_TAO_quy(P_PN_ID varchar2,p_ngay_xet_XLQ date) return number is
cursor kqct_quy_cur is
       select nam_xl nam_xet,
       				nvl(to_number(substr(ma_xep_loai_q1,2,1)),0) Mxl_quy1,
              nvl(to_number(substr(ma_xep_loai_q2,2,1)),0) Mxl_quy2,
              nvl(to_number(substr(ma_xep_loai_q3,2,1)),0) Mxl_quy3,
              nvl(to_number(substr(ma_xep_loai_q4,2,1)),0) Mxl_quy4
       from pn_KET_QUA_CAI_TAO
       where  pn_id=p_PN_ID and nam_xl>=to_number(to_Char(p_ngay_xet,'yyyy'))-1;
kqct_quy_rec kqct_quy_cur%rowtype;
p_ketqua number(4);
XL_Q1 number(2);
XL_Q2 number(2);
XL_Q3 number(2);
XL_Q4 number(2);
XL_Q4_Truoc number(2);
thang_xet number(4);
Begin
	for kqct_quy_rec in kqct_quy_Cur
	loop
		if kqct_quy_rec.nam_xet<>to_number(to_char(p_ngay_Xet_XLQ,'yyyy')) then
			XL_Q4_truoc:=kqct_quy_rec.mxl_Quy4;
		end if;
		XL_Q1:=kqct_quy_rec.mxl_Quy1;
		XL_Q2:=kqct_quy_rec.mxl_Quy2;
		XL_Q3:=kqct_quy_rec.mxl_Quy3;
		XL_Q4:=kqct_quy_rec.mxl_Quy4;
	end loop;
	thang_xet:=to_number(to_char(p_ngay_Xet_XLQ,'mm'));
	if thang_xet<=2 then
		p_ketqua:=xl_Q4_truoc;
	elsif thang_xet>=3 and thang_xet<=5 then
		p_ketqua:=XL_Q1;
	elsif thang_xet>=6 and thang_xet<=8 then
		p_ketqua:=XL_Q2;
	elsif thang_xet>=9 and thang_xet<=12 then
		p_ketqua:=XL_Q3;
	end if;
--	p_ketqua:=kqct_quy_rec.Mxl_quy2;
	if p_ketqua is not null then return p_ketqua;end if;
	return 0;
End;
BEGIN
	p_PN_KET_QUA_CAI_TAO:=pn_db.GET_KQCT_DIEU_KIEN_XGTH(P_PN_ID,p_ngay_xet);
	LenStr:=nvl(length(P_PN_KET_QUA_CAI_TAO),0);
	so_thang_an_phat:=nvl(to_number(substr(p_ma_muc_an_phat,1,2)),0)*12+nvl(to_number(substr(p_ma_muc_an_phat,3,2)),0);
	--so_thang_an_phat:=trunc(nvl(p_so_ngay_an_phat,0)/30);
  ----------------------------------------------------------
  P_DIEU_KIEN:=0; -- Khong ?? ?i?u ki?n
  --- Life sentence
  if to_number(p_ma_muc_an_phat) in (911000,912000) then
		if Lenstr<8 then -- khong du 8 ky xep loai
			p_dieu_kien:=0; -- not engough
		else
			p_data:=substr(p_PN_KET_QUA_CAI_TAO,Lenstr-7); -- lay 8 ky
			if instr(P_data,'D')<>0 or instr(P_data,'E')<>0 then
				P_DIEU_KIEN:=0; -- an chung than toa xu khong co 8 ky xep loai kha tro len
			else
				P_DIEU_KIEN:=1;
			end if;
		end if;
	else
		----------------------- Limited time Senetence
		if SO_THANG_AN_PHAT>180 then -- an tren 15 nam thi phai co 6 ky xep loai
			if LenStr<6 then -- An tren 15 nam khong du khong du 6 ky xep loai
				P_DIEU_KIEN:=0;
			else
				p_data:=substr(p_PN_KET_QUA_CAI_TAO,Lenstr-5); -- lay 6 ky xep loai
				if instr(P_data,'D')<>0 or instr(P_data,'E')<>0 then
					P_DIEU_KIEN:=0; -- an tren 15 nam khong du 6 ky xep loai kha tro len
				else
					P_DIEU_KIEN:=1;
				end if;
			end if;
		elsif SO_THANG_AN_PHAT>120 and so_thang_an_phat<=180 then -- tren 10 nam den  15 nam thi phai co 4 ky xep loai kha tro len
			if LenStr<4 then -- 4 ky xep loai
				P_DIEU_KIEN:=0;
			else
				p_data:=substr(p_PN_KET_QUA_CAI_TAO,Lenstr-3); -- lay 4 ky xep loai
				if instr(P_data,'D')<>0 or instr(P_data,'E')<>0 then
					P_DIEU_KIEN:=0; -- khong du 4 ky tien tiep kha tro len
				else
					P_DIEU_KIEN:=1;
				end if;
			end if;
		elsif SO_THANG_AN_PHAT>60 and so_thang_an_phat<=120 then -- an tren 5 nam den 10 nam phai co 1 ky xep loai kha tro len
			if LenStr<2 then --  khong du 2 ky xep loai
				P_DIEU_KIEN:=0;
			else
				p_data:=substr(p_PN_KET_QUA_CAI_TAO,Lenstr-1); -- lay 2 ky xep loai
				if instr(P_data,'D')<>0 or instr(P_data,'E')<>0 then
					P_DIEU_KIEN:=0; -- khong du 2 ky lien tiep xep loai kha tro len
				else
					P_DIEU_KIEN:=1;
				end if;
			end if;
		elsif SO_THANG_AN_PHAT>36 and so_thang_an_phat<=120 then -- an tu tren 3 den 5 nam
			if LenStr<1 then --  khong du 1 ky xep loai
				P_DIEU_KIEN:=0;
			else
				p_data:=substr(p_PN_KET_QUA_CAI_TAO,Lenstr); -- lay 1 ky xep loai
				if instr(P_data,'D')<>0 or instr(P_data,'E')<>0 then
					P_DIEU_KIEN:=0; -- khong du 1 ky xep loai gan nhat kha tro len
				else
					P_DIEU_KIEN:=1;
				end if;
			end if;
		else -- tu 3 nam tro xuong thi phai xet den quy
			if Lenstr>0 then -- neu co ky xep loai thi phai xep loai kha tro len
				p_data:=substr(p_PN_KET_QUA_CAI_TAO,Lenstr); -- lay 1 ky xep loai
				if instr(P_data,'D')<>0 or instr(P_data,'E')<>0 then
					P_DIEU_KIEN:=0; -- an tu 3 nam tro xuong co ket qua cai tao nhung khong xep loai kha tro len
				else
					P_DIEU_KIEN:=1;
				end if;
			else
				p_PN_KET_QUA_CAI_TAO_quy:=get_PN_KET_QUA_CAI_TAO_quy(P_PN_ID,p_ngay_xet);
				if p_PN_KET_QUA_CAI_TAO_quy in (1,2) then
					p_DIEU_KIEN:=1;
				else
					p_DIEU_KIEN:=0;
				end if;
			end if;
		end if;
	end if;
  return P_DIEU_KIEN;
END;--- of GET_DIEU_KIEN_XGTH_KQCT

/************ GET_DIEU_KIEN_XGTH_TGCH function *********************
 Function: Ki?m tra ?i?u ki?n xet gi?m th?i h?n theo th?i gian ch?p hanh
*/
Function GET_DIEU_KIEN_XGTH_TGCH(P_PN_ID varchar2,p_ngay_xet date,P_ma_muc_an_phat varchar2,P_MA_GHI_CHU_RIENG varchar2) return number IS
-- Created: Nguyen Van Khuyen
-- Date: Sat Dec 16, 2006
-- Function:
P_DIEU_KIEN number(4);
so_nam number(10);
so_thang number(10);
so_ngay number(10);
ma_muc_tg_chap_hanh varchar2(7);
so_thang_chap_hanh number(10);
so_ngay_chap_hanh number(10);
so_ngay_an_phat number(10);
---p_so_ngay_an_phat
Begin
 ma_muc_tg_chap_hanh:=pn_get.ma_tg_chap_hanh(p_pn_id,p_ngay_xet);
-- PN_GET.tg_chap_hanh(p_pn_id,p_ngay_xet,so_nam,so_thang,so_ngay);
/* p_so_thang_chap_hanh:=nvl(so_nam,0)*12+nvl(so_thang,0)+trunc(nvl(so_ngay,0)/30);
 p_so_ngay_chap_hanh:=(nvl(so_nam,0)*12+nvl(so_thang,0))*30+nvl(so_ngay,0);*/

 so_thang_chap_hanh:=pn_sys.get_number_from_ma_string(ma_muc_tg_chap_hanh);
 so_ngay_chap_hanh:=pn_sys.get_number_from_ma_string(ma_muc_tg_chap_hanh,'sd');

 P_DIEU_KIEN:=0;---khong du dieu kien
 if to_number(P_ma_muc_an_phat) in (911000,912000) then -- chung than
 	if so_ngay_chap_hanh<10*12*30 then -- chua duoc 10 nam
 		P_DIEU_KIEN:=0;
 	else -- du dieu kien
 		P_DIEU_KIEN:=1;
 	end if;
 else  -- an co thoi han
-- 	so_ngay_an_phat:=nvl(to_number(substr(p_ma_muc_an_phat,2,2)),0)*12*30+nvl(to_number(substr(p_ma_muc_an_phat,4,2)),0)*30+nvl(to_number(substr(p_ma_muc_an_phat,6,2)),0);
 	so_ngay_an_phat:=pn_sys.get_number_from_ma_string(p_ma_muc_an_phat,'sd');

 	if 4*so_ngay_chap_hanh<so_ngay_an_phat then -- chua chap hanh duoc 1/4 muc an
 		P_DIEU_KIEN:=0;  -- khong du
 	elsif 4*so_ngay_chap_hanh>=so_ngay_an_phat and 3*so_ngay_chap_hanh<so_ngay_an_phat then -- tu 1/4 den duoi 1/3 thi kiem tra muc an
 		if to_number(substr(nvl(P_MA_GHI_CHU_RIENG,'9999'),1,2))in (13,17,19) then
 			P_DIEU_KIEN:=1;-- co du dieu kien
 		else
 			P_DIEU_KIEN:=0;
 		end if;
 	else -- chap hanh duoc tu 1/3 muc an tro len
 			P_DIEU_KIEN:=1;
	end if;
 end if;
 return P_DIEU_KIEN;
End;  -- of GET_DIEU_KIEN_XGTH_TGCH

/************ GET_DIEU_KIEN_XET_GIAM_AN function *********************
 Function: Ki?m tra ?i?u ki?n ?? ?i?u ki?n xet gi?m an
*/
Function GET_DIEU_KIEN_XET_GIAM_AN(P_PN_ID varchar2,p_ngay_xet date,P_ma_muc_an_Phat varchar2,P_MA_GHI_CHU_RIENG varchar2) return number IS
-- Created: Nguyen Van Khuyen
-- Date: Sat Dec 16, 2006
-- Function:
P_DIEU_KIEN_KQCT number(4);
P_DIEU_KIEN_TGCH number(4);
P_DIEU_KIEN number(4);
Begin
 P_DIEU_KIEN:=0;

 P_DIEU_KIEN_TGCH:=PN_DB.GET_DIEU_KIEN_XGTH_TGCH(P_PN_ID,p_ngay_xet,p_ma_muc_an_phat,P_MA_GHI_CHU_RIENG);
 P_DIEU_KIEN_KQCT:=pn_db.GET_DIEU_KIEN_XGTH_KQCT(p_PN_ID,p_ngay_xet,p_ma_muc_an_phat);
 if P_DIEU_KIEN_TGCH=1 then
 	if P_DIEU_KIEN_KQCT=1 then -- du tat ca cac dieu kien
 		P_DIEU_KIEN:=1;
 	else  -- chi du dieu kien ve TGCH
 		P_DIEU_KIEN:=10;
 	end if;
 else
 	if P_DIEU_KIEN_KQCT=1 then -- chi du dieu ken ve kqct
 		P_DIEU_KIEN:=20;
 	else  -- khong du dieu kien gi ca
 		P_DIEU_KIEN:=0;
 	end if;
 end if;
 return P_DIEU_KIEN;
End;  -- of GET_DIEU_KIEN_XET_GIAM_AN

/************ GET_SO_NAM_KQCT_GIAM_AN function *********************
 Function: L?y s? n?m ma k?t qu? c?i t?o c?n co khi xet gi?m an
*/

Function GET_SO_NAM_KQCT_GIAM_AN(P_PN_ID varchar2,p_ngay_xet date,p_ma_muc_an_phat varchar2,p_so_tien_an number default 0) return number IS
-- Created: Nguyen Van Khuyen
-- Date: Sun Dec 17, 2006
-- Lastest Modified: 20/12/2011
-- Function:
P_DIEU_KIEN number(4);
Num_Rec number(4):=0;
so_nam number(4);
thang_xet_giam number(4);
nam_xet_giam number(4);
P_SO_THANG_CHAP_HANH number(4);
p_so_thang_an_Phat number(4);
p_ket_qua_cai_tao varchar2(100);
p_data varchar2(200);
LenStr number(4);
 	Begin

 	thang_xet_giam:=to_number(to_char(p_ngay_xet,'mm'));
 	nam_xet_giam:=to_number(to_char(p_ngay_xet,'yyyy'));
 	p_so_thang_an_phat:=nvl(to_number(substr(p_ma_muc_an_phat,1,2)),0)*12+nvl(to_number(substr(p_ma_muc_an_phat,3,2)),0);
	p_KET_QUA_CAI_TAO:=pn_db.GET_KQCT_DIEU_KIEN_XGTH(P_PN_ID,p_ngay_xet);
	LenStr:=nvl(length(P_KET_QUA_CAI_TAO),0);

 	if to_number(p_ma_Muc_an_phat) in (911000,912000) then  -- an chung than ph?i co 8 k? x?p lo?i lien ti?p kha tr? len
 		if thang_xet_giam>6 then -- N?u xet sau thang Sau thi c?n ph?i co 8 k? x?p lo?i trong 5 n?m
					p_data:=substr(p_KET_QUA_CAI_TAO,Lenstr-7); -- lay 8 ky
					so_nam:=4;
 		else   -- N?u xet tr??c Thang Sau thi c?n ph?i co 8 k? x?p lo?i  va ph?i ki?m tra
 			select count(*) into Num_Rec from PN_KET_QUA_CAI_TAO where PN_ID=p_PN_ID and nam_xl=nam_xet_giam;
 			if Num_rec=0 then -- N?u n?m xet ?? co k?t qu? c?i t?o  thi s? n?m c?n thi?t la 5 n?m
				p_data:=substr(p_KET_QUA_CAI_TAO,Lenstr-7); -- lay 8 ky
 				so_nam:=4;
 			else  -- Nguoc lai con 4 nam
				p_data:=substr(p_KET_QUA_CAI_TAO,Lenstr-7); -- lay 8 ky
 				so_nam:=4;
 			end if;
 		end if;
 	else  -- AN  PH?T CO TH?I H?N
		if p_so_thang_an_phat>180 then -- An tren 15 n?m thi ph?i co 6 k? t??ng ???ng 3 n?m
	 		if thang_xet_giam>6 then -- N?u xet sau Thang Sau thi ph?i co 6 k? trong 4 n?m
				p_data:=substr(p_KET_QUA_CAI_TAO,Lenstr-5); -- lay 5 ky
	 			select count(*) into Num_Rec from PN_KET_QUA_CAI_TAO where PN_ID=p_PN_ID and nam_xl=nam_xet_giam and MA_XEP_LOAI_CUOI is not null;
	 				if Num_Rec=0 then
 					so_nam:=3;
	 				else
	 					so_nam:=2;
	 				end if;
	 		else   -- N?u xet tr??c Thang SAU thi ph?i co 6 k? va ki?m tra
---	 			select count(*) into Num_Rec from PN_KET_QUA_CAI_TAO where PN_ID=p_PN_ID and nam_xl=nam_xet_giam
---	 			if Num_rec=0 then -- N?u n?m xet ch?a co k?t qu? c?i t?o thi s? n?m xet la 4
					p_data:=substr(p_KET_QUA_CAI_TAO,Lenstr-5); -- lay 5 ky
	 				so_nam:=3;
	 --			else  -- Ng??c l?i thi c?n 3
	 	--			so_nam:=2;
	 		--	end if;
	 		end if;
		elsif p_so_thang_an_phat>120 and p_so_thang_an_phat<=180 then -- An tren 10 ??n 15 n?m ph?i co 2 n?m t?c la 4 k? x?p lo?i kha
			p_data:=substr(p_KET_QUA_CAI_TAO,Lenstr-3); -- lay 4 ky
	 		if thang_xet_giam>6 then -- N?u xet sau Thang Sau thi c?n ph?i co 4 k? va 3 n?m
	 			select count(*) into Num_Rec from PN_KET_QUA_CAI_TAO where PN_ID=p_PN_ID and nam_xl=nam_xet_giam and MA_XEP_LOAI_CUOI is not null;
	 				if Num_Rec=0 then
	 					so_nam:=2;
	 				else
	 					so_nam:=1;
	 				end if;
	 		else   -- N?u xet tr??c thang SAU thi c?n 3 n?m
--	 			select count(*) into Num_Rec from PN_KET_QUA_CAI_TAO where PN_ID=p_PN_ID and nam_xl=nam_xet_giam and MA_XEP_LOAI_DAU is not null;
	-- 			if Num_rec=0 then -- N?u nam xet d? co k?t qu? c?i t?o thi s? nam c?n thi?t la 3
	 				so_nam:=2;
	 	--		else  -- ng??c l?i thi c?n 2 nam
	 		--		so_nam:=1;
	 			--end if;
	 		end if;
	 	elsif p_so_thang_an_phat>60 and p_so_thang_an_phat<=120 then -- An tren 5 ??n 10 n?m ph?i co 1 nam t?c la 2 k?
			p_data:=substr(p_KET_QUA_CAI_TAO,Lenstr-1); -- lay 2 ky
	 		if thang_xet_giam>6 then -- N?u xet sau Thang Sau thi c?n ph?i co 1 k? va 2 nam
	 			select count(*) into Num_Rec from PN_KET_QUA_CAI_TAO where  PN_ID=p_PN_ID and nam_xl=nam_xet_giam and MA_XEP_LOAI_CUOI is not null;
	 			if Num_rec=0 then
	 				so_nam:=1;
	 			else
	 				so_nam:=0;
	 			end if;
	 		else   -- Ng??c l?i thi c?n 2 n?m
	 			select count(*) into Num_Rec from PN_KET_QUA_CAI_TAO where PN_ID=p_PN_ID and nam_xl=nam_xet_giam and MA_XEP_LOAI_DAU is not null;
--	 			if Num_rec=0 then -- N?u nam xet d? co k?t qu? c?i t?o thi s? nam c?n thi?t la 2
	 				so_nam:=1;
	-- 			else  -- ng??c l?i thi c?n 1 nam
	 	--			so_nam:=0;
	 		--	end if;
	 		end if;
		elsif p_so_thang_an_phat>36 and p_so_thang_an_phat<=60 then -- An tren 3 ??n 5 n?m ph?i co 1 k? x?p lo?i kha
			p_data:=substr(p_KET_QUA_CAI_TAO,Lenstr-1); -- lay 2 ky
	 		if thang_xet_giam>6 then -- n?u xet sau Thang Sau thi c?n ph?i co 1 k? va 0 n?m
	 			select count(*) into Num_Rec from PN_KET_QUA_CAI_TAO where PN_ID=p_PN_ID and nam_xl=nam_xet_giam and MA_XEP_LOAI_DAU is not null;
	 			if Num_rec=0 then
 					so_nam:=1;
	 			else
	 				return 0;
	 			end if;
	 		else   -- N?u xet tr??c Thang Sau thi c?n 2 n?m
--	 			select count(*) into Num_Rec from PN_KET_QUA_CAI_TAO where PN_ID=p_PN_ID and nam_xl=nam_xet_giam and MA_XEP_LOAI_DAU is not null;
	-- 			if Num_rec=0 then -- N?u nam xet d? co k?t qu? c?i t?o thi s? nam c?n thi?t la 1
	 				so_nam:=1;
	 	--		else  -- ng??c l?i thi c?n 1 nam
	 		--		so_nam:=0;
	 			--end if;
	 		end if;
		else -- An d??i 3 n?m thi ph?i co 1 Quy
	 		if thang_xet_giam>6 then -- N?u xet sau Thang SAU thi c?n phai co 0 n?m
	 			so_nam:=0;
	 		else   -- N?u xet tr??c Thang Sau thi ph?i ki?m tra
	 			select count(*) into Num_Rec from PN_KET_QUA_CAI_TAO where PN_ID=p_PN_ID and nam_xl=nam_xet_giam;
	 			if Num_rec=0 then -- N?u n?m xet ch?a co KQCT thi l?y 1 n?m
	 				so_nam:=1;
	 			else  -- Ng??c l?i thi c?n 0 n?m
	 				so_nam:=0;
	 			end if;
	 		end if;
 		end if;
	 end if;
	 if instr(p_data,'D')>0  or instr(p_data,'E')>0 then so_nam:=so_nam+2;end if;
	so_nam:=nvl(so_nam,0)+nvl(p_so_tien_an,0);
	return so_nam;
End;	-- of GET_SO_NAM_KQCT_GIAM_AN

/************ GET_KET_QUA_PLGG_HIEN_TAI function *********************
 Function: L?y k?t qu? phan lo?i giam gi? trong m?t kho?ng th?i gian
           K?t qu? g?m co ngay phan lo?i va m? phan lo?i ng?n cach nhau b?ng d?u '@'
           Ngay tr??c, m? phan lo?i sau
           N?u k?t qu? la NULL co ngh?a la ch?a co phan lo?i
*/
Function GET_KET_QUA_PLGG_HIEN_TAI(P_PN_ID varchar2,P_FROM_DATE date,p_TO_DATE date,p_LOAI_KQ number) return varchar2 IS
cursor pn_qc_cur is
       select NGAY_BIEN_BAN ngay_phan_loai,MA_PHAN_LOAI ma_loai
       from PN_PHAN_LOAI_GIAM_GIU
       where PN_ID=P_PN_ID and NGAY_BIEN_BAN>=P_from_date and NGAY_BIEN_BAN<=p_to_Date
       order by NGAY_BIEN_BAN;
pn_qc_rec pn_qc_cur%rowtype;
P_ngay_pl varchar2(20);
p_ma_loai varchar2(4);
count_rec number(4);
p_ketqua varchar2(2000);
BEGIN
	count_Rec:=0;
	for pn_qc_Rec in pn_qc_cur
	loop
		count_rec:=count_Rec+1;
		p_ma_Loai:=pn_qc_rec.ma_loai;
		p_ngay_pl:=pn_qc_rec.ngay_phan_loai;
	end loop;
	if count_Rec>0 then
		if p_ngay_pl is null then p_ketqua:=to_char(sysdate,'dd/mm/yyyy');else p_ketqua:=p_ngay_pl;end if;
		p_ketqua:=P_ketqua||'@'||p_ma_loai;
	else
		return null;
	end if;
	if p_LOAI_KQ=1 then -- tra ve loai QC
		return 	p_ma_Loai;
	elsif p_LOAI_KQ=2 then -- tra ve ngay xl
		return 	p_ngay_pl;
	else
		if p_ketqua is not null then 	return p_ketqua;end if;
	end if;
	return null;
End; --- Of GET_KET_QUA_PLGG_HIEN_TAI

/************ GET_MA_NANG_HA_LOAI_PLGG function *********************
 Function: L?y k?t qu? nang, h? phan lo?i giam gi? trong m?t kho?ng th?i gian
 10: H? lo?i Qu?n ch?
 20: Nang lo?i qu?n ch?
 30: Gi? nguyen Qu?n ch?
 0: Khong co qu?n ch?
*/

Function GET_MA_NANG_HA_LOAI_PLGG(P_PN_ID varchar2,p_ngay_moc date ) RETURN number IS
-- Created: Nguyen Van Khuyen
-- Date:    Mon, Jan 23, 2006
-- Function: Lay ma phan loai quan che nang hay ha
-- Value return: 1 - nang, -1 ha, 0 khong doi
p_ngay_bien_ban_truoc date;
p_ngay_bien_ban_sau date;
p_ma_pl_truoc number(2);
p_ma_pl_sau number(2);
p_ketqua number(4):=0;
Procedure SET_PHAN_LOAI_GIAM_GIU(P_PN_ID varchar2,p_ngay_moc_set_pl date,p_ngay_bien_ban_qc out date,p_ma_loai out number) IS
cursor QC_CUR is
              select ngay_bien_ban,to_number(ma_phan_loai) ma_loai
              from PN_PHAN_LOAI_GIAM_GIU
              where PN_ID=P_PN_ID and ngay_bien_ban<=p_ngay_moc_set_pl
              order by ngay_bien_ban;
QC_REC QC_CUR%rowtype;
p_ngay_bien_ban date;
p_ma_Loai_qc varchar2(20);
num_rec number(2):=0;
Begin
 for qc_rec in qc_cur
 loop
  num_rec:=num_rec+1;
  if qc_rec.ngay_bien_ban is not null then
   p_ngay_bien_ban:=qc_rec.ngay_bien_ban;
  else
   p_ngay_bien_ban:=p_ngay_moc_set_Pl;
  end if;
  p_ma_Loai_qc:=qc_rec.ma_loai;
 end loop;
 if num_rec>0 then
  p_ngay_bien_ban_qc:=p_ngay_bien_ban;
  p_ma_loai:=to_number(p_ma_Loai_qc);
 else
  p_ngay_bien_ban_qc:=null;
  p_ma_loai:=0;
 end if;
 End;  --- of SET_PHAN_LOAI_GIAM_GIU (of GET_MA_NANG_HA_LOAI_QUAN_CHE);
BEGIN
 SET_PHAN_LOAI_GIAM_GIU(P_PN_ID,P_ngay_moc,P_ngay_bien_ban_SAU,P_MA_PL_SAU);
 if p_ngay_bien_ban_sau is null and p_ma_pl_sau=0 then
  p_ketqua:=0;
 else
   SET_PHAN_LOAI_GIAM_GIU(P_PN_ID,P_ngay_bien_ban_SAU-2,P_ngay_bien_ban_TRUOC,P_MA_PL_TRUOC);
   if P_ngay_bien_ban_TRUOC is null and P_MA_PL_TRUOC=0 then
    p_ketqua:=0;
   else
     if P_MA_PL_TRUOC>P_MA_PL_SAU then -- h? loai quan che
      p_ketqua:=10;
     elsif P_MA_PL_TRUOC<P_MA_PL_SAU then -- nang loai quan che
      p_ketqua:=20;
     elsif P_MA_PL_TRUOC=P_MA_PL_SAU then -- giu nguyen
      p_ketqua:=30;
     else
      p_ketqua:=0;
     end if;
   end if;
 end if;
return p_ketqua;
End;  -- of Get_Ma_Nang_HA_loai_PLGG

