/************ GET_LOAI_PHAM_NHAN function *********************
 Function: Phan loai pham nhan theo Phap lenh Thi hanh an 1993
 1: Ph?m nhan Lo?i I
 2: Ph?m nhan Lo?i II
 3: Ph?m nhan Lo?i III
*/
Function GET_LOAI_PHAM_NHAN(p_ma_toi_danh varchar2,p_ma_muc_an_phat varchar2,p_ma_tai_pham varchar2) RETURN number is
-- Created: Nguyen Van Khuyen
-- Date:    Mon, Jan 23, 2006
-- Function: Lay ma phan loai quan che nang hay ha
-- Value return: 1 - nang, -1 ha, 0 khong doi
p_MA_TOI_DAU number(4);
p_so_thang_an_phat number(10):=0;
p_LOAI_PN number(4):=0;
BEGIN
	p_ma_toi_Dau:=to_number(substr(p_ma_toi_Danh,1,3));
	if p_ma_toi_Dau<=92 then --- cac toi ANQG la loai I
		p_LOAI_PN:=1;
	else
		if to_number(p_ma_muc_an_phat) in (911000,912000) then --- an chung than la LOAI I
			p_LOAI_PN:=1;
		else  -- an co thoi han
			p_so_thang_an_phat:=to_number(substr(p_ma_Muc_an_phat,2,2))*12+to_number(substr(p_ma_Muc_an_phat,4,2));
			if p_so_thang_an_phat>=240 and p_so_thang_an_phat<=360 then -- an tu 20 nam tro len la loai I
				p_LOAI_PN:=1;
			else  -- an duoi 20 nam thi kiem tra xem tai pham
				if p_ma_tai_pham=2  then -- tai pham nguy hiem la loai I
					P_LOAI_PN:=1;
				else  -- neu khong thi kiem tra
					if p_so_thang_an_phat>60 and p_so_thang_an_phat<240 then -- an tu tren 5 nawm den duoi 10 nam la loai I
						P_LOAI_PN:=2;
					else
						P_LOAI_PN:=3;
					end if;
				end if;
			end if;
		end if;
	end if;
  return p_LOAI_PN;
End; --- of GET_LOAI_PHAM_NHAN
/************ GET_QUAN_HE_GIA_DINH function *********************
 Function: Phan loai pham nhan theo Phap lenh Thi hanh an 1993
 */
Function GET_QUAN_HE_GIA_DINH(p_pn_id varchar2,p_ma_quan_he varchar2) RETURN varchar2 is
-- Created: Nguyen Van Khuyen
-- Date:    Mon, May 31th, 2010
-- Function: Lay ma phan loai quan che nang hay ha
-- Value return: 1 - nang, -1 ha, 0 khong doi
p_hoten varchar2(200);
BEGIN
  select HO_TEN_QHGD into p_hoten from pn_quan_he_gia_dinh
  where pn_id=p_pn_id and ma_quan_he=p_ma_quan_he;
  if p_hoten is not null then
  	return p_hoten;
  end if;
	exception
	  when no_data_found then return null;
	  when others then return p_hoten;
	return null;
End; --- of GET_QUAN_HE_GIA_DINH
END; --- Of pn_DB Package Body 20/12/2011


