  CREATE OR REPLACE EDITIONABLE PACKAGE BODY "QLPN_SUOI_HAI"."PN_DX" IS
FUNCTION GET_CHUOI_KQCT(P_PN_ID VARCHAR2,P_NGAY_XET DATE,P_MA_MUC_AN_PHAT VARCHAR2) RETURN VARCHAR2 IS
  NUM_REC NUMBER(4):=0;
  P_SO_NAM_CT NUMBER(4):=0;
  P_SO_NGAY_AN_PHAT NUMBER(10):=0;
  P_DATA VARCHAR2(100);
  P_XLQUY VARCHAR2(100);
  P_XLQUY_LAST VARCHAR2(100);
  P_DATA_CT VARCHAR2(100);

BEGIN
  IF TO_NUMBER(P_MA_MUC_AN_PHAT) IN (911000,912000) THEN
    P_SO_NGAY_AN_PHAT:=100*12*30;
  ELSE
    P_SO_NGAY_AN_PHAT:=PN_SYS.GET_NUMBER_FROM_MA_STRING(P_MA_MUC_AN_PHAT,'SD');
  END IF;
  IF P_SO_NGAY_AN_PHAT=36000 THEN
    P_SO_NAM_CT:=5;
  ELSIF P_SO_NGAY_AN_PHAT>5400 AND P_SO_NGAY_AN_PHAT<=10800 THEN
    P_SO_NAM_CT:=4;
  ELSIF P_SO_NGAY_AN_PHAT>3600 AND P_SO_NGAY_AN_PHAT<=5400 THEN
    P_SO_NAM_CT:=3;
  ELSIF P_SO_NGAY_AN_PHAT>2520 AND P_SO_NGAY_AN_PHAT<=3600 THEN
    P_SO_NAM_CT:=3;
  ELSIF P_SO_NGAY_AN_PHAT>1800 AND P_SO_NGAY_AN_PHAT<=2520 THEN
    P_SO_NAM_CT:=2;
  ELSIF P_SO_NGAY_AN_PHAT>1080 AND P_SO_NGAY_AN_PHAT<=1800 THEN
    P_SO_NAM_CT:=1;
  ELSE
    P_SO_NAM_CT:=1;
  END IF;
 FOR OBJ IN (SELECT NAM_XL
          ,DECODE(MA_XEP_LOAI_Q1,'110','B','210','B','120','C','220','C','130','D','230','D','140','E','240','E','A') QUY1
          ,DECODE(MA_XEP_LOAI_Q2,'110','B','210','B','120','C','220','C','130','D','230','D','140','E','240','E','A') QUY2
          ,DECODE(MA_XEP_LOAI_DAU,'110','B','210','B','120','C','220','C','130','D','230','D','140','E','240','E','A') DAU_NAM
          ,DECODE(MA_XEP_LOAI_Q3,'110','B','210','B','120','C','220','C','130','D','230','D','140','E','240','E','A') QUY3

          ,DECODE(MA_XEP_LOAI_CUOI,'110','B','210','B','120','C','220','C','130','D','230','D','140','E','240','E','A') CUOI_NAM
          ,DECODE(MA_XEP_LOAI_CA,'110','B','210','B','120','C','220','C','130','D','230','D','140','E','240','E','A') CA_NAM

    FROM PN_KET_QUA_CAI_TAO
    WHERE PN_ID=P_PN_ID  AND NAM_XL>=TO_NUMBER(TO_CHAR(P_NGAY_XET,'YYYY'))-P_SO_NAM_CT AND NAM_XL<=TO_NUMBER(TO_CHAR(P_NGAY_XET,'YYYY'))
    ORDER BY NAM_XL)
  LOOP
    P_DATA:='';
    NUM_REC:=NUM_REC+1;
    IF OBJ.DAU_NAM='A' THEN
    IF OBJ.NAM_XL='2015' THEN
     P_XLQUY_LAST:=OBJ.QUY1;
    END IF;
     IF OBJ.QUY2 IS NOT NULL THEN
        P_XLQUY:=OBJ.QUY2;
     ELSE
        P_XLQUY:=OBJ.QUY1;
     END IF;
     IF OBJ.CUOI_NAM<>'A' THEN
         IF OBJ.QUY3 IS NOT NULL THEN
            P_XLQUY:=OBJ.QUY3;
         END IF;
        P_DATA:=OBJ.CUOI_NAM;
     END IF;
    ELSE
      IF OBJ.CUOI_NAM='A' THEN
        P_DATA:=OBJ.DAU_NAM;
      ELSE
        P_DATA:=OBJ.DAU_NAM||OBJ.CUOI_NAM;
      END IF;
    END IF;
    IF P_DATA_CT IS NULL THEN
      P_DATA_CT:=P_DATA;
    ELSE
      P_DATA_CT:=P_DATA_CT||P_DATA;
    END IF;
  END LOOP;
  P_DATA_CT:=P_DATA_CT||P_XLQUY_LAST;
  RETURN P_DATA_CT;
END;

FUNCTION GET_SO_NAM_KQCT_DX(P_PN_ID VARCHAR2,P_NGAY_XET_DX DATE,P_MA_MUC_AN_PHAT VARCHAR2) RETURN NUMBER IS
SO_NAM NUMBER(4);
P_SO_NGAY_AN_PHAT NUMBER(10);

BEGIN
  P_SO_NGAY_AN_PHAT:=PN_SYS.GET_NUMBER_FROM_MA_STRING(P_MA_MUC_AN_PHAT,'SD');

   IF TO_NUMBER(P_MA_MUC_AN_PHAT) IN (911000,912000) THEN
     SO_NAM:=4;
   ELSE
    IF P_SO_NGAY_AN_PHAT>5400 THEN
      SO_NAM:=3;
    ELSIF P_SO_NGAY_AN_PHAT>3600 AND P_SO_NGAY_AN_PHAT<=5400 THEN
      SO_NAM:=2;
    ELSIF P_SO_NGAY_AN_PHAT>2520 AND P_SO_NGAY_AN_PHAT<=3600 THEN
      SO_NAM:=2;
    ELSIF P_SO_NGAY_AN_PHAT>1800 AND P_SO_NGAY_AN_PHAT<=2520 THEN
      SO_NAM:=1;
    ELSIF P_SO_NGAY_AN_PHAT>1080 AND P_SO_NGAY_AN_PHAT<=1800 THEN
      SO_NAM:=1;
    ELSIF P_SO_NGAY_AN_PHAT>0 AND P_SO_NGAY_AN_PHAT<=1080 THEN
        SO_NAM:=0;
    ELSE
       SO_NAM:=0;
     END IF;
  END IF;
    RETURN SO_NAM;
END;





FUNCTION GET_DIEU_KIEN_DX_TGCH(P_PN_ID VARCHAR2,P_NGAY_XET DATE,P_MA_TOI_DANH VARCHAR2,P_MA_MUC_AN_PHAT VARCHAR2,P_SO_TIEN_AN NUMBER,P_MA_GHI_CHU_RIENG VARCHAR2,P_NGAY_HET_HAN DATE) RETURN NUMBER IS



TONG_SO_THANG_AN_PHAT NUMBER:=0;
TONG_SO_THANG_CHAP_HANH NUMBER:=0;
TONG_SO_THANG_CON_LAI NUMBER:=0;
SO_LAN_GIAM NUMBER(4):=0;
NUM_REC_DX NUMBER(4):=0;
NUM_REC_NGHIEN_MT NUMBER(4):=0;
--NUM_REC_HPBS NUMBER(4):=0;
--P_TONG_TIEN_BI_PHAT NUMBER:=0;
--P_TONG_TIEN_DA_HOAN NUMBER:=0;
CMAGCR NUMBER:=0;
P_DIEU_KIEN NUMBER:=2000;
BEGIN

  TONG_SO_THANG_AN_PHAT:=GET_THANG(P_MA_MUC_AN_PHAT);

  TONG_SO_THANG_CHAP_HANH:=GET_THANG(PN_GET.MA_TG_CHAP_HANH(P_PN_ID,P_NGAY_XET));

  TONG_SO_THANG_CON_LAI:=GET_THANG(PN_GET.MA_TG_CON_LAI(P_PN_ID,P_NGAY_XET));



IF TO_NUMBER(P_MA_MUC_AN_PHAT) IN (911000,912000) THEN
  IF TONG_SO_THANG_CHAP_HANH<15*12 THEN
    P_DIEU_KIEN:=2111;
  ELSIF TONG_SO_THANG_CHAP_HANH>=13*12 AND TONG_SO_THANG_CHAP_HANH<15*12 THEN
    SELECT COUNT(*) INTO CMAGCR FROM MA_GHI_CHU_RIENG M WHERE MA<='2500' AND INSTR(P_MA_GHI_CHU_RIENG,MA)>0;
    IF CMAGCR>0 THEN

      IF TONG_SO_THANG_CON_LAI>8*12 THEN
        P_DIEU_KIEN:=2417;
      ELSE
        P_DIEU_KIEN:=1110;
      END IF;
    ELSE
      P_DIEU_KIEN:=2112;
    END IF;
  ELSE

    IF TONG_SO_THANG_CON_LAI>6*12 THEN
      P_DIEU_KIEN:=2415;
    ELSE
      SELECT COUNT(*) INTO SO_LAN_GIAM FROM PN_GIAM_THOI_HAN WHERE PN_ID=P_PN_ID AND MA_MUC_QD_GIAM_TOA_AN IN ('921000','922000');
      IF SO_LAN_GIAM=0 THEN
        P_DIEU_KIEN:=2411;
      ELSE
        P_DIEU_KIEN:=1120;
      END IF;
    END IF;

  END IF;

ELSE
  IF 4*TONG_SO_THANG_CHAP_HANH<TONG_SO_THANG_AN_PHAT THEN
      P_DIEU_KIEN:=2121;
  ELSIF 4*TONG_SO_THANG_CHAP_HANH>=TONG_SO_THANG_AN_PHAT AND 3*TONG_SO_THANG_CHAP_HANH<TONG_SO_THANG_AN_PHAT THEN

    CMAGCR:=0;
    SELECT COUNT(*) INTO CMAGCR FROM MA_GHI_CHU_RIENG M WHERE MA<='2500' AND INSTR(P_MA_GHI_CHU_RIENG,MA)>0;
    IF CMAGCR>0 THEN
      IF TONG_SO_THANG_CON_LAI>8*12 THEN
        P_DIEU_KIEN:=2417;
      ELSE
        P_DIEU_KIEN:=1210;
      END IF;
    ELSE
      P_DIEU_KIEN:=2122;
    END IF;



ELSE
    P_DIEU_KIEN:=1200;
    if TONG_SO_THANG_AN_PHAT>=10*12  AND PN_RANGE.IN_STRING('093;094;095;096;097;098;099;100;101;102;103;104;105;106;107;108;109;110;111;112;113;114;115;116;117;118;119;120;121;122;
    1123;1124;1125;1126;1127;1128;1129;1130;1131;1132;1133;1134;1135;1136;1137;1138;1139;1140;1141;1142;1143;1144;1145;1146;1147;1148;1149;1150;1151;1152;1153;1154;1155;1156',P_MA_TOI_DANH,9)>0
    and 3*TONG_SO_THANG_CHAP_HANH<2*TONG_SO_THANG_AN_PHAT  ----- note
    then
    P_DIEU_KIEN:=2100;
    end if;
    if TONG_SO_THANG_AN_PHAT>=7*12  AND PN_RANGE.IN_STRING('133;134;194c;194d;196;193;1168;1169;1251;1252;1248',P_MA_TOI_DANH,9)>0
    and 3*TONG_SO_THANG_CHAP_HANH<2*TONG_SO_THANG_AN_PHAT  ----- note
    then
    P_DIEU_KIEN:=2100;
    end if;
  END IF;
END IF;

IF P_DIEU_KIEN>=2000 THEN RETURN P_DIEU_KIEN;END IF;



  IF NVL(P_NGAY_HET_HAN,P_NGAY_XET+1)<=P_NGAY_XET THEN
    RETURN 2401;
  END IF;

  IF INSTR(NVL(P_MA_GHI_CHU_RIENG,'9999'),'9929')>0 THEN
    RETURN 2403;
  END IF;

  IF TO_NUMBER(NVL(SUBSTR(P_MA_GHI_CHU_RIENG,1,4),'9999'))=9930 THEN
    RETURN 2405;
  END IF;

  IF NVL(P_SO_TIEN_AN,0)>=2 THEN
    RETURN 2409;
  END IF;

  SELECT COUNT(*) INTO NUM_REC_DX FROM PN_TIEN_AN WHERE PN_ID=P_PN_ID AND NVL(TO_NUMBER(MA_GHI_CHU_TA),90)=30;
  IF NUM_REC_DX>0 THEN
    RETURN 2407;
  END IF;
  IF PN_RANGE.IN_STRING('9928',P_MA_GHI_CHU_RIENG,9)>0 THEN
    RETURN 2407;
  END IF;

  IF PN_RANGE.IN_STRING('078;079;080;081;082;083;084;085;086;087;088;089;090;091',P_MA_TOI_DANH,9)>0  THEN
    IF TONG_SO_THANG_AN_PHAT>7*12 THEN
      RETURN 2413;
    END IF;
  END IF;


  IF PN_RANGE.IN_STRING('192;193;194;195;196;197;198;200;201',P_MA_TOI_DANH,9)>0 THEN

    IF TONG_SO_THANG_AN_PHAT<=7*12 THEN
      IF TONG_SO_THANG_CON_LAI>12 THEN
        RETURN 2419;
      END IF;
    ELSIF TONG_SO_THANG_AN_PHAT>7*12 AND TONG_SO_THANG_AN_PHAT<=15*12  THEN
      IF TONG_SO_THANG_CON_LAI>12*2 THEN
        RETURN 2421;
      END IF;
    ELSE
      IF TONG_SO_THANG_CON_LAI>3*12 THEN
        RETURN 2423;
      END IF;
    END IF;
  END IF;








  SELECT COUNT(*) INTO NUM_REC_NGHIEN_MT FROM PN_DOI_TUONG_NGHIEN_MT WHERE PN_ID=P_PN_ID;
  IF NUM_REC_NGHIEN_MT>0 THEN
    RETURN 2425;
  END IF;
  IF PN_RANGE.IN_STRING('9919',P_MA_GHI_CHU_RIENG,9)>0 THEN
    RETURN 2425;
  END IF;

  IF COUNTSTR(P_MA_TOI_DANH)>0 THEN
    RETURN 2433;
  END IF;


IF PN_RANGE.IN_STRING('093;094;095;096',P_MA_TOI_DANH,9)>0 AND PN_RANGE.IN_STRING('138',P_MA_TOI_DANH,9)>0 THEN
    RETURN 2426;
  END IF;

  IF PN_RANGE.IN_STRING('093;094;095;096',P_MA_TOI_DANH,9)>0 AND PN_RANGE.IN_STRING('133;136',P_MA_TOI_DANH,9)>0 THEN
    RETURN 2427;
  END IF;

  IF PN_RANGE.IN_STRING('138',P_MA_TOI_DANH,9)>0 AND PN_RANGE.IN_STRING('133;136',P_MA_TOI_DANH,9)>0 THEN
    RETURN 2428;
  END IF;

  IF PN_RANGE.IN_STRING('093;094;095;096',P_MA_TOI_DANH,9)>0 AND PN_RANGE.IN_STRING('111;112',P_MA_TOI_DANH,9)>0 THEN
    RETURN 2429;
  END IF;

  IF PN_RANGE.IN_STRING('133',P_MA_TOI_DANH,9)>0 AND PN_RANGE.IN_STRING('136',P_MA_TOI_DANH,9)>0 THEN
    RETURN 2430;
  END IF;

  IF PN_RANGE.IN_STRING('133;136',P_MA_TOI_DANH,9)>0 AND PN_RANGE.IN_STRING('111;112',P_MA_TOI_DANH,9)>0 THEN
    RETURN 2431;
  END IF;

  IF PN_RANGE.IN_STRING('138',P_MA_TOI_DANH,9)>0 AND PN_RANGE.IN_STRING('111;112',P_MA_TOI_DANH,9)>0 THEN
    RETURN 2432;
  END IF;

  IF PN_RANGE.IN_STRING('093;094;095;096',P_MA_TOI_DANH,9)>0  AND PN_RANGE.IN_STRING('9933',P_MA_GHI_CHU_RIENG,9)>0 THEN
    RETURN 2435;
  END IF;

  IF PN_RANGE.IN_STRING('133;136',P_MA_TOI_DANH,9)>0  AND PN_RANGE.IN_STRING('9931',P_MA_GHI_CHU_RIENG,9)>0 THEN
    RETURN 2437;
  END IF;

  IF PN_RANGE.IN_STRING('133;136',P_MA_TOI_DANH,9)>0  AND PN_RANGE.IN_STRING('9933',P_MA_GHI_CHU_RIENG,9)>0 THEN
    RETURN 2439;
  END IF;

  IF PN_RANGE.IN_STRING('138',P_MA_TOI_DANH,9)>0  AND PN_RANGE.IN_STRING('9933',P_MA_GHI_CHU_RIENG,9)>0 THEN
    RETURN 2441;
  END IF;

  IF PN_RANGE.IN_STRING('133;136;138',P_MA_TOI_DANH,9)>0  AND PN_RANGE.IN_STRING('9932',P_MA_GHI_CHU_RIENG,9)>0 THEN
    RETURN 2443;
  END IF;


  IF NVL(P_SO_TIEN_AN,0)=1 THEN


      IF PN_RANGE.IN_STRING('192;193;194;195;196;197;198;199;200;201',P_MA_TOI_DANH,9)>0 THEN
        RETURN 2445;
      END IF;

        IF PN_RANGE.IN_STRING('093;094;095;096',P_MA_TOI_DANH,9)>0 THEN
          RETURN 2447;
        END IF;

        IF PN_RANGE.IN_STRING('111;112',P_MA_TOI_DANH,9)>0 THEN
          RETURN 2449;
        END IF;

        IF PN_RANGE.IN_STRING('133;136',P_MA_TOI_DANH,9)>0 THEN
          RETURN 2451;
        END IF;

        IF PN_RANGE.IN_STRING('135',P_MA_TOI_DANH,9)>0 THEN
          RETURN 2453;
        END IF;

        IF PN_RANGE.IN_STRING('139',P_MA_TOI_DANH,9)>0 THEN
          RETURN 2455;
        END IF;

        IF PN_RANGE.IN_STRING('138',P_MA_TOI_DANH,9)>0 THEN
          RETURN 2457;
        END IF;

        IF PN_RANGE.IN_STRING('134',P_MA_TOI_DANH,9)>0 THEN
          RETURN 2459;
        END IF;

        IF PN_RANGE.IN_STRING('257',P_MA_TOI_DANH,9)>0 THEN
          RETURN 2461;
        END IF;


        IF PN_RANGE.IN_STRING('119',P_MA_TOI_DANH,9)>0 THEN
          RETURN 2463;
        END IF;

        IF PN_RANGE.IN_STRING('120',P_MA_TOI_DANH,9)>0 THEN
          RETURN 2465;
        END IF;


        IF PN_RANGE.IN_STRING('245',P_MA_TOI_DANH,9)>0 THEN
          RETURN 2467;
        END IF;

        IF PN_RANGE.IN_STRING('250',P_MA_TOI_DANH,9)>0 THEN
          RETURN 2469;
        END IF;


        IF PN_RANGE.IN_STRING('104',P_MA_TOI_DANH,9)>0 AND PN_RANGE.IN_STRING('9934',P_MA_GHI_CHU_RIENG,9)>0 THEN
          RETURN 2471;
        END IF;

  END IF;
  RETURN P_DIEU_KIEN;
END;

FUNCTION GET_DIEU_KIEN_DX_HPBS(P_PN_ID VARCHAR2,P_NGAY_XET DATE) RETURN NUMBER IS

--TONG_SO_NGAY_AN_PHAT NUMBER(10):=0;
--TONG_SO_NGAY_CHAP_HANH NUMBER(10):=0;
--TONG_SO_NGAY_CON_LAI NUMBER(10):=0;
--SO_LAN_GIAM NUMBER(4):=0;
--NUM_REC_DX NUMBER(4):=0;
--NUM_REC_NGHIEN_MT NUMBER(4):=0;
NUM_REC_HPBS NUMBER(4):=0;
P_TONG_TIEN_BI_PHAT NUMBER(15):=0;
P_TONG_TIEN_DA_HOAN NUMBER(15):=0;
P_DIEU_KIEN NUMBER(10):=0;
BEGIN

  SELECT COUNT(*) INTO NUM_REC_HPBS FROM PN_HPBS_HINH_PHAT
  WHERE PN_ID=P_PN_ID AND TO_NUMBER(MA_HINH_PHAT)>=201
  AND TO_NUMBER(MA_HINH_PHAT)<=299;
  IF NUM_REC_HPBS>0 THEN
    FOR OBJ IN (
      SELECT MA_PN_HPBSHP,MA_HINH_PHAT MA_HP,NVL(TONG_TIEN_PHAT,0) SO_TIEN_PHAT FROM PN_HPBS_HINH_PHAT
      WHERE PN_ID=P_PN_ID  AND TO_NUMBER(MA_HINH_PHAT)>=201 AND TO_NUMBER(MA_HINH_PHAT)<=299 AND NVL(TO_NUMBER(MA_GHI_CHU_HPBS),0) NOT IN (10,11,12,13)
    )
    LOOP
      P_TONG_TIEN_BI_PHAT:=P_TONG_TIEN_BI_PHAT+OBJ.SO_TIEN_PHAT;

      FOR OBJ2 IN (SELECT NVL(SO_TIEN_NOP,0) SO_TIEN_HOAN FROM PN_HPBS_THUC_HIEN
      WHERE MA_PN_HPBSHP=OBJ.MA_PN_HPBSHP AND NVL(NGAY_NOP,P_NGAY_XET)<=P_NGAY_XET
      )
      LOOP
         P_TONG_TIEN_DA_HOAN:=P_TONG_TIEN_DA_HOAN+NVL(OBJ2.SO_TIEN_HOAN,0);
     END LOOP;

    END LOOP;


      IF P_TONG_TIEN_DA_HOAN<P_TONG_TIEN_BI_PHAT THEN
        RETURN 2473;
      END IF;
  END IF;
  RETURN P_DIEU_KIEN;
END;




FUNCTION GET_DIEU_KIEN_DX_KQCT(P_PN_ID VARCHAR2,P_NGAY_XET DATE,P_MA_MUC_AN_PHAT VARCHAR2, THIEUKY NUMBER DEFAULT 0) RETURN NUMBER IS
  --LEN NUMBER(4):=0;
  NUM_REC NUMBER(4):=0;
  P_SO_NAM_CT NUMBER(4):=0;
  LEN_STR NUMBER(4):=0;
  P_SO_NGAY_AN_PHAT NUMBER(10):=0;
  P_DATA VARCHAR2(100);
  --P_XLQUY VARCHAR2(100);
  P_XLQUY3 VARCHAR2(100);
  P_XLQUY_LAST VARCHAR2(100);
  P_DATA_CT VARCHAR2(100);
  CCOUNT_XL_NAM  NUMBER;

BEGIN
  SELECT COUNT(*) INTO CCOUNT_XL_NAM FROM PN_OPEN_DOT_DAC_XA WHERE CHECK_XL_NAM=1;
  IF TO_NUMBER(P_MA_MUC_AN_PHAT) IN (911000,912000) THEN
    P_SO_NGAY_AN_PHAT:=100*12*30;
  ELSE
    P_SO_NGAY_AN_PHAT:=PN_SYS.GET_NUMBER_FROM_MA_STRING(P_MA_MUC_AN_PHAT,'SD');
  END IF;
  IF P_SO_NGAY_AN_PHAT=36000 THEN
    P_SO_NAM_CT:=5;
  ELSIF P_SO_NGAY_AN_PHAT>5400 AND P_SO_NGAY_AN_PHAT<=10800 THEN
    P_SO_NAM_CT:=4;
  ELSIF P_SO_NGAY_AN_PHAT>3600 AND P_SO_NGAY_AN_PHAT<=5400 THEN
    P_SO_NAM_CT:=3;
  ELSIF P_SO_NGAY_AN_PHAT>2520 AND P_SO_NGAY_AN_PHAT<=3600 THEN
    P_SO_NAM_CT:=3;
  ELSIF P_SO_NGAY_AN_PHAT>1800 AND P_SO_NGAY_AN_PHAT<=2520 THEN
    P_SO_NAM_CT:=2;
  ELSIF P_SO_NGAY_AN_PHAT>1080 AND P_SO_NGAY_AN_PHAT<=1800 THEN
    P_SO_NAM_CT:=1;
  ELSE
    P_SO_NAM_CT:=1;
  END IF;

 FOR OBJ IN (SELECT NAM_XL
          ,DECODE(MA_XEP_LOAI_Q1,'110','B','210','B','120','C','220','C','130','D','230','D','140','E','240','E',NULL,'A','E') QUY1
          ,DECODE(MA_XEP_LOAI_Q2,'110','B','210','B','120','C','220','C','130','D','230','D','140','E','240','E',NULL,'A','E') QUY2
          ,(CASE
            WHEN CCOUNT_XL_NAM=1 AND NAM_XL<2016 THEN DECODE(MA_XEP_LOAI_CA,'110','B','210','B','120','C','220','C','130','D','230','D','140','E','240','E',NULL,'A','E')
            ELSE DECODE(MA_XEP_LOAI_DAU,'110','B','210','B','120','C','220','C','130','D','230','D','140','E','240','E',NULL,'A','E')
          END) DAU_NAM

          ,DECODE(MA_XEP_LOAI_Q3,'110','B','210','B','120','C','220','C','130','D','230','D','140','E','240','E',NULL,'A','E') QUY3

          ,DECODE(MA_XEP_LOAI_CUOI,'110','B','210','B','120','C','220','C','130','D','230','D','140','E','240','E',NULL,'A','E') CUOI_NAM
          ,DECODE(MA_XEP_LOAI_CA,'110','B','210','B','120','C','220','C','130','D','230','D','140','E','240','E',NULL,'A','E') CA_NAM

    FROM PN_KET_QUA_CAI_TAO
    WHERE PN_ID=P_PN_ID  AND NAM_XL>=TO_NUMBER(TO_CHAR(P_NGAY_XET,'YYYY'))-P_SO_NAM_CT AND NAM_XL<=TO_NUMBER(TO_CHAR(P_NGAY_XET,'YYYY'))
    ORDER BY NAM_XL)
  LOOP
    P_DATA:='';
    NUM_REC:=NUM_REC+1;
    IF OBJ.NAM_XL=2016 THEN
     IF OBJ.QUY3 <>'A' THEN
          P_XLQUY3:=OBJ.QUY3;
       END IF;
    END IF;
    IF OBJ.DAU_NAM='A' THEN
      IF OBJ.NAM_XL=2016 THEN
        IF OBJ.QUY2 <>'A' THEN
          P_XLQUY_LAST:=OBJ.QUY2;


       END IF;
      END IF;
     IF OBJ.CUOI_NAM<>'A' THEN



        P_DATA:=OBJ.CUOI_NAM;
     END IF;
    ELSE
    IF OBJ.NAM_XL=2016 THEN
        IF OBJ.QUY2 <>'A' THEN
          P_XLQUY_LAST:=OBJ.QUY2;
       END IF;
      END IF;
      IF OBJ.CUOI_NAM='A' THEN
        P_DATA:=OBJ.DAU_NAM;
      ELSE
        P_DATA:=OBJ.DAU_NAM||OBJ.CUOI_NAM;
      END IF;
    END IF;
    IF P_DATA_CT IS NULL THEN
      P_DATA_CT:=P_DATA;
    ELSE
      P_DATA_CT:=P_DATA_CT||P_DATA;
    END IF;
  END LOOP;

  IF P_XLQUY3 NOT IN ('B','C') THEN
     RETURN 2280;
  END IF;
  P_DATA_CT:=P_DATA_CT;



  LEN_STR:=NVL(LENGTH(P_DATA_CT),0);


  IF TO_NUMBER(P_MA_MUC_AN_PHAT) IN (911000,912000) THEN
      IF LEN_STR+THIEUKY<9 THEN
        RETURN 2211;
      ELSE
        P_DATA:=SUBSTR(P_DATA_CT,LEN_STR-8+THIEUKY);
        IF NVL(INSTR(P_DATA,'D'),0)<>0 OR NVL(INSTR(P_DATA,'E'),0)<>0 OR INSTR(P_DATA,'A')<>0 THEN
          RETURN 2212;
        ELSE
          RETURN 0;
        END IF;
      END IF;
  ELSE


    IF P_SO_NGAY_AN_PHAT>5400 THEN
      IF LEN_STR+THIEUKY<7 THEN
        RETURN 2221;
      ELSE
        P_DATA:=SUBSTR(P_DATA_CT,LEN_STR-6+THIEUKY);
        IF INSTR(P_DATA,'D')<>0 OR INSTR(P_DATA,'E')<>0 OR INSTR(P_DATA,'A')<>0 THEN
          RETURN 2222;
        ELSE
          RETURN 0;
        END IF;
      END IF;
    ELSIF P_SO_NGAY_AN_PHAT>3600 AND P_SO_NGAY_AN_PHAT<=5400 THEN
      IF LEN_STR+THIEUKY<5 THEN
        RETURN 2231;
      ELSE
        P_DATA:=SUBSTR(P_DATA_CT,LEN_STR-4+THIEUKY);
        IF INSTR(P_DATA,'D')<>0 OR INSTR(P_DATA,'E')<>0 OR INSTR(P_DATA,'A')<>0 THEN
          RETURN 2232;
        ELSE
          RETURN 0;
        END IF;
      END IF;
    ELSIF P_SO_NGAY_AN_PHAT>2520 AND P_SO_NGAY_AN_PHAT<=3600 THEN
      IF LEN_STR+THIEUKY<4 THEN
        RETURN 2241;
      ELSE
        P_DATA:=SUBSTR(P_DATA_CT,LEN_STR-3+THIEUKY);
        IF INSTR(P_DATA,'D')<>0 OR INSTR(P_DATA,'E')<>0 OR INSTR(P_DATA,'A')<>0 THEN
          RETURN 2242;
        ELSE
          RETURN 0;
        END IF;
      END IF;
    ELSIF P_SO_NGAY_AN_PHAT>1800 AND P_SO_NGAY_AN_PHAT<=2520 THEN
      IF LEN_STR+THIEUKY<3 THEN
        RETURN 2251;
      ELSE
        P_DATA:=SUBSTR(P_DATA_CT,LEN_STR-2+THIEUKY);
        IF INSTR(P_DATA,'D')<>0 OR INSTR(P_DATA,'E')<>0 OR INSTR(P_DATA,'A')<>0 THEN
          RETURN 2252;
        ELSE
          RETURN 0;
        END IF;
      END IF;
    ELSIF P_SO_NGAY_AN_PHAT>1080 AND P_SO_NGAY_AN_PHAT<=1800 THEN
        IF LEN_STR+THIEUKY<2 THEN
          RETURN 2261;
        ELSE
          P_DATA:=SUBSTR(P_DATA_CT,LEN_STR-1+THIEUKY);
          IF INSTR(P_DATA,'D')<>0 OR INSTR(P_DATA,'E')<>0 OR INSTR(P_DATA,'A')<>0 THEN
            RETURN 2262;
          ELSE
            RETURN 0;
          END IF;
        END IF;
    ELSIF P_SO_NGAY_AN_PHAT<=1080 THEN

    IF THIEUKY=0 THEN
      IF P_DATA_CT IS NOT NULL THEN
        P_DATA:=SUBSTR(P_DATA_CT,LEN_STR);

        IF INSTR(P_DATA,'D')<>0 OR INSTR(P_DATA,'E')<>0 OR INSTR(P_DATA,'A')<>0 THEN
          RETURN 2271;
        ELSE
          RETURN 0;
        END IF;
      ELSE
        RETURN 2271;
      END IF;
    ELSE
        IF NVL(P_XLQUY_LAST,'D') IN ('B','C') THEN
           RETURN 0;
         ELSE
           RETURN 2271;
         END IF;
      END IF;
    END IF;
  END IF;

  RETURN 0;
END;



FUNCTION GET_DIEU_KIEN_DAC_XA(P_PN_ID VARCHAR2,P_NGAY_XET DATE) RETURN NUMBER IS
P_MA_TOI_DANH VARCHAR(60);
--P_MA_TOI_DANH_CON_LAI VARCHAR(60);
P_MA_MUC_AN_PHAT VARCHAR2(7):='000000';
P_MA_GHI_CHU_RIENG VARCHAR2(60);
P_SO_TIEN_AN NUMBER(4):=0;
--P_SO_TIEN_SU NUMBER(4):=0;
P_NGAY_HET_HAN DATE;
CMAGCR NUMBER;
--P_DIEU_KIEN NUMBER(4):=2000;
P_DIEU_KIEN_KQCT NUMBER(4):=0;
--P_DIEU_KIEN_HPBS NUMBER(4):=0;
P_DIEU_KIEN_TGCH NUMBER:=2000;
THIEUKY          NUMBER:=0;
BEGIN


  SELECT MA_TOI_DANH,MA_MUC_AN_PHAT,NVL(SO_TIEN_AN,0),MA_GHI_CHU_RIENG,NVL(NGAY_RA_TRAI,P_NGAY_XET+1)
  INTO P_MA_TOI_DANH,P_MA_MUC_AN_PHAT,P_SO_TIEN_AN,P_MA_GHI_CHU_RIENG,P_NGAY_HET_HAN
  FROM PN_LAI_LICH
  WHERE PN_ID=P_PN_ID;


  P_DIEU_KIEN_TGCH:=GET_DIEU_KIEN_DX_TGCH(P_PN_ID,P_NGAY_XET,P_MA_TOI_DANH, P_MA_MUC_AN_PHAT,P_SO_TIEN_AN,P_MA_GHI_CHU_RIENG,P_NGAY_HET_HAN);
  CMAGCR:=0;
  SELECT COUNT(*) INTO CMAGCR FROM MA_GHI_CHU_RIENG M WHERE MA<='2500' AND INSTR(P_MA_GHI_CHU_RIENG,MA)>0;
  IF CMAGCR>0 THEN
    THIEUKY:=1;
  END IF;
  P_DIEU_KIEN_KQCT:=GET_DIEU_KIEN_DX_KQCT(P_PN_ID,P_NGAY_XET,P_MA_MUC_AN_PHAT,THIEUKY);
  --P_DIEU_KIEN:=P_DIEU_KIEN_TGCH;





  IF P_DIEU_KIEN_KQCT>2000 THEN
    RETURN P_DIEU_KIEN_KQCT;
  END IF;
  RETURN P_DIEU_KIEN_TGCH;
END;

FUNCTION GET_XLCT_DX(VPN_ID VARCHAR2, VNGAY_XET DATE,VKQCT OUT VARCHAR2, LOAI NUMBER DEFAULT 0)  RETURN VARCHAR2 IS
 MA_MUC_AN VARCHAR2(10);
 MUC_AN_THANG NUMBER;
 MA_GCR VARCHAR2(100);
 SO_TA NUMBER:=0;
 SO_KY NUMBER:=0;
 SO_KY_UT NUMBER:=0;
 --SO_KY_TA NUMBER:=0;
 LOAI_KY VARCHAR2(3);
 --CHIA_KY NUMBER:=0;
 SO_KY_THUC VARCHAR2(2000);
 SO_KY_THUC_DAI VARCHAR2(2000);


 --SO_KY2 NUMBER:=0;
 --SO_KY_UT2 NUMBER:=0;
 --SO_KY_TA2 NUMBER:=0;
 --LOAI_KY2 VARCHAR2(3);
 --CHIA_KY2 NUMBER:=0;
 --SO_KY_THUC2 VARCHAR2(2000);
 --SO_KY_THUC_DAI2 VARCHAR2(2000);

 VNAM_XL NUMBER;
 --VNGAYQDGTH DATE;
 --CGTH NUMBER;
 CMAGCR NUMBER;
 --VNGAY_30_04 DATE:=TO_DATE('30-APR-'||TO_CHAR(VNGAY_XET,'YYYY'),'DD-MON-YYYY');
 --VNGAY_25_08 DATE:=TO_DATE('25-AUG-'||TO_CHAR(VNGAY_XET,'YYYY'),'DD-MON-YYYY');
 --VNGAY_02_09 DATE:=TO_DATE('02-SEP-'||TO_CHAR(VNGAY_XET,'YYYY'),'DD-MON-YYYY');
 --VQUY_CUOI VARCHAR2(200);
 --VQUY_CUOI_DAI VARCHAR2(200);
 STRXL VARCHAR2(100);
 KYCN  VARCHAR2(100);
 KYCANAM VARCHAR2(200);
BEGIN
 SELECT T.MA_MUC_AN_PHAT, NVL(T.SO_TIEN_AN,0), GET_THANG(T.MA_MUC_AN_PHAT), T.MA_GHI_CHU_RIENG
   INTO MA_MUC_AN,SO_TA,MUC_AN_THANG, MA_GCR
     FROM PN_LAI_LICH T
       WHERE PN_ID=VPN_ID;
 SELECT COUNT(*) INTO CMAGCR FROM MA_GHI_CHU_RIENG M WHERE MA<='2500' AND INSTR(MA_GCR,MA)>0;

 IF MA_MUC_AN IN ('912000','911000') THEN
    SO_KY:=4*2+1; LOAI_KY:='K_'; SO_KY_UT:=1;
 ELSIF MUC_AN_THANG BETWEEN 15*12+0.01 AND 30*12 THEN
    SO_KY:=3*2+1; LOAI_KY:='K_'; SO_KY_UT:=1;
 ELSIF MUC_AN_THANG BETWEEN 10*12+0.01 AND 15*12 THEN
    SO_KY:=2*2+1; LOAI_KY:='K_'; SO_KY_UT:=1;
 ELSIF MUC_AN_THANG BETWEEN 7*12+0.01 AND 10*12 THEN
    SO_KY:=2*2; LOAI_KY:='K_'; SO_KY_UT:=1;
 ELSIF MUC_AN_THANG BETWEEN 5*12+0.01 AND 7*12 THEN
    SO_KY:=3; LOAI_KY:='K_'; SO_KY_UT:=1;
 ELSIF MUC_AN_THANG BETWEEN 3*12+0.01 AND 5*12 THEN
    SO_KY:=2; LOAI_KY:='K_'; SO_KY_UT:=1;
 ELSIF MUC_AN_THANG<=3*12  THEN
  IF CMAGCR=0 THEN
    SO_KY:=1; LOAI_KY:='K_'; SO_KY_UT:=1;
  ELSE
    SO_KY:=1; LOAI_KY:='Q_';
  END IF;
 END IF;


 IF CMAGCR>0 THEN
    SO_KY:=SO_KY-SO_KY_UT;
 END IF;

   IF SO_KY=0 THEN SO_KY:=1; END IF;

    FOR J IN (SELECT * FROM
                   (SELECT * FROM
                       (SELECT T.NAM_XL,T.XL,T.KY,T.KY_XEP_LOAI,T.XEP_LOAI,
                               T.MA_XEP_LOAI,T.NGAY_XL FROM V_PN_KQCT_DOC T
                            WHERE PN_ID=VPN_ID
                             AND T.KY_XL LIKE LOAI_KY
                              AND T.NGAY_XL<VNGAY_XET
                               AND NAM_XL>=TO_NUMBER(TO_CHAR(VNGAY_XET,'YYYY'))-ROUND(SO_KY/2)
                                ORDER BY NGAY_XL DESC)
       WHERE ROWNUM<=SO_KY)
       ORDER BY NGAY_XL
       )
    LOOP
     IF VNAM_XL<>J.NAM_XL OR VNAM_XL IS NULL THEN
      SO_KY_THUC:=SO_KY_THUC||CHR(10)||J.NAM_XL||': '||J.KY||': '||J.XL;
      SO_KY_THUC_DAI:=SO_KY_THUC_DAI||CHR(10)||'+ NA?m '||J.NAM_XL||': '||J.KY_XEP_LOAI||': '||J.XEP_LOAI;
     ELSE

      SELECT XL, XEP_LOAI INTO KYCN,KYCANAM FROM V_PN_KQCT_DOC T WHERE PN_ID=VPN_ID AND KY_XL='CA' AND NAM_XL=J.NAM_XL;

      SO_KY_THUC:=SO_KY_THUC||';'||J.KY||':'||J.XL||'; CN: '||KYCN;
      SO_KY_THUC_DAI:=SO_KY_THUC_DAI||'; '||J.KY_XEP_LOAI||': '||J.XEP_LOAI||'; Ca?# nA?m: '||KYCANAM;
     END IF;
     VNAM_XL:=J.NAM_XL;
     STRXL:=STRXL||J.MA_XEP_LOAI;

    END LOOP;


  VKQCT:=STRXL;
  IF LOAI=1 THEN
   RETURN SUBSTR(SO_KY_THUC_DAI,2);
  END IF;
   RETURN SUBSTR(SO_KY_THUC,2);
EXCEPTION
     WHEN OTHERS THEN RETURN NULL;
END;

FUNCTION GET_XLCT_DX_QUY(VPN_ID VARCHAR2, VNGAY_XET DATE,VKQCT OUT VARCHAR2, LOAI NUMBER DEFAULT 0, VCHUOI NUMBER DEFAULT 0)  RETURN VARCHAR2 IS
 MA_MUC_AN VARCHAR2(10);
 MUC_AN_THANG NUMBER;
 MA_GCR VARCHAR2(100);
 SO_TA NUMBER:=0;
 SO_KY NUMBER:=0;
 SO_KY_UT NUMBER:=0;
 ----SO_KY_TA NUMBER:=0;
 LOAI_KY VARCHAR2(3);
 --CHIA_KY NUMBER:=0;
 SO_KY_THUC VARCHAR2(2000);
 SO_KY_THUC_DAI VARCHAR2(2000);
 --STR_QUY_THUC VARCHAR2(2000);
 --STR_QUY_THUC_DAI VARCHAR2(2000);


 --SO_KY2 NUMBER:=0;
 --SO_KY_UT2 NUMBER:=0;
 --SO_KY_TA2 NUMBER:=0;
 --LOAI_KY2 VARCHAR2(3);
 --CHIA_KY2 NUMBER:=0;
 CHUOI_QUY_DAU VARCHAR2(2000);
 CHUOI_QUY VARCHAR2(2000);
 CHUOI_QUY_CUOI VARCHAR2(2000);
 --CHUOI_QUY_DAI VARCHAR2(2000);
 CHUOI_DAU_NAM VARCHAR2(1000);
 CHUOI_CUOI_NAM VARCHAR2(1000);
 CHUOI_CA_NAM VARCHAR2(1000);


 VNAM_XL NUMBER;
 --VNGAYQDGTH DATE;
 --CGTH NUMBER;
 CMAGCR NUMBER;
 --VNGAY_30_04 DATE:=TO_DATE('30-APR-'||TO_CHAR(VNGAY_XET,'YYYY'),'DD-MON-YYYY');
 --VNGAY_25_08 DATE:=TO_DATE('25-AUG-'||TO_CHAR(VNGAY_XET,'YYYY'),'DD-MON-YYYY');
 --VNGAY_02_09 DATE:=TO_DATE('02-SEP-'||TO_CHAR(VNGAY_XET,'YYYY'),'DD-MON-YYYY');
 --VQUY_CUOI VARCHAR2(200);
 --VQUY_CUOI_DAI VARCHAR2(200);
 STRXL VARCHAR2(100);
 KYCN  VARCHAR2(100);
 KYCANAM VARCHAR2(200);
BEGIN
 SELECT T.MA_MUC_AN_PHAT, NVL(T.SO_TIEN_AN,0), GET_THANG(T.MA_MUC_AN_PHAT), T.MA_GHI_CHU_RIENG
   INTO MA_MUC_AN,SO_TA,MUC_AN_THANG, MA_GCR
     FROM PN_LAI_LICH T
       WHERE PN_ID=VPN_ID;
 SELECT COUNT(*) INTO CMAGCR FROM MA_GHI_CHU_RIENG M WHERE MA<='2500' AND INSTR(MA_GCR,MA)>0;

 IF MA_MUC_AN IN ('912000','911000') THEN
    SO_KY:=100*2+1; LOAI_KY:='K_'; SO_KY_UT:=1;
 ELSIF MUC_AN_THANG BETWEEN 15*12+0.01 AND 30*12 THEN
    SO_KY:=100*2+1; LOAI_KY:='K_'; SO_KY_UT:=1;
 ELSIF MUC_AN_THANG BETWEEN 10*12+0.01 AND 15*12 THEN
    SO_KY:=100*2+1; LOAI_KY:='K_'; SO_KY_UT:=1;
 ELSIF MUC_AN_THANG BETWEEN 7*12+0.01 AND 10*12 THEN
    SO_KY:=100*2; LOAI_KY:='K_'; SO_KY_UT:=1;
 ELSIF MUC_AN_THANG BETWEEN 5*12+0.01 AND 7*12 THEN
    SO_KY:=100; LOAI_KY:='K_'; SO_KY_UT:=1;
 ELSIF MUC_AN_THANG BETWEEN 3*12+0.01 AND 5*12 THEN
    SO_KY:=100; LOAI_KY:='K_'; SO_KY_UT:=1;
 ELSIF MUC_AN_THANG<=3*12  THEN
  IF CMAGCR=0 THEN
    SO_KY:=100; LOAI_KY:='K_'; SO_KY_UT:=1;
  ELSE
    SO_KY:=100; LOAI_KY:='Q_';
  END IF;
 END IF;


 IF CMAGCR>0 THEN
    SO_KY:=SO_KY-SO_KY_UT;
 END IF;

   IF SO_KY=0 THEN SO_KY:=1; END IF;

    FOR J IN (SELECT * FROM
                   (SELECT * FROM
                       (SELECT T.NAM_XL,T.XL,T.KY_XL,T.KY,T.KY_XEP_LOAI,T.XEP_LOAI,
                               T.MA_XEP_LOAI,T.NGAY_XL FROM V_PN_KQCT_DOC T
                            WHERE PN_ID=VPN_ID
                             AND T.KY_XL LIKE LOAI_KY
                              AND T.NGAY_XL<VNGAY_XET
                               AND NAM_XL>=TO_NUMBER(TO_CHAR(VNGAY_XET,'YYYY'))-ROUND(SO_KY/2)
                                ORDER BY NGAY_XL DESC)
       WHERE ROWNUM<=SO_KY)
       ORDER BY NGAY_XL
       )
    LOOP

    IF LOAI=0 THEN
       SELECT 'Q1:'||XEP_LOAI_Q1||'; Q2:'||XEP_LOAI_Q2, 'Q3:'||XEP_LOAI_Q3||DECODE(XEP_LOAI_Q4,NULL,NULL,'; Q4:'||XEP_LOAI_Q4)
             --- ,'6TDN:'||XEP_LOAI_DAU,'6TCN:'||XEP_LOAI_CUOI ----,'; CN:'||XEP_LOAI_CA
            INTO CHUOI_QUY_DAU, CHUOI_QUY_CUOI---,CHUOI_DAU_NAM, CHUOI_CUOI_NAM----, CHUOI_CA_NAM
               FROM V_PN_XEP_LOAI_CAI_TAO WHERE PN_ID=VPN_ID AND NAM_XL=J.NAM_XL;
    ELSE
       SELECT 'Quy 1:'||XEP_LOAI_Q1||'; Quy 2:'||XEP_LOAI_Q2,
              'Quy 3:'||XEP_LOAI_Q3||DECODE(XEP_LOAI_Q4,NULL,NULL,'; Quy 4:'||XEP_LOAI_Q4)---,
             --- '6 thang d?u nam:'||XEP_LOAI_DAU, '6 thang cu?i nam:'||XEP_LOAI_CUOI----,'; C? nam:'||XEP_LOAI_CA
            INTO CHUOI_QUY_DAU, CHUOI_QUY_CUOI----, CHUOI_DAU_NAM,CHUOI_CUOI_NAM----, CHUOI_CA_NAM
               FROM V_PN_XEP_LOAI_CAI_TAO WHERE PN_ID=VPN_ID AND NAM_XL=J.NAM_XL;

    END IF;

     IF VNAM_XL<>J.NAM_XL OR VNAM_XL IS NULL THEN
      SO_KY_THUC:=SO_KY_THUC||CHR(10)||J.NAM_XL||': '||J.KY||': '||J.XL;
      SO_KY_THUC_DAI:=SO_KY_THUC_DAI||CHR(10)||'+ NA?m '||J.NAM_XL||': '||J.KY_XEP_LOAI||': '||J.XEP_LOAI;

       IF J.KY_XL='KD' AND J.NAM_XL<>TO_CHAR(VNGAY_XET,'YYYY') THEN
          IF VCHUOI IN (1,3) THEN
            CHUOI_QUY:=CHUOI_QUY||CHR(10)||'+ Nam '||J.NAM_XL||': '||CHUOI_QUY_DAU;
          ELSIF VCHUOI=2 THEN
            CHUOI_QUY:=CHUOI_QUY||CHR(10)||'+ Nam '||J.NAM_XL||': '||CHUOI_DAU_NAM;
          ELSE
            CHUOI_QUY:=CHUOI_QUY||CHR(10)||'+ Nam '||J.NAM_XL||': '||CHUOI_QUY_DAU||'; '||CHUOI_DAU_NAM;
          END IF;
       ELSIF (J.KY_XL='KD' OR J.KY_XL LIKE 'Q_') AND J.NAM_XL=TO_CHAR(VNGAY_XET,'YYYY') THEN
          IF VCHUOI=0 THEN
             CHUOI_QUY:=CHUOI_QUY||CHR(10)||'+ Nam '||J.NAM_XL||': '||CHUOI_QUY_DAU||'; '||CHUOI_DAU_NAM||'; '||CHUOI_QUY_CUOI;
          ELSIF VCHUOI IN (1,3) THEN
             CHUOI_QUY:=CHUOI_QUY||CHR(10)||'+ Nam '||J.NAM_XL||': '||CHUOI_QUY_DAU||'; '||CHUOI_QUY_CUOI;
          ELSIF VCHUOI=2 THEN
             CHUOI_QUY:=CHUOI_QUY||CHR(10)||'+ Nam '||J.NAM_XL||': '||CHUOI_DAU_NAM||'; '||CHUOI_QUY_CUOI;
          END IF;
       ELSIF J.KY_XL='KC' THEN
          IF VCHUOI IN (0,1) THEN
             CHUOI_QUY:=CHUOI_QUY||CHR(10)||'+ Nam '||J.NAM_XL||': '||CHUOI_QUY_CUOI||'; '||CHUOI_CUOI_NAM;
          ELSIF VCHUOI=3 THEN
             CHUOI_QUY:=CHUOI_QUY||CHR(10)||'+ Nam '||J.NAM_XL||': '||CHUOI_QUY_CUOI;
          ELSIF VCHUOI=2 THEN
             CHUOI_QUY:=CHUOI_QUY||CHR(10)||'+ Nam '||J.NAM_XL||': '||CHUOI_CUOI_NAM;
          END IF;
       END IF;

     ELSE

       IF J.KY_XL='KC' THEN
          IF VCHUOI=1 THEN
             CHUOI_QUY:=CHUOI_QUY||'; '||CHUOI_QUY_CUOI||CHUOI_CA_NAM;
          ELSIF VCHUOI=3 THEN
             CHUOI_QUY:=CHUOI_QUY||'; '||CHUOI_QUY_CUOI;
          ELSIF VCHUOI=0 THEN
              CHUOI_QUY:=CHUOI_QUY||'; '||CHUOI_QUY_CUOI||'; '||CHUOI_CUOI_NAM||CHUOI_CA_NAM;
          ELSIF VCHUOI=2 THEN
              CHUOI_QUY:=CHUOI_QUY||'; '||CHUOI_CUOI_NAM||CHUOI_CA_NAM;
          END IF;
       END IF;

      SELECT XL, XEP_LOAI INTO KYCN,KYCANAM FROM V_PN_KQCT_DOC T WHERE PN_ID=VPN_ID AND KY_XL='CA' AND NAM_XL=J.NAM_XL;

      SO_KY_THUC:=SO_KY_THUC||';'||J.KY||':'||J.XL||'; CN: '||KYCN;
      SO_KY_THUC_DAI:=SO_KY_THUC_DAI||'; '||J.KY_XEP_LOAI||': '||J.XEP_LOAI||'; Ca?# nA?m: '||KYCANAM;
     END IF;
     VNAM_XL:=J.NAM_XL;
     STRXL:=STRXL||J.MA_XEP_LOAI;

    END LOOP;

   VKQCT:=STRXL;

   RETURN SUBSTR(CHUOI_QUY,2);
EXCEPTION
     WHEN OTHERS THEN RETURN NULL;
END;

FUNCTION GET_CHUOI_XLCT_DX_QUY(VPN_ID VARCHAR2, VNGAY_XET DATE)  RETURN VARCHAR2 IS
 MA_MUC_AN VARCHAR2(10);
 MUC_AN_THANG NUMBER;
 MA_GCR VARCHAR2(100);
 SO_TA NUMBER:=0;
 SO_KY NUMBER:=0;
 SO_KY_UT NUMBER:=0;
 --SO_KY_TA NUMBER:=0;
 LOAI_KY VARCHAR2(3);
 --CHIA_KY NUMBER:=0;
 --SO_KY_THUC VARCHAR2(2000);
 --SO_KY_THUC_DAI VARCHAR2(2000);
 --SO_KY2 NUMBER:=0;
 --SO_KY_UT2 NUMBER:=0;
 --SO_KY_TA2 NUMBER:=0;
 --LOAI_KY2 VARCHAR2(3);
 --CHIA_KY2 NUMBER:=0;
 --SO_KY_THUC2 VARCHAR2(2000);
 --SO_KY_THUC_DAI2 VARCHAR2(2000);

 --VNAM_XL NUMBER;
 --VNGAYQDGTH DATE;
 --CGTH NUMBER;
 CMAGCR NUMBER;
 --VNGAY_30_04 DATE:=TO_DATE('30-APR-'||TO_CHAR(VNGAY_XET,'YYYY'),'DD-MON-YYYY');
 --VNGAY_25_08 DATE:=TO_DATE('25-AUG-'||TO_CHAR(VNGAY_XET,'YYYY'),'DD-MON-YYYY');
 --VNGAY_02_09 DATE:=TO_DATE('02-SEP-'||TO_CHAR(VNGAY_XET,'YYYY'),'DD-MON-YYYY');
 --VQUY_CUOI VARCHAR2(200);
 --VQUY_CUOI_DAI VARCHAR2(200);
 STRXL VARCHAR2(100);
 --KYCN  VARCHAR2(100);
 --KYCANAM VARCHAR2(200);
BEGIN
 SELECT T.MA_MUC_AN_PHAT, NVL(T.SO_TIEN_AN,0), GET_THANG(T.MA_MUC_AN_PHAT), T.MA_GHI_CHU_RIENG
   INTO MA_MUC_AN,SO_TA,MUC_AN_THANG, MA_GCR
     FROM PN_LAI_LICH T
       WHERE PN_ID=VPN_ID;
 SELECT COUNT(*) INTO CMAGCR FROM MA_GHI_CHU_RIENG M WHERE MA<='2500' AND INSTR(MA_GCR,MA)>0;

 IF MA_MUC_AN IN ('912000','911000') THEN
    SO_KY:=4*2+1; LOAI_KY:='K_'; SO_KY_UT:=1;
 ELSIF MUC_AN_THANG BETWEEN 15*12+0.01 AND 30*12 THEN
    SO_KY:=3*2+1; LOAI_KY:='K_'; SO_KY_UT:=1;
 ELSIF MUC_AN_THANG BETWEEN 10*12+0.01 AND 15*12 THEN
    SO_KY:=2*2+1; LOAI_KY:='K_'; SO_KY_UT:=1;
 ELSIF MUC_AN_THANG BETWEEN 7*12+0.01 AND 10*12 THEN
    SO_KY:=2*2; LOAI_KY:='K_'; SO_KY_UT:=1;
 ELSIF MUC_AN_THANG BETWEEN 5*12+0.01 AND 7*12 THEN
    SO_KY:=3; LOAI_KY:='K_'; SO_KY_UT:=1;
 ELSIF MUC_AN_THANG BETWEEN 3*12+0.01 AND 5*12 THEN
    SO_KY:=2; LOAI_KY:='K_'; SO_KY_UT:=1;
 ELSIF MUC_AN_THANG<=3*12  THEN
  IF CMAGCR=0 THEN
    SO_KY:=1; LOAI_KY:='K_'; SO_KY_UT:=1;
  ELSE
    SO_KY:=1; LOAI_KY:='Q_';
  END IF;
 END IF;


 IF CMAGCR>0 THEN
    SO_KY:=SO_KY-SO_KY_UT;
 END IF;

 IF SO_KY=0 THEN SO_KY:=1; END IF;

 IF LOAI_KY='K_' THEN
    SO_KY:=SO_KY*2+1;
    LOAI_KY:='Q_';
 END IF;

    FOR J IN (SELECT * FROM
                   (SELECT * FROM
                       (SELECT T.NAM_XL,T.XL,T.KY,T.KY_XEP_LOAI,T.XEP_LOAI,
                               T.MA_XEP_LOAI,T.NGAY_XL FROM V_PN_KQCT_DOC T
                            WHERE PN_ID=VPN_ID
                             AND T.KY_XL LIKE LOAI_KY
                              AND T.NGAY_XL<VNGAY_XET
                               AND NAM_XL>=TO_NUMBER(TO_CHAR(VNGAY_XET,'YYYY'))-ROUND(SO_KY/2)
                                ORDER BY NGAY_XL DESC)
       WHERE ROWNUM<=SO_KY)
       ORDER BY NGAY_XL
       )
    LOOP
     STRXL:=STRXL||J.MA_XEP_LOAI;
    END LOOP;


   RETURN STRXL;
EXCEPTION
     WHEN OTHERS THEN RETURN NULL;
END;
END;





