PROCEDURE GET_THOI_HAN(P_MA VARCHAR2, SOTHANG OUT NUMBER, SONGAY OUT NUMBER ) IS
   BEGIN
          SELECT NAM*12+THANG,NGAY INTO SOTHANG,SONGAY FROM MA_MUC_THOI_GIAN WHERE MA=P_MA;
   END;
---------------------------------
FUNCTION MA_TG_CHAP_HANH(P_PN_ID VARCHAR2, P_NGAY_XET DATE DEFAULT SYSDATE,P_FORMAT VARCHAR2 DEFAULT NULL) RETURN VARCHAR2 IS
   MA_MUC_TG_TAM_GIAM VARCHAR2(7);
   MA_MUC_TG_TAM_GIU VARCHAR2(7);
   SO_THANG_TAM_GIAM NUMBER(10):=0;
   SO_NGAY_TAM_GIAM NUMBER(10):=0;
   SO_THANG_TAM_GIU NUMBER(10):=0;
   SO_NGAY_TAM_GIU NUMBER(10):=0;
   MA_MUC_TG_TDC VARCHAR2(7);
   SO_THANG_TDC NUMBER(10):=0;
   SO_NGAY_TDC NUMBER(10):=0;
   MA_MUC_TG_TRON VARCHAR2(7);
   SO_THANG_TRON NUMBER(10):=0;
   SO_NGAY_TRON NUMBER(10):=0;
   MA_MUC_TG_HOAN VARCHAR2(7);
   SO_THANG_HOAN NUMBER(10):=0;
   SO_NGAY_HOAN NUMBER(10):=0;
   VNGAY_BAT DATE;
   VNGAY_RA DATE;
   VNGAY_XET DATE;
   SO_THANG_THUC_O NUMBER(10):=0;
   SO_NGAY_THUC_O NUMBER(10):=0;
   TONG_SO_THANG NUMBER(10):=0;
   TONG_SO_NGAY NUMBER(10):=0;
   P_KETQUA VARCHAR2(7);
BEGIN
     SELECT   LL.NGAY_BAT,
             LL.NGAY_RA_TRAI,
       NVL(LL.MA_MUC_TAM_GIAM,'000000'),
       NVL(LL.MA_MUC_TAM_GIU,'000000')
     INTO    VNGAY_BAT,
             VNGAY_RA,
       MA_MUC_TG_TAM_GIAM,
       MA_MUC_TG_TAM_GIU
     FROM     PN_LAI_LICH LL
     WHERE    LL.PN_ID=P_PN_ID;

     IF VNGAY_RA<P_NGAY_XET THEN
        VNGAY_XET:=VNGAY_RA;
     ELSE
        VNGAY_XET:=P_NGAY_XET;
     END IF;

     GET_THOI_HAN(MA_MUC_TG_TAM_GIAM,SO_THANG_TAM_GIAM,SO_NGAY_TAM_GIAM);
     GET_THOI_HAN(MA_MUC_TG_TAM_GIU,SO_THANG_TAM_GIU,SO_NGAY_TAM_GIU);
     SO_THANG_TAM_GIAM:=SO_THANG_TAM_GIAM+SO_THANG_TAM_GIU;
     SO_NGAY_TAM_GIAM:=SO_NGAY_TAM_GIAM+SO_NGAY_TAM_GIU;

       MA_MUC_TG_TDC:=MA_TG_TAM_DINH_CHI(P_PN_ID,VNGAY_XET);
       GET_THOI_HAN(MA_MUC_TG_TDC,SO_THANG_TDC,SO_NGAY_TDC);

       MA_MUC_TG_TRON:=MA_TG_TRON_TRAI(P_PN_ID,VNGAY_XET);
       GET_THOI_HAN(MA_MUC_TG_TRON,SO_THANG_TRON,SO_NGAY_TRON);

       MA_MUC_TG_HOAN:=MA_TG_HOAN_THI_HANH_AN(P_PN_ID,VNGAY_XET);
       GET_THOI_HAN(MA_MUC_TG_HOAN,SO_THANG_HOAN,SO_NGAY_HOAN);

       SO_THANG_THUC_O:=PN_DATE.DATE_MINUS(VNGAY_XET,VNGAY_BAT,'MF');
       SO_NGAY_THUC_O:=PN_DATE.DATE_MINUS(VNGAY_XET,VNGAY_BAT,'D');

       TONG_SO_THANG:=NVL(SO_THANG_THUC_O,0)+NVL(SO_THANG_TAM_GIAM,0)-(NVL(SO_THANG_TDC,0)+NVL(SO_THANG_TRON,0)+NVL(SO_THANG_HOAN,0))  ;
       TONG_SO_NGAY:=NVL(SO_NGAY_THUC_O,0)+NVL(SO_NGAY_TAM_GIAM,0)-(NVL(SO_NGAY_TDC,0)+NVL(SO_NGAY_TRON,0)+NVL(SO_NGAY_HOAN,0));

       IF P_FORMAT='MD' THEN
         P_KETQUA:=TO_CHAR(NVL(TONG_SO_THANG,0)*30+NVL(TONG_SO_NGAY,0));
       ELSE
         P_KETQUA:=PN_SYS.GET_MA_STRING_FROM_NUMBERS(TONG_SO_THANG,TONG_SO_NGAY);
       END IF;
     RETURN P_KETQUA;
END;
---------------------------------
   FUNCTION MA_TG_CON_LAI(P_PN_ID VARCHAR2,P_NGAY_XET DATE DEFAULT SYSDATE,P_FORMAT VARCHAR2 DEFAULT NULL) RETURN VARCHAR2 IS
   MA_MUC_AN VARCHAR2(10);
   SO_THANG_AN_PHAT NUMBER(10):=0;
   SO_NGAY_AN_PHAT NUMBER(10):=0;

   MA_MUC_TG_DA_O VARCHAR2(7);
   SO_THANG_DA_O NUMBER(10):=0;
   SO_NGAY_DA_O NUMBER(10):=0;

   MA_MUC_TG_GTH VARCHAR2(7);
   SO_THANG_GTH NUMBER(10):=0;
   SO_NGAY_GTH NUMBER(10):=0;
   SO_LAN_GIAM NUMBER(4):=0;

   MA_MUC_TG_MIEN VARCHAR2(7);
   SO_THANG_MIEN NUMBER(10):=0;
   SO_NGAY_MIEN NUMBER(4):=0;

   TONG_SO_THANG NUMBER(10):=0;
   TONG_SO_NGAY NUMBER(10):=0;
   NUM_REC NUMBER(4);

   P_KETQUA VARCHAR2(7);
   BEGIN
    SELECT MA_MUC_AN_PHAT INTO MA_MUC_AN FROM PN_LAI_LICH WHERE PN_ID=P_PN_ID;

     MA_MUC_TG_DA_O:=MA_TG_CHAP_HANH(P_PN_ID,P_NGAY_XET);
     GET_THOI_HAN(MA_MUC_TG_DA_O,SO_THANG_DA_O,SO_NGAY_DA_O);

     IF MA_MUC_AN IN ('911000','912000') THEN
       SELECT COUNT(*) INTO SO_LAN_GIAM FROM PN_GIAM_THOI_HAN WHERE PN_ID=P_PN_ID AND NGAY_QD_GIAM<=P_NGAY_XET AND TO_NUMBER(MA_MUC_QD_GIAM_TOA_AN)=921000;
       IF SO_LAN_GIAM>0 THEN
         SO_THANG_AN_PHAT:=30*12;
         SO_NGAY_AN_PHAT:=0;
       ELSE
         SELECT COUNT(*) INTO SO_LAN_GIAM FROM PN_GIAM_THOI_HAN WHERE PN_ID=P_PN_ID AND NGAY_QD_GIAM<=P_NGAY_XET AND TO_NUMBER(MA_MUC_QD_GIAM_TOA_AN)=922000;
         IF SO_LAN_GIAM>0 THEN
           SO_THANG_AN_PHAT:=20*12;
           SO_NGAY_AN_PHAT:=0;
         ELSE
           RETURN '911000';
         END IF;
       END IF;
     ELSE
       GET_THOI_HAN(MA_MUC_AN,SO_THANG_AN_PHAT,SO_NGAY_AN_PHAT);
     END IF;

     MA_MUC_TG_GTH:=MA_TG_GIAM_AN(P_PN_ID,P_NGAY_XET);
     GET_THOI_HAN(MA_MUC_TG_GTH,SO_THANG_GTH,SO_NGAY_GTH);

     SELECT COUNT(*) INTO NUM_REC FROM PN_MIEN_HINH_PHAT WHERE PN_ID=P_PN_ID AND QD_MIEN_NGAY IS NOT NULL;
     IF NUM_REC>0 THEN
      SELECT MA_MUC_THOI_HAN_MIEN INTO MA_MUC_TG_MIEN FROM PN_MIEN_HINH_PHAT WHERE PN_ID=P_PN_ID;
       IF MA_MUC_TG_MIEN IS NOT NULL THEN
         IF MA_MUC_TG_MIEN<>MA_MUC_AN THEN
           GET_THOI_HAN(MA_MUC_TG_MIEN,SO_THANG_MIEN,SO_NGAY_MIEN);
         END IF;
       END IF;
     END IF;

     TONG_SO_THANG:=NVL(SO_THANG_AN_PHAT,0)-(NVL(SO_THANG_DA_O,0)+NVL(SO_THANG_GTH,0)+NVL(SO_THANG_MIEN,0));
     TONG_SO_NGAY:=NVL(SO_NGAY_AN_PHAT,0)-(NVL(SO_NGAY_DA_O,0)+NVL(SO_NGAY_GTH,0)+NVL(SO_NGAY_MIEN,0));

     IF P_FORMAT='MD' THEN
       P_KETQUA:=TO_CHAR(NVL(TONG_SO_THANG,0)*30+NVL(TONG_SO_NGAY,0));
     ELSE
       P_KETQUA:=PN_SYS.GET_MA_STRING_FROM_NUMBERS(TONG_SO_THANG,TONG_SO_NGAY);
     END IF;
     RETURN P_KETQUA;
   END;
---------------------------------
   FUNCTION MA_TG_GIAM_AN(P_PN_ID VARCHAR2,P_NGAY_XET DATE DEFAULT SYSDATE,P_LOAI_KQ NUMBER DEFAULT 1) RETURN VARCHAR2 IS

   CURSOR PN_GTH_CUR IS
          SELECT MA_MUC_QD_GIAM_TOA_AN MA_MUC_GIAM
          FROM PN_GIAM_THOI_HAN
          WHERE PN_ID=P_PN_ID
          AND NGAY_XET<P_NGAY_XET
          --AND NGAY_XET>=(SELECT L.NGAY_BAT FROM PN_LAI_LICH L WHERE PN_ID=P_PN_ID)
          AND TO_NUMBER(MA_MUC_QD_GIAM_TOA_AN)<=923000
          AND NVL(MA_MUC_QD_GIAM_TOA_AN,'000000') > '000001'
          AND NGAY_QD_GIAM IS NOT NULL
          AND NGAY_QD_GIAM<P_NGAY_XET
          ORDER BY NGAY_QD_GIAM ;

   PN_GTH_REC PN_GTH_CUR%ROWTYPE;
   MMG_TU_CHUNG_THAN VARCHAR2(7);
   MMG_HET_AN VARCHAR2(7);
   MMG_CO_THOI_HAN VARCHAR2(7);
   GIAM_AN VARCHAR2(50);
   --SO_NAM   NUMBER(10):=0;
   SO_THANG NUMBER(10):=0;
   SO_NGAY   NUMBER(10):=0;
   NUM_REC NUMBER(4):=0;
   P_KETQUA_GTH VARCHAR2(200);
   BEGIN
     FOR PN_GTH_REC IN PN_GTH_CUR
     LOOP
       NUM_REC:=NUM_REC+1;
       IF PN_GTH_REC.MA_MUC_GIAM IN ('921000','922000') THEN
         MMG_TU_CHUNG_THAN:=PN_GTH_REC.MA_MUC_GIAM;
       ELSIF TO_NUMBER(PN_GTH_REC.MA_MUC_GIAM)='923000' THEN
         MMG_HET_AN:=PN_GTH_REC.MA_MUC_GIAM;
       ELSE
         SO_THANG:=SO_THANG+PN_SYS.GET_NUMBER_FROM_MA_STRING(PN_GTH_REC.MA_MUC_GIAM);
         SO_NGAY:=SO_NGAY+PN_SYS.GET_NUMBER_FROM_MA_STRING(PN_GTH_REC.MA_MUC_GIAM,'d');
       END IF;
     END LOOP;
     MMG_CO_THOI_HAN:=PN_SYS.GET_MA_STRING_FROM_NUMBERS(SO_THANG,SO_NGAY);

     IF MMG_TU_CHUNG_THAN IS NOT NULL THEN GIAM_AN:=MMG_TU_CHUNG_THAN;END IF;
     IF MMG_CO_THOI_HAN IS NOT NULL THEN
       IF GIAM_AN IS NOT NULL THEN
         GIAM_AN:=GIAM_AN||';'||MMG_CO_THOI_HAN;
       ELSE
         GIAM_AN:=MMG_CO_THOI_HAN;
       END IF;
     END IF;
     IF MMG_HET_AN IS NOT NULL THEN
       IF GIAM_AN IS NOT NULL THEN
         GIAM_AN:=GIAM_AN||';'||MMG_HET_AN;
       ELSE
         GIAM_AN:=MMG_HET_AN;
       END IF;
     END IF;
     IF GIAM_AN IS NULL THEN  GIAM_AN:='000000';END IF;

     IF P_LOAI_KQ=1 THEN
       P_KETQUA_GTH:=MMG_CO_THOI_HAN;
     ELSIF P_LOAI_KQ=2 THEN
       P_KETQUA_GTH:=GIAM_AN;
     ELSIF P_LOAI_KQ=3 THEN
       IF NUM_REC>0 THEN
         P_KETQUA_GTH:=TO_CHAR(NUM_REC)||'@'||GIAM_AN;
       ELSE
         P_KETQUA_GTH:=GIAM_AN;
       END IF;
     ELSE
       IF NUM_REC>0 THEN
         GIAM_AN:=REPLACE(GIAM_AN,'000000;','');
         P_KETQUA_GTH:=TO_CHAR(NUM_REC)||' L?n = '||U_COUNT_MAS('ma_muc_thoi_gian',GIAM_AN);
       ELSE
         P_KETQUA_GTH:=U_COUNT_MAS('ma_muc_thoi_gian',GIAM_AN);
       END IF;
     END IF;
     RETURN P_KETQUA_GTH;
   END;
---------------------------------
   FUNCTION MA_TG_TAM_DINH_CHI(P_PN_ID VARCHAR2,P_NGAY_XET DATE DEFAULT SYSDATE) RETURN VARCHAR2 IS
   --SO_NAM NUMBER(10):=0;
   SO_THANG NUMBER(10):=0;
   SO_NGAY NUMBER(10):=0;
   P_KETQUA_TDC VARCHAR2(7);
   NGAYBAT DATE;
   BEGIN
     SELECT NGAY_BAT INTO NGAYBAT FROM PN_LAI_LICH WHERE PN_ID=P_PN_ID;

     SELECT  SUM(PN_DATE.DATE_MINUS(NGAY_LAI,NGAY_TDC,'MF')),
             SUM(PN_DATE.DATE_MINUS(NGAY_LAI,NGAY_TDC,'D'))
     INTO     SO_THANG,
             SO_NGAY
     FROM     PN_TDC_TAM_DINH_CHI
     WHERE   PN_ID=P_PN_ID  AND  NGAY_TDC<=P_NGAY_XET
     AND NVL(NGAY_LAI,P_NGAY_XET+1)<=P_NGAY_XET
     AND NGAY_TDC>NGAYBAT AND MA_LENH_TDC='1';
     P_KETQUA_TDC:=PN_SYS.GET_MA_STRING_FROM_NUMBERS(SO_THANG,SO_NGAY);

     IF P_KETQUA_TDC IS NOT NULL THEN RETURN P_KETQUA_TDC;END IF;
     RETURN '000000';
     EXCEPTION
       WHEN NO_DATA_FOUND THEN RETURN '000000';
       WHEN OTHERS THEN RETURN '000000';
   END;
---------------------------------
   FUNCTION MA_TG_THA_CO_DK(P_PN_ID VARCHAR2,P_NGAY_XET DATE DEFAULT SYSDATE) RETURN VARCHAR2 IS
   SO_THANG NUMBER(10):=0;
   SO_NGAY NUMBER(10):=0;
   P_KETQUA_TCDK VARCHAR2(7);
   NGAYBAT DATE;
   BEGIN
     SELECT NGAY_BAT INTO NGAYBAT FROM PN_LAI_LICH WHERE PN_ID=P_PN_ID;

     SELECT  SUM(PN_DATE.DATE_MINUS(NGAY_TRO_LAI_TRAI,NGAY_THA_TT,'MF')),
             SUM(PN_DATE.DATE_MINUS(NGAY_TRO_LAI_TRAI,NGAY_THA_TT,'D'))
     INTO    SO_THANG,
             SO_NGAY
     FROM    PN_THA_CO_DK
     WHERE   PN_ID=P_PN_ID  AND  NGAY_THA_TT<=P_NGAY_XET
     AND NVL(NGAY_TRO_LAI_TRAI,P_NGAY_XET+1)<=P_NGAY_XET;

     P_KETQUA_TCDK:=PN_SYS.GET_MA_STRING_FROM_NUMBERS(SO_THANG,SO_NGAY);

     IF P_KETQUA_TCDK IS NOT NULL THEN RETURN P_KETQUA_TCDK;END IF;
     RETURN '000000';
     EXCEPTION
       WHEN NO_DATA_FOUND THEN RETURN '000000';
       WHEN OTHERS THEN RETURN '000000';
   END;
---------------------------------
---------------------------------
   FUNCTION MA_TG_HOAN_THI_HANH_AN(P_PN_ID VARCHAR2,P_NGAY_XET DATE DEFAULT SYSDATE) RETURN VARCHAR2 IS

   --SO_NAM NUMBER(10):=0;
   SO_THANG NUMBER(10):=0;
   SO_NGAY NUMBER(10):=0;
   P_KETQUA_HOAN VARCHAR2(7);
   BEGIN
     SELECT   SUM(PN_DATE.DATE_MINUS(NGAY_HOAN,NGAY_THI_HANH_AN,'MF')),
             SUM(PN_DATE.DATE_MINUS(NGAY_HOAN,NGAY_THI_HANH_AN,'D'))
     INTO     SO_THANG,
             SO_NGAY
     FROM     PN_HOAN_THI_HANH_AN
     WHERE   PN_ID=P_PN_ID  AND  NVL(NGAY_THI_HANH_AN,P_NGAY_XET+1)<=P_NGAY_XET;
     P_KETQUA_HOAN:=PN_SYS.GET_MA_STRING_FROM_NUMBERS(SO_THANG,SO_NGAY);

     IF P_KETQUA_HOAN IS NOT NULL THEN RETURN P_KETQUA_HOAN;END IF;
     RETURN '000000';
     EXCEPTION
       WHEN NO_DATA_FOUND THEN RETURN '000000';
       WHEN OTHERS THEN RETURN '000000';

   END;
---------------------------------
   FUNCTION MA_TG_TRON_TRAI(P_PN_ID VARCHAR2, P_NGAY_XET DATE DEFAULT SYSDATE) RETURN VARCHAR2 IS

   --SO_NAM NUMBER(10):=0;
   SO_THANG NUMBER(10):=0;
   SO_NGAY NUMBER(10):=0;
   P_KETQUA_TRON VARCHAR2(7);
   BEGIN
     SELECT   SUM(PN_DATE.DATE_MINUS(NGAY_BAT_LAI,NGAY_TRON,'MF')),
             SUM(PN_DATE.DATE_MINUS(NGAY_BAT_LAI,NGAY_TRON,'D'))
     INTO     SO_THANG,
             SO_NGAY
     FROM     PN_TT_TRON_TRAI T, PN_LAI_LICH P
     WHERE   T.PN_ID=P_PN_ID
       AND   T.NGAY_TRON>P.NGAY_BAT
       AND   T.PN_ID=P.PN_ID
       AND   NGAY_TRON<P_NGAY_XET AND NVL(NGAY_BAT_LAI,P_NGAY_XET+1)<=P_NGAY_XET;

     P_KETQUA_TRON:=PN_SYS.GET_MA_STRING_FROM_NUMBERS(SO_THANG,SO_NGAY);

     IF P_KETQUA_TRON IS NOT NULL THEN RETURN P_KETQUA_TRON;END IF;
     RETURN '000000';
     EXCEPTION
       WHEN NO_DATA_FOUND THEN RETURN '000000';
       WHEN OTHERS THEN RETURN '000000';
   END;
---------------------------------
FUNCTION NGAY_HET_HAN(P_PN_ID VARCHAR2,P_NGAY_XET DATE DEFAULT SYSDATE) RETURN DATE IS
  NGAY_BAT DATE;
  MA_MUC_TG_AN_PHAT VARCHAR2(7);
  SO_THANG_AN_PHAT NUMBER(10);
  SO_NGAY_AN_PHAT NUMBER(10);

  MA_MUC_TG_TAM_GIAM VARCHAR2(7);
  MA_MUC_TG_TAM_GIU VARCHAR2(7);
  MA_MUC_TG_O_TRUOC VARCHAR2(7);
  SO_THANG_TAM_GIAM NUMBER(4):=0;
  SO_NGAY_TAM_GIAM NUMBER(4):=0;

  MA_MUC_TG_GIAM_AN VARCHAR2(7);
  SO_THANG_GIAM NUMBER(10);
  SO_NGAY_GIAM NUMBER(10);

  MA_MUC_TG_MIEN VARCHAR2(7);
  SO_THANG_MIEN NUMBER(10);
  SO_NGAY_MIEN NUMBER(10);

  MA_MUC_TG_TDC VARCHAR2(7);
  SO_THANG_TDC NUMBER(10);
  SO_NGAY_TDC NUMBER(10);

  MA_MUC_TG_TCDK VARCHAR2(7);
  SO_THANG_TCDK NUMBER(10);
  SO_NGAY_TCDK NUMBER(10);

  MA_MUC_TG_TRON VARCHAR2(7);
  SO_THANG_TRON NUMBER(10);
  SO_NGAY_TRON NUMBER(10);

  MA_MUC_TG_HOAN VARCHAR2(7);
  SO_THANG_HOAN NUMBER(10);
  SO_NGAY_HOAN NUMBER(10);

  TONG_SO_THANG NUMBER(10);
  TONG_SO_NGAY NUMBER(10);

  P_NGAY_HET_HAN DATE;

  NUM_REC NUMBER(4);
BEGIN
--- RETURN NULL
--- Chet
SELECT COUNT(*) INTO NUM_REC FROM PN_PNC_CHET  WHERE PN_ID=P_PN_ID AND trunc(NGAY_CHET)<=P_NGAY_XET
AND TO_NUMBER(NVL(MA_TH_CHET,'90')) NOT IN (30,40,50);
IF NUM_REC>0 THEN RETURN NULL;END IF;
--- Tron trai
SELECT COUNT(*) INTO NUM_REC FROM PN_TT_TRON_TRAI
WHERE PN_ID=P_PN_ID AND trunc(NGAY_TRON)<=P_NGAY_XET AND (NGAY_BAT_LAI IS NULL OR NGAY_BAT_LAI>P_NGAY_XET);
IF NUM_REC>0 THEN RETURN NULL;END IF;
--- Huy an
SELECT COUNT(*) INTO NUM_REC FROM PN_HUY_AN WHERE PN_ID=P_PN_ID AND NGAY_TRA_TUDO<=P_NGAY_XET AND (NGAY_LAI IS NULL OR NGAY_LAI>P_NGAY_XET);
IF NUM_REC>0 THEN RETURN NULL;END IF;
--- Chuyen giao
SELECT COUNT(*) INTO NUM_REC FROM PN_CHUYEN_GIAO WHERE PN_ID=P_PN_ID AND NGAY_CHUYEN_GIAO<=P_NGAY_XET;
IF NUM_REC>0 THEN RETURN NULL;END IF;
--- Trich xuat chuyen trai
SELECT COUNT(*) INTO NUM_REC FROM PN_TX_TRICH_XUAT WHERE PN_ID=P_PN_ID
AND MA_LENH_TX=1 AND MA_TINH_TRANG_TX=30;
IF NUM_REC>0 THEN RETURN NULL;END IF;
--- Chuyen trai
SELECT COUNT(*) INTO NUM_REC FROM PN_CHUYEN_TRAI
WHERE PN_ID=P_PN_ID AND NGAY_CHUYEN<=P_NGAY_XET AND NVL(NGAY_TRO_LAI,P_NGAY_XET+1)>SYSDATE;
IF NUM_REC>0 THEN RETURN NULL;END IF;
--- Tam dinh chi
SELECT COUNT(*) INTO NUM_REC FROM PN_TDC_TAM_DINH_CHI WHERE PN_ID=P_PN_ID AND NGAY_TDC<=P_NGAY_XET
AND MA_LENH_TDC='1' AND NVL(NGAY_LAI,P_NGAY_XET+1)>P_NGAY_XET;
IF NUM_REC>0 THEN RETURN NULL;END IF;
--- Hoan thi hanh an
SELECT COUNT(*) INTO NUM_REC FROM PN_HOAN_THI_HANH_AN
WHERE PN_ID=P_PN_ID AND NGAY_HOAN<=P_NGAY_XET AND NVL(NGAY_THI_HANH_AN,P_NGAY_XET+1)>P_NGAY_XET;
IF NUM_REC>0 THEN RETURN NULL;END IF;

--- RETURN P_NGAY_HET_HAN
--- Dac xa
SELECT COUNT(*) INTO NUM_REC FROM PN_DX_DAC_XA WHERE PN_ID=P_PN_ID AND MA_DUOC_DAC_XA<'20' AND NGAY_THA_DX IS NOT NULL;
IF NUM_REC>0 THEN
  SELECT MAX(NGAY_THA_DX) INTO P_NGAY_HET_HAN FROM PN_DX_DAC_XA WHERE PN_ID=P_PN_ID;
  RETURN P_NGAY_HET_HAN;
END IF;
--- Tha co DK
SELECT COUNT(*) INTO NUM_REC FROM PN_THA_CO_DK WHERE PN_ID=P_PN_ID
AND MA_DUOC_TT<'20' AND NGAY_THA_TT IS NOT NULL AND NGAY_TRO_LAI_TRAI IS NULL;
IF NUM_REC>0 THEN
  SELECT MAX(NGAY_THA_TT) INTO P_NGAY_HET_HAN FROM PN_THA_CO_DK WHERE PN_ID=P_PN_ID;
  RETURN P_NGAY_HET_HAN;
END IF;
---
SELECT  NGAY_BAT,
        MA_MUC_AN_PHAT,
        NVL(MA_MUC_TAM_GIAM,'000000'),
        NVL(MA_MUC_TAM_GIU,'000000'),
        NVL(MA_MUC_TG_O_TRUOC,'000000')
INTO    NGAY_BAT,
        MA_MUC_TG_AN_PHAT,
        MA_MUC_TG_TAM_GIAM,
        MA_MUC_TG_TAM_GIU,
        MA_MUC_TG_O_TRUOC
FROM    PN_LAI_LICH
WHERE   PN_ID=P_PN_ID;
---
--- Mien
SELECT COUNT(*) INTO NUM_REC FROM PN_MIEN_HINH_PHAT WHERE PN_ID=P_PN_ID AND QD_MIEN_NGAY IS NOT NULL;
IF NUM_REC>0 THEN
  SELECT MA_MUC_THOI_HAN_MIEN,NGAY_TRA_TU_DO INTO MA_MUC_TG_MIEN,P_NGAY_HET_HAN
  FROM PN_MIEN_HINH_PHAT WHERE PN_ID=P_PN_ID;
  IF P_NGAY_HET_HAN IS NOT NULL THEN
    IF NVL(P_NGAY_HET_HAN,P_NGAY_XET+1)<P_NGAY_XET THEN RETURN P_NGAY_HET_HAN;END IF;
    ELSE
      IF MA_MUC_TG_MIEN<>MA_MUC_TG_AN_PHAT THEN
        SO_THANG_MIEN:=PN_SYS.GET_NUMBER_FROM_MA_STRING(MA_MUC_TG_MIEN);
        SO_NGAY_MIEN:=PN_SYS.GET_NUMBER_FROM_MA_STRING(MA_MUC_TG_MIEN,'d');
      END IF;
  END IF;
END IF;
--- Giam an An chung than
IF MA_MUC_TG_AN_PHAT LIKE '9%' THEN
  SELECT COUNT(*) INTO NUM_REC FROM PN_GIAM_THOI_HAN
  WHERE PN_ID=P_PN_ID AND MA_MUC_QD_GIAM_TOA_AN='921000' AND SO_QD_GIAM IS NOT NULL;
    IF NUM_REC>0 THEN
         SO_THANG_AN_PHAT:=30*12;
         SO_NGAY_AN_PHAT:=0;
    ELSE
      SELECT COUNT(*) INTO NUM_REC FROM PN_GIAM_THOI_HAN
      WHERE PN_ID=P_PN_ID AND MA_MUC_QD_GIAM_TOA_AN='922000' AND SO_QD_GIAM IS NOT NULL;
        IF NUM_REC>0 THEN
          SO_THANG_AN_PHAT:=20*12;
          SO_NGAY_AN_PHAT:=0;
        ELSE
          RETURN NULL;
        END IF;
    END IF;
ELSE
  SO_THANG_AN_PHAT:=PN_SYS.GET_NUMBER_FROM_MA_STRING(MA_MUC_TG_AN_PHAT);
  SO_NGAY_AN_PHAT:=PN_SYS.GET_NUMBER_FROM_MA_STRING(MA_MUC_TG_AN_PHAT,'d');
END IF;
--- Giam an An co thoi han
SELECT COUNT(*) INTO NUM_REC FROM PN_GIAM_THOI_HAN
WHERE PN_ID=P_PN_ID AND MA_MUC_QD_GIAM_TOA_AN='923000';
  IF NUM_REC>0 THEN
    SELECT MAX(NGAY_THA_GIAM_HET_AN) INTO P_NGAY_HET_HAN FROM PN_GIAM_THOI_HAN
    WHERE PN_ID=P_PN_ID AND MA_MUC_QD_GIAM_TOA_AN='923000';
    RETURN P_NGAY_HET_HAN;
  END IF;

SO_THANG_TAM_GIAM:=PN_SYS.GET_NUMBER_FROM_MA_STRING(MA_MUC_TG_TAM_GIAM)+PN_SYS.GET_NUMBER_FROM_MA_STRING(MA_MUC_TG_TAM_GIU)+PN_SYS.GET_NUMBER_FROM_MA_STRING(MA_MUC_TG_O_TRUOC);
SO_NGAY_TAM_GIAM:=PN_SYS.GET_NUMBER_FROM_MA_STRING(MA_MUC_TG_TAM_GIAM,'d')+PN_SYS.GET_NUMBER_FROM_MA_STRING(MA_MUC_TG_TAM_GIU,'d')+PN_SYS.GET_NUMBER_FROM_MA_STRING(MA_MUC_TG_O_TRUOC,'d');

MA_MUC_TG_GIAM_AN:=MA_TG_GIAM_AN(P_PN_ID,P_NGAY_XET);
SO_THANG_GIAM:=PN_SYS.GET_NUMBER_FROM_MA_STRING(MA_MUC_TG_GIAM_AN);
SO_NGAY_GIAM:=PN_SYS.GET_NUMBER_FROM_MA_STRING(MA_MUC_TG_GIAM_AN,'d');

MA_MUC_TG_TDC:=MA_TG_TAM_DINH_CHI(P_PN_ID,P_NGAY_XET);
SO_THANG_TDC:=PN_SYS.GET_NUMBER_FROM_MA_STRING(MA_MUC_TG_TDC);
SO_NGAY_TDC:=PN_SYS.GET_NUMBER_FROM_MA_STRING(MA_MUC_TG_TDC,'d');

MA_MUC_TG_TCDK:=MA_TG_THA_CO_DK(P_PN_ID,P_NGAY_XET);
SO_THANG_TCDK:=PN_SYS.GET_NUMBER_FROM_MA_STRING(MA_MUC_TG_TCDK);
SO_NGAY_TCDK:=PN_SYS.GET_NUMBER_FROM_MA_STRING(MA_MUC_TG_TCDK,'d');

MA_MUC_TG_HOAN:=MA_TG_HOAN_THI_HANH_AN(P_PN_ID,P_NGAY_XET);
SO_THANG_HOAN:=PN_SYS.GET_NUMBER_FROM_MA_STRING(MA_MUC_TG_HOAN);
SO_NGAY_HOAN:=PN_SYS.GET_NUMBER_FROM_MA_STRING(MA_MUC_TG_HOAN,'d');

MA_MUC_TG_TRON:=MA_TG_TRON_TRAI(P_PN_ID,P_NGAY_XET);
SO_THANG_TRON:=PN_SYS.GET_NUMBER_FROM_MA_STRING(MA_MUC_TG_TRON);
SO_NGAY_TRON:=PN_SYS.GET_NUMBER_FROM_MA_STRING(MA_MUC_TG_TRON,'d');

TONG_SO_THANG:=NVL(SO_THANG_AN_PHAT,0)-NVL(SO_THANG_TAM_GIAM,0)-NVL(SO_THANG_GIAM,0)-NVL(SO_THANG_MIEN,0)+NVL(SO_THANG_TRON,0)+NVL(SO_THANG_TDC,0)+NVL(SO_THANG_TCDK,0)+NVL(SO_THANG_HOAN,0);
TONG_SO_NGAY:=NVL(SO_NGAY_AN_PHAT,0)-NVL(SO_NGAY_TAM_GIAM,0)-NVL(SO_NGAY_GIAM,0)-NVL(SO_NGAY_MIEN,0)+NVL(SO_NGAY_TRON,0)+NVL(SO_NGAY_TDC,0)+NVL(SO_NGAY_TCDK,0)+NVL(SO_NGAY_HOAN,0);

P_NGAY_HET_HAN:=PN_DATE.GET_DATE_PLUS(NGAY_BAT,TONG_SO_THANG,TONG_SO_NGAY);

RETURN P_NGAY_HET_HAN;
END;
