   ------------------------------------------------------------------------------------------
FUNCTION MA_TINH_TRANG(P_PN_ID VARCHAR2,P_NGAY_XET DATE DEFAULT SYSDATE) RETURN VARCHAR2 IS
   NUM_REC VARCHAR2(2);
   NUM_REC2 VARCHAR2(2);

BEGIN
   SELECT COUNT(*) INTO NUM_REC FROM PN_LAI_LICH T WHERE PN_ID=P_PN_ID AND LY_DO_KET_THUC IS NOT NULL;
   IF NUM_REC>0 THEN
      RETURN '9999'; -- Ket thuc ho so --
   END IF;

   SELECT COUNT(*) INTO NUM_REC FROM PN_LAI_LICH T WHERE PN_ID=P_PN_ID AND T.NGAY_DEN_TRAI<= P_NGAY_XET;
   IF NUM_REC>0 THEN

   SELECT COUNT(*) INTO NUM_REC FROM PN_PNC_CHET	WHERE PN_ID=P_PN_ID AND trunc(NGAY_CHET)<=P_NGAY_XET
   AND TO_NUMBER(NVL(MA_TH_CHET,'90')) NOT IN (30,40,50);
   IF NUM_REC>0 THEN
      RETURN '171'; -- Chet --
   END IF;

   SELECT COUNT(*) INTO NUM_REC FROM PN_TDC_TAM_DINH_CHI WHERE PN_ID=P_PN_ID AND MA_LENH_TDC='1'
   AND NGAY_TDC<=P_NGAY_XET AND NVL(NGAY_LAI,P_NGAY_XET+1)>P_NGAY_XET AND MA_TINH_TRANG_TDC='30';
   IF NUM_REC>0 THEN
      RETURN '153'; -- TDC chet --
   END IF;

   SELECT COUNT(*) INTO NUM_REC FROM PN_TX_TRICH_XUAT WHERE PN_ID=P_PN_ID AND MA_LENH_TX='1'
   AND NGAY_TX<=P_NGAY_XET AND NVL(NGAY_TRA_LAI,P_NGAY_XET+1)>P_NGAY_XET AND MA_TINH_TRANG_TX='40';
   IF NUM_REC>0 THEN
      RETURN '144'; -- TX chet --
   END IF;

   SELECT COUNT(*) INTO NUM_REC FROM PN_TT_TRON_TRAI WHERE PN_ID=P_PN_ID AND NGAY_TRON<=P_NGAY_XET
   AND (NGAY_BAT_LAI IS NULL OR NGAY_BAT_LAI>P_NGAY_XET) AND MA_TINH_TRANG_TRON=20;
   IF NUM_REC>0 THEN
   		RETURN '132'; -- Tron trai chet --
   END IF;

   SELECT COUNT(*) INTO NUM_REC FROM PN_TX_TRICH_XUAT WHERE PN_ID=P_PN_ID AND MA_LENH_TX='1'
   AND NGAY_TX<=P_NGAY_XET AND NVL(NGAY_TRA_LAI,P_NGAY_XET+1)>P_NGAY_XET AND MA_TINH_TRANG_TX='50';
   IF NUM_REC>0 THEN
      RETURN '145'; -- TX tron --
   END IF;

   SELECT COUNT(*) INTO NUM_REC FROM PN_TX_TRICH_XUAT WHERE PN_ID=P_PN_ID AND MA_LENH_TX='1'
   AND NGAY_TX<=P_NGAY_XET AND NVL(NGAY_TRA_LAI,P_NGAY_XET+1)>P_NGAY_XET AND MA_TINH_TRANG_TX='97';
   IF NUM_REC>0 THEN
      RETURN '150'; -- TX huy an --
   END IF;

   SELECT COUNT(*) INTO NUM_REC FROM PN_TDC_TAM_DINH_CHI WHERE PN_ID=P_PN_ID AND MA_LENH_TDC='1'
   AND NGAY_TDC<=P_NGAY_XET AND NVL(NGAY_LAI,P_NGAY_XET+1)>P_NGAY_XET AND MA_TINH_TRANG_TDC='40';
   IF NUM_REC>0 THEN
      RETURN '154'; -- TDC tron --
   END IF;

   SELECT COUNT(*) INTO NUM_REC FROM PN_TT_TRON_TRAI WHERE PN_ID=P_PN_ID
   AND trunc(NGAY_TRON)<=P_NGAY_XET AND (NGAY_BAT_LAI IS NULL OR NGAY_BAT_LAI>P_NGAY_XET);
   IF NUM_REC >0 THEN
      RETURN '131'; -- Tron trai --
   END IF;

   SELECT COUNT(*) INTO NUM_REC FROM PN_HUY_AN WHERE PN_ID=P_PN_ID AND NGAY_TRA_TUDO<=P_NGAY_XET AND (NGAY_LAI IS NULL OR NGAY_LAI>P_NGAY_XET);
   IF NUM_REC>0 THEN
      RETURN '181'; -- Huy an --
   END IF;

   SELECT COUNT(*) INTO NUM_REC FROM PN_CHUYEN_GIAO WHERE PN_ID=P_PN_ID AND NGAY_CHUYEN_GIAO<=P_NGAY_XET;
   IF NUM_REC>0 THEN
      RETURN '127'; -- Chuyen giao --
   END IF;

   SELECT COUNT(*) INTO NUM_REC FROM PN_MIEN_HINH_PHAT WHERE PN_ID=P_PN_ID AND (NGAY_TRA_TU_DO<=P_NGAY_XET);
   IF NUM_REC>0 THEN
      RETURN '124'; -- Mien --
   END IF;

   SELECT COUNT(*) INTO NUM_REC FROM PN_CHUYEN_TRAI	WHERE PN_ID=P_PN_ID AND NGAY_CHUYEN<=P_NGAY_XET
   AND NVL(NGAY_TRO_LAI,P_NGAY_XET+1)>P_NGAY_XET AND (MA_TRUONG_HOP_CHUYEN<>50 OR MA_TRUONG_HOP_CHUYEN IS NULL);
   IF NUM_REC>0 THEN
      RETURN '161'; -- Chuyen trai khac --
   END IF;

   SELECT COUNT(*) INTO NUM_REC FROM PN_TX_TRICH_XUAT WHERE PN_ID=P_PN_ID AND MA_LENH_TX='1'
   AND NGAY_TX<=P_NGAY_XET AND NVL(NGAY_TRA_LAI,P_NGAY_XET+1)>P_NGAY_XET AND MA_TINH_TRANG_TX='30';
   IF NUM_REC>0 THEN
      RETURN '143'; -- TX chuyen trai --
   END IF;

   SELECT COUNT(*) INTO NUM_REC FROM PN_TDC_TAM_DINH_CHI WHERE PN_ID=P_PN_ID AND MA_LENH_TDC='1'
   AND NGAY_TDC<=P_NGAY_XET AND NVL(NGAY_LAI,P_NGAY_XET+1)>P_NGAY_XET AND MA_TINH_TRANG_TDC='60';
   IF NUM_REC>0 THEN
      RETURN '156'; -- TDC chuyen trai --
   END IF;

   SELECT COUNT(*) INTO NUM_REC FROM PN_TX_TRICH_XUAT WHERE PN_ID=P_PN_ID AND NGAY_TX<=P_NGAY_XET
   AND NVL(NGAY_TRA_LAI,P_NGAY_XET+1)>P_NGAY_XET AND MA_TINH_TRANG_TX='80';
   IF NUM_REC>0 THEN
      RETURN '148'; -- TX dac xa --
   END IF;

   SELECT COUNT(*) INTO NUM_REC FROM PN_TDC_TAM_DINH_CHI WHERE PN_ID=P_PN_ID AND NGAY_TDC<=P_NGAY_XET
   AND NVL(NGAY_LAI,P_NGAY_XET+1)>P_NGAY_XET AND MA_TINH_TRANG_TDC='50';
   IF NUM_REC>0 THEN
      RETURN '155'; -- TDC dac xa --
   END IF;

   SELECT COUNT(*) INTO NUM_REC FROM PN_DX_DAC_XA WHERE PN_ID=P_PN_ID
   AND NGAY_THA_DX IS NOT NULL AND MA_DUOC_DAC_XA<'20' AND NGAY_THA_DX<=P_NGAY_XET;
   IF NUM_REC>0 THEN
      RETURN '123'; -- Dac xa --
   END IF;

   SELECT COUNT(*) INTO NUM_REC FROM PN_TX_TRICH_XUAT WHERE PN_ID=P_PN_ID AND MA_LENH_TX='1'
   AND NGAY_TX<=P_NGAY_XET AND NVL(NGAY_TRA_LAI,P_NGAY_XET+1)>P_NGAY_XET AND MA_TINH_TRANG_TX='91';
   IF NUM_REC>0 THEN
      RETURN '126'; -- TX Tha truoc co DK --
   END IF;

   SELECT COUNT(*) INTO NUM_REC FROM PN_THA_CO_DK WHERE PN_ID=P_PN_ID
   AND NGAY_THA_TT IS NOT NULL AND MA_DUOC_TT<'20' AND NGAY_THA_TT<=P_NGAY_XET
   AND nvl(NGAY_TRO_LAI_TRAI,P_NGAY_XET+1)>P_NGAY_XET;
   IF NUM_REC>0 THEN
      RETURN '126'; -- Tha truoc co DK --
   END IF;

   SELECT COUNT(*) INTO NUM_REC FROM PN_GIAM_THOI_HAN WHERE PN_ID=P_PN_ID
   AND NGAY_THA_GIAM_HET_AN<=P_NGAY_XET;
   IF NUM_REC>0 THEN
      RETURN '122'; --Giam het an --
   END IF;

   SELECT COUNT(*) INTO NUM_REC FROM PN_HOAN_THI_HANH_AN
   WHERE PN_ID=P_PN_ID AND NGAY_HOAN<P_NGAY_XET AND NVL(NGAY_THI_HANH_AN,P_NGAY_XET+1)>P_NGAY_XET;
   IF NUM_REC>0 THEN
      RETURN '191'; -- Hoan THA --
   END IF;

   NUM_REC:=0;
   SELECT COUNT(*) INTO NUM_REC FROM PN_TDC_TAM_DINH_CHI WHERE PN_ID=P_PN_ID AND MA_LENH_TDC='1'
   AND NGAY_TDC<=P_NGAY_XET AND NVL(NGAY_LAI,P_NGAY_XET+1)>P_NGAY_XET AND MA_TINH_TRANG_TDC='20';
   IF NUM_REC>0 THEN
      RETURN '152'; -- TDC gia han --
   END IF;

   SELECT COUNT(*) INTO NUM_REC FROM PN_TDC_TAM_DINH_CHI WHERE PN_ID=P_PN_ID AND MA_LENH_TDC='1'
   AND NGAY_TDC<=P_NGAY_XET AND NVL(NGAY_LAI,P_NGAY_XET+1)>P_NGAY_XET AND MA_TINH_TRANG_TDC='70';
   IF NUM_REC>0 THEN
      RETURN '157'; -- TDC qua han --
   END IF;

   SELECT COUNT(*) INTO NUM_REC FROM PN_TDC_TAM_DINH_CHI WHERE PN_ID=P_PN_ID AND MA_LENH_TDC='1'
   AND NGAY_TDC<=P_NGAY_XET AND NVL(NGAY_LAI,P_NGAY_XET+1)>P_NGAY_XET AND MA_TINH_TRANG_TDC='80';
   IF NUM_REC>0 THEN
      RETURN '159'; -- TDC dc mien --
   END IF;

   SELECT COUNT(*) INTO NUM_REC FROM PN_TDC_TAM_DINH_CHI WHERE PN_ID=P_PN_ID AND MA_LENH_TDC='1'
   AND NGAY_TDC<=P_NGAY_XET AND NVL(NGAY_LAI,P_NGAY_XET+1)>P_NGAY_XET AND MA_TINH_TRANG_TDC='98';
   IF NUM_REC>0 THEN
      RETURN '158'; -- TDC xu toi moi --
   END IF;

   NUM_REC:=0;
   SELECT COUNT(*) INTO NUM_REC FROM PN_TDC_TAM_DINH_CHI WHERE PN_ID=P_PN_ID AND MA_LENH_TDC='1'
   AND NGAY_TDC<=P_NGAY_XET AND NVL(NGAY_LAI,P_NGAY_XET+1)>P_NGAY_XET;
   IF NUM_REC>0 THEN
      RETURN '151'; -- Tam dinh chi --
   END IF;

   SELECT COUNT(*) INTO NUM_REC FROM PN_TX_TRICH_XUAT WHERE PN_ID=P_PN_ID AND NGAY_TX<=P_NGAY_XET
   AND NVL(NGAY_TRA_LAI,P_NGAY_XET+1)>P_NGAY_XET AND MA_TINH_TRANG_TX='70';
   IF NUM_REC>0 THEN
      RETURN '147'; -- TX Giam het an --
   END IF;

   SELECT COUNT(*) INTO NUM_REC FROM PN_TX_TRICH_XUAT WHERE PN_ID=P_PN_ID AND NGAY_TX<=P_NGAY_XET
   AND NVL(NGAY_TRA_LAI,P_NGAY_XET+1)>P_NGAY_XET AND MA_TINH_TRANG_TX='98';
   IF NUM_REC>0 THEN
      RETURN '149'; -- TX Xu toi moi --
   END IF;

   NUM_REC:=0;
   SELECT COUNT(*) INTO NUM_REC FROM PN_TX_TRICH_XUAT WHERE PN_ID=P_PN_ID AND MA_LENH_TX='1'
   AND NGAY_TX<=P_NGAY_XET AND NVL(NGAY_TRA_LAI,P_NGAY_XET+1)>P_NGAY_XET;
   IF NUM_REC>0 THEN
      SELECT COUNT(*) INTO NUM_REC2 FROM PN_LAI_LICH WHERE PN_ID=P_PN_ID AND NVL(NGAY_RA_TRAI,P_NGAY_XET+1)<=P_NGAY_XET;
      IF NUM_REC2>0 THEN
         RETURN '146'; -- TX Het an --
      ELSE
         NUM_REC2:=0;
         SELECT COUNT(*) INTO NUM_REC2 FROM PN_TX_TRICH_XUAT WHERE PN_ID=P_PN_ID AND MA_LENH_TX='1'
         AND NGAY_TX<=P_NGAY_XET AND NVL(NGAY_TRA_LAI,P_NGAY_XET+1)>P_NGAY_XET AND MA_TINH_TRANG_TX='20';
         IF NUM_REC2>0 THEN
            RETURN '142'; -- Trich xuat gia han --
         ELSE
            RETURN '141'; -- Trich xuat --
         END IF;
      END IF;
   END IF;

   SELECT COUNT(*) INTO NUM_REC FROM PN_LAI_LICH	WHERE PN_ID=P_PN_ID AND NGAY_RA_TRAI<=P_NGAY_XET;
   IF NUM_REC>0 THEN
      NUM_REC2:=0;
   		SELECT COUNT(*) INTO NUM_REC2 FROM PN_CHUA_BENH_BAT_BUOC
      WHERE PN_ID=P_PN_ID AND (NGAY_KET_THUC IS NULL OR NGAY_KET_THUC>P_NGAY_XET);
      IF NUM_REC2>0 THEN
         RETURN '125'; -- H?t an ti?p t?c ch?a b?nh b?t bu?c --
      END IF;
   END IF;

   SELECT COUNT(*) INTO NUM_REC FROM PN_LAI_LICH	WHERE PN_ID=P_PN_ID AND NVL(NGAY_RA_TRAI,P_NGAY_XET+1)>P_NGAY_XET;
   IF NUM_REC>0 THEN
      NUM_REC2:=0;
   		SELECT COUNT(*) INTO NUM_REC2 FROM PN_GR_GIAM_RIENG WHERE PN_ID=P_PN_ID AND (NGAY_KT_GR IS NULL OR NGAY_KT_GR>P_NGAY_XET);
   		IF NUM_REC2>0 THEN
   		   RETURN '112'; -- Giam rieng --
   		END IF;
      NUM_REC2:=0;
      SELECT COUNT(*) INTO NUM_REC2 FROM PN_CHUA_BENH_BAT_BUOC WHERE PN_ID=P_PN_ID AND (NGAY_KET_THUC IS NULL OR NGAY_KET_THUC>P_NGAY_XET);
   		IF NUM_REC2>0 THEN
   		   RETURN '113'; -- Chua benh bat buoc --
   		END IF;
      RETURN '111'; -- Dang chap hanh an --
   	ELSE
   	  RETURN '121'; -- Chap hanh xong --
   	END IF;
   ----
   ELSE
    RETURN '182'; --- Xem lai ngay den trai --
   END IF;
END;
