   FUNCTION GET_GIAM_THOI_HAN (VPN_ID VARCHAR2,VNGAY_XET DATE DEFAULT SYSDATE) RETURN VARCHAR2 IS
    VRET VARCHAR2(2000);
    I NUMBER:=0;
   BEGIN
    FOR J IN (SELECT MA_MUC_DN_GIAM_TG,
             T.MUC_GIAM,
             T.SO_QD_GIAM,
             T.NGAY_QD_GIAM,
             T.TOA_QD_GIAM
          FROM V_GTH_GON T
             WHERE PN_ID=VPN_ID AND NGAY_XET<VNGAY_XET AND T.NGAY_QD_GIAM IS NOT NULL
               ORDER BY NGAY_QD_GIAM)
    LOOP
      I:=I+1;
      IF J.MA_MUC_DN_GIAM_TG='923000' THEN
          VRET:=VRET||CHR(10)||'- L?n '||I||': '||J.MUC_GIAM||' theo QD s? '||J.SO_QD_GIAM||' ngay '||TO_CHAR(J.NGAY_QD_GIAM,'dd/mm/yyyy')||' c?a '||J.TOA_QD_GIAM||'.';
      ELSE
          VRET:=VRET||CHR(10)||'- L?n '||I||': Gi?m '||J.MUC_GIAM||' theo QD s? '||J.SO_QD_GIAM||' ngay '||TO_CHAR(J.NGAY_QD_GIAM,'dd/mm/yyyy')||' c?a '||J.TOA_QD_GIAM||'.';
       END IF;
    END LOOP;
     IF I=1 THEN
       RETURN SUBSTR(VRET,INSTR(VRET,'theo'));
     END IF;
     RETURN VRET;
   END;

   FUNCTION GET_GIAM_GON (VPN_ID VARCHAR2,VNGAY_XET DATE DEFAULT SYSDATE) RETURN VARCHAR2 IS
    VRET VARCHAR2(2000);
    I NUMBER:=0;
   BEGIN
    FOR J IN (SELECT REPLACE(REPLACE(T.MUC_GIAM,' thang','T'),' nam','N') MUC_GIAM,T.NGAY_QD_GIAM
                 FROM V_GIAM_THOI_HAN T
                       WHERE PN_ID=VPN_ID AND NGAY_XET<VNGAY_XET AND T.NGAY_QD_GIAM IS NOT NULL
                           ORDER BY NGAY_QD_GIAM)
    LOOP
      I:=I+1;
      VRET:=VRET||CHR(10)||TO_CHAR(J.NGAY_QD_GIAM,'dd/mm/yyyy')||'-'||J.MUC_GIAM;
    END LOOP;
     IF I=1 THEN
       RETURN SUBSTR(VRET,INSTR(VRET,'theo'));
     END IF;
     RETURN VRET;
   END;
---------------------------------
   FUNCTION GET_HPBS (VPN_ID VARCHAR2) RETURN VARCHAR2 IS
    VRET VARCHAR2(2000);
    V_HPBS_CHUNG  VARCHAR2(2000);
   BEGIN
    FOR J IN (SELECT T.MA_HINH_PHAT,T.HINH_PHAT_BS,T.NOI_DUNG_PHAT,T.MUC_THOI_HAN,T.MA_MUC_THOI_HAN,
                     T.TONG_TIEN_PHAT,
                     DECODE(T.MA_HE_SO_TIEN,'10','d?ng',T.HE_SO_TIEN) HE_SO_TIEN,
                     T.SO_TIEN_NOP,
                     DECODE(T.SO_TIEN_NOP,NULL,' (ch?a n?p)',', d? n?p '||TRANSLATE(TO_CHAR(T.SO_TIEN_NOP,'999G999G999G999'),', ','.')||' '||DECODE(T.MA_HE_SO_TIEN,'10','d?ng',T.HE_SO_TIEN)) NOP_TIEN,
                     DECODE(T.GHI_CHU_HPBS,NULL,NULL,' '||T.GHI_CHU_HPBS) GHI_CHU_HPBS
                     FROM V_HPBS T WHERE PN_ID=VPN_ID)
    LOOP
      IF J.MA_HINH_PHAT LIKE '2%' THEN
        IF J.TONG_TIEN_PHAT IS NOT NULL THEN
          VRET:=VRET||'; '||J.HINH_PHAT_BS||' '||TRANSLATE(TO_CHAR(J.TONG_TIEN_PHAT,'999G999G999G999'),', ','.')||' '||J.HE_SO_TIEN||J.NOP_TIEN||J.GHI_CHU_HPBS;
        ELSE
          VRET:=VRET||'; '||'Hinh ph?t b? sung: '||J.HINH_PHAT_BS||J.GHI_CHU_HPBS;
        END IF;
      ELSE
        IF J.MA_MUC_THOI_HAN='000000' THEN
         VRET:=VRET||'; '||'Hinh ph?t b? sung: '||J.HINH_PHAT_BS||' '||TRANSLATE(TO_CHAR(J.TONG_TIEN_PHAT,'999G999G999G999'),', ','.')||' '||J.HE_SO_TIEN||J.GHI_CHU_HPBS;
        ELSE
         VRET:=VRET||'; '||'Hinh ph?t b? sung: '||J.HINH_PHAT_BS||' '||J.MUC_THOI_HAN||J.GHI_CHU_HPBS;
        END IF;
      END IF;
    END LOOP;
    BEGIN
    SELECT GHI_CHU_HPBS INTO V_HPBS_CHUNG FROM PN_LAI_LICH WHERE PN_ID=VPN_ID;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN V_HPBS_CHUNG:=NULL;
      WHEN OTHERS THEN V_HPBS_CHUNG:=NULL;
    END;
    VRET:=SUBSTR(VRET,2);
    IF V_HPBS_CHUNG IS NOT NULL THEN
      VRET:=VRET||' ('||V_HPBS_CHUNG||')';
    END IF;
    RETURN VRET;
   END;
---------------------------------
   FUNCTION GET_HPBS_PHIEU_GIAM (VPN_ID VARCHAR2) RETURN VARCHAR2 IS
    VRET VARCHAR2(2000);
    I NUMBER:=0;
    V_HPBS_CHUNG  VARCHAR2(2000);
   BEGIN
    BEGIN
    SELECT GHI_CHU_HPBS INTO V_HPBS_CHUNG FROM PN_LAI_LICH WHERE PN_ID=VPN_ID;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN V_HPBS_CHUNG:=NULL;
      WHEN OTHERS THEN V_HPBS_CHUNG:=NULL;
    END;
    FOR J IN (SELECT MA_HINH_PHAT,
                     COUNTMA('ma_hinh_phat_bs',MA_HINH_PHAT) HINH_PHAT_BS,
                     NOI_DUNG_PHAT,
                     COUNTMA('ma_muc_thoi_gian',MA_MUC_THOI_HAN) MUC_THOI_HAN,
                     MA_MUC_THOI_HAN,
                     TONG_TIEN_PHAT,
                     DECODE(MA_HE_SO_TIEN,'10','d?ng',COUNTMA('ma_he_so_tien',MA_HE_SO_TIEN)) HE_SO_TIEN,
                     SO_TIEN_NOP,DECODE(SO_TIEN_NOP,NULL,' (ch?a n?p)',', d? n?p '||TRANSLATE(TO_CHAR(SO_TIEN_NOP,'999G999G999G999'),', ','.')
                     ||' '||DECODE(MA_HE_SO_TIEN,'10','d?ng',COUNTMA('ma_he_so_tien',MA_HE_SO_TIEN))) NOP_TIEN,
                     DECODE(GHI_CHU_HPBS_HP,NULL,NULL,' '||GHI_CHU_HPBS_HP) GHI_CHU_HPBS
                     FROM PN_HPBS_HINH_PHAT B,
                     (SELECT MA_PN_HPBSHP,SUM(SO_TIEN_NOP) SO_TIEN_NOP FROM PN_HPBS_THUC_HIEN GROUP BY MA_PN_HPBSHP) C
                     WHERE B.PN_ID=VPN_ID AND C.MA_PN_HPBSHP(+)=B.MA_PN_HPBSHP)
    LOOP
    I:=I+1;
      IF J.MA_HINH_PHAT LIKE '2%' THEN
         VRET:=VRET||'; '||J.HINH_PHAT_BS||' '||TRANSLATE(TO_CHAR(J.TONG_TIEN_PHAT,'999G999G999G999'),', ','.')||' '||J.HE_SO_TIEN||J.NOP_TIEN||J.GHI_CHU_HPBS;
      ELSE
        IF J.MA_MUC_THOI_HAN='000000' THEN
         VRET:=VRET||'; '||J.HINH_PHAT_BS||' '||TRANSLATE(TO_CHAR(J.TONG_TIEN_PHAT,'999G999G999G999'),', ','.')||' '||J.HE_SO_TIEN||J.GHI_CHU_HPBS;
        ELSE
         VRET:=VRET||'; '||J.HINH_PHAT_BS||' '||J.MUC_THOI_HAN||J.GHI_CHU_HPBS;
        END IF;
      END IF;
    END LOOP;
    VRET:=REPLACE(VRET,CHR(10));
    IF I=1 THEN
     VRET:=SUBSTR(VRET,2);
      IF V_HPBS_CHUNG IS NOT NULL THEN
       VRET:=VRET||CHR(10)||'('||V_HPBS_CHUNG||')';
     END IF;
     RETURN VRET;
    ELSE
     VRET:=REPLACE(VRET,';',';'||CHR(10)||'   +');
     VRET:=REPLACE(VRET,' ;',';');
     VRET:=SUBSTR(VRET,2);
    IF V_HPBS_CHUNG IS NOT NULL THEN
       VRET:=VRET||CHR(10)||' ('||V_HPBS_CHUNG||')';
     END IF;
     RETURN VRET;
    END IF;
   END;
