FUNCTION GET_HPBS_PHIEU_THA_CO_DK (VPN_ID VARCHAR2) RETURN VARCHAR2 IS
    VRET VARCHAR2(2000);
    I NUMBER:=0;
    V_HPBS_CHUNG  VARCHAR2(2000);
    V_NGAY_DEN_TRAI DATE;
    V_NOP_TIEN VARCHAR2(100);
    V_NOP_TRUOC VARCHAR2(500);
    V_NOP_SAU VARCHAR2(500);
    V_CON_LAI VARCHAR2(500);
   BEGIN
    BEGIN
    SELECT GHI_CHU_HPBS, NGAY_DEN_TRAI INTO V_HPBS_CHUNG,V_NGAY_DEN_TRAI FROM PN_LAI_LICH WHERE PN_ID=VPN_ID;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN V_HPBS_CHUNG:=NULL;
      WHEN OTHERS THEN V_HPBS_CHUNG:=NULL;
    END;
    FOR J IN (SELECT H.HINH_PHAT_BS, H.TONG_TIEN_PHAT,H.HE_SO_TIEN,H.NOP_TIEN,
                H.NOP_TIEN_TRUOC, H.NOP_TIEN_SAU, H.CON_LAI, H.GHI_CHU_HPBS
                 FROM V_HPBS_THUC_HIEN H WHERE PN_ID=VPN_ID)
    LOOP
    I:=I+1;
     IF J.NOP_TIEN IS NULL THEN
        V_NOP_TIEN:=' (ch?a th?c hi?n)';
     ELSE
        V_NOP_TIEN:='';
     END IF;
     IF J.NOP_TIEN_TRUOC IS NOT NULL THEN
        V_NOP_TRUOC:=', d? th?c hi?n tr??c khi CHAPT '||TRANSLATE(TO_CHAR(J.NOP_TIEN_TRUOC,'999G999G999G999'),', ','.')||' '||J.HE_SO_TIEN;
     ELSE
        V_NOP_TRUOC:='';
     END IF;
     IF J.NOP_TIEN_SAU IS NOT NULL THEN
        V_NOP_SAU:=', d? th?c hi?n trong khi CHAPT '||TRANSLATE(TO_CHAR(J.NOP_TIEN_SAU,'999G999G999G999'),', ','.')||' '||J.HE_SO_TIEN;
     ELSE
        V_NOP_SAU:='';
     END IF;
     IF J.CON_LAI>0 AND J.NOP_TIEN IS NOT NULL THEN
        V_CON_LAI:=', ch?a th?c hi?n '||TRANSLATE(TO_CHAR(J.CON_LAI,'999G999G999G999'),', ','.')||' '||J.HE_SO_TIEN;
     ELSE
        V_CON_LAI:='';
     END IF;
      VRET:=VRET||'; '||J.HINH_PHAT_BS||': '||TRANSLATE(TO_CHAR(J.TONG_TIEN_PHAT,'999G999G999G999'),', ','.')
                ||' '||J.HE_SO_TIEN||V_NOP_TIEN||V_NOP_TRUOC||V_NOP_SAU||V_CON_LAI||J.GHI_CHU_HPBS;
    END LOOP;
    VRET:=REPLACE(VRET,CHR(10));
    IF I=0 THEN
     RETURN 'Khong';
    ELSE
     VRET:=REPLACE(VRET,';',';'||CHR(10)||'   +');
     VRET:=REPLACE(VRET,' ;',';');
     VRET:=SUBSTR(VRET,2);
     IF V_HPBS_CHUNG IS NOT NULL THEN
       VRET:=VRET||CHR(10)||' ('||V_HPBS_CHUNG||')';
     END IF;
     RETURN VRET;
    END IF;
   END;
