   FUNCTION GET_TIEN_AN (VPN_ID VARCHAR2) RETURN VARCHAR2 IS
    VRET VARCHAR2(2000);
    I NUMBER:=0;
   BEGIN
    FOR J IN (SELECT NAM_XU,
    COUNTMA('ma_cq',MA_CQ_TOA_XU_TA)||' '||COUNTMA('ma_dp',MA_DP_TOA_XU_TA) TOA_XU_TA,
    U_COUNT_MAS('ma_toi_danh',MA_TOI_DANH_TA) TOI_DANH_TA,
    MA_MUC_AN_TA,
    COUNTMA('ma_muc_thoi_gian',MA_MUC_AN_TA) MUC_AN_TA,
    T.MA_GHI_CHU_TA,
    COUNTMA('ma_ghi_chu_tien_an', T.MA_GHI_CHU_TA) ND_GHI_CHU_TA,
    DECODE(GHI_CHU_TA,NULL,'','('||GHI_CHU_TA||')') GHI_CHU_TA
    FROM PN_TIEN_AN T WHERE PN_ID=VPN_ID ORDER BY NAM_XU)
    LOOP
      I:=I+1;
      IF J.MA_MUC_AN_TA IS NULL THEN
         VRET:=VRET||CHR(10)||'- Nam '||J.NAM_XU||' '||J.TOA_XU_TA||' x? '||J.ND_GHI_CHU_TA||' v? t?i '||J.TOI_DANH_TA||J.ND_GHI_CHU_TA||J.GHI_CHU_TA||'.';
      ELSIF J.MA_MUC_AN_TA LIKE '9%' THEN
         VRET:=VRET||CHR(10)||'- Nam '||J.NAM_XU||' '||J.TOA_XU_TA||' x? '||J.MUC_AN_TA||' '||J.ND_GHI_CHU_TA||' v? t?i '||J.TOI_DANH_TA||J.GHI_CHU_TA||'.';
      ELSE
         VRET:=VRET||CHR(10)||'- Nam '||J.NAM_XU||' '||J.TOA_XU_TA||' x? '||J.MUC_AN_TA||
                              ' tu v? t?i '||J.TOI_DANH_TA||J.GHI_CHU_TA||'.';
      END IF;
    END LOOP;
    IF I=1 THEN VRET:=SUBSTR(VRET,3); END IF;
    RETURN VRET;
   END;
