   FUNCTION GET_XEP_LOAI(VPN_ID VARCHAR2,VNAM_XL NUMBER) RETURN VARCHAR2 IS
    VRET VARCHAR2(2000);
   BEGIN
     FOR J IN (SELECT T.NAM_XL,T.XEP_LOAI, DECODE(T.XEP_LOAI_CUOI,NULL,DECODE(T.GHI_CHU,NULL,NULL,'; '||T.GHI_CHU)) GHI_CHU
              FROM V_PN_XLCT_GON T WHERE T.PN_ID=VPN_ID AND T.NAM_XL>=VNAM_XL ORDER BY T.NAM_XL)
     LOOP
           VRET:=VRET||CHR(10)||'+ Nam '||J.NAM_XL||': '||J.XEP_LOAI;
     END LOOP;
     RETURN REPLACE(SUBSTR(VRET,2),';;',';');
   END;

   FUNCTION GET_XEP_LOAI_GON(VPN_ID VARCHAR2,VNAM_XL NUMBER) RETURN VARCHAR2 IS
    VRET VARCHAR2(2000);
   BEGIN
     FOR J IN (SELECT T.NAM_XL,T.XEP_LOAI_GON, DECODE(T.XEP_LOAI_CUOI,NULL,DECODE(T.GHI_CHU,NULL,NULL,'; '||T.GHI_CHU)) GHI_CHU
              FROM V_PN_XLCT_GON T WHERE T.PN_ID=VPN_ID AND T.NAM_XL>=VNAM_XL ORDER BY T.NAM_XL)
     LOOP
           VRET:=VRET||CHR(10)||J.NAM_XL||': '||J.XEP_LOAI_GON;
     END LOOP;
     RETURN REPLACE(SUBSTR(VRET,2),';;',';');
   END;
---------------------------------
   FUNCTION GET_XEP_LOAI_QUY_GON(VPN_ID VARCHAR2,VNAM_XL NUMBER) RETURN VARCHAR2 IS
    VRET VARCHAR2(2000);
   BEGIN
     FOR J IN (SELECT T.NAM_XL,T.XEP_LOAI_QUY_GON, DECODE(T.XEP_LOAI_CUOI,NULL,DECODE(T.GHI_CHU,NULL,NULL,'; '||T.GHI_CHU)) GHI_CHU
              FROM V_PN_XLCT_GON T WHERE T.PN_ID=VPN_ID AND T.NAM_XL>=VNAM_XL ORDER BY T.NAM_XL)
     LOOP
           VRET:=VRET||CHR(10)||J.NAM_XL||': '||J.XEP_LOAI_QUY_GON;
     END LOOP;
     RETURN REPLACE(SUBSTR(VRET,2),';;',';');
   END;

   FUNCTION QUAN_HE_GIA_DINH(VPN_ID VARCHAR2,V_MA_QH VARCHAR2) RETURN VARCHAR2 IS
    VRET VARCHAR2(4000);
    I    NUMBER:=0;
   BEGIN
   FOR J IN (SELECT T.HO_TEN_QHGD,
                    DECODE(T.NGAY_SINH_QHGD,NULL,'',';'||CHR(9)||' Nam sinh: '||T.NGAY_SINH_QHGD) NGAY_SINH_QHGD,
                    DECODE(T.NGHE_NGHIEP_QHGD,NULL,'',';'||CHR(9)||' Ngh? nghi?p: '||T.NGHE_NGHIEP_QHGD) NGHE_NGHIEP_QHGD,
                    DECODE(T.NOI_O,NULL,'',';'||CHR(10)||' Ch? ? hi?n nay: '||T.NOI_O) NOI_O,
                    T.GHI_CHU_QHGD
    FROM PN_QUAN_HE_GIA_DINH T WHERE T.PN_ID=VPN_ID AND T.MA_QUAN_HE=V_MA_QH)
   LOOP
    IF V_MA_QH='151' THEN
      IF BO_DAU(J.HO_TEN_QHGD)=BO_DAU('Cac con') THEN
          VRET:=' '||J.GHI_CHU_QHGD;
      ELSE
          VRET:=VRET||CHR(10)||'   + '||J.HO_TEN_QHGD||J.NGAY_SINH_QHGD
                    ||J.NGHE_NGHIEP_QHGD||J.NOI_O;
      END IF;
    ELSE
     VRET:=VRET||J.HO_TEN_QHGD||J.NGAY_SINH_QHGD
               ||J.NGHE_NGHIEP_QHGD||J.NOI_O;
    END IF;
    I:=I+1;
   END LOOP;
    IF I>0 THEN
       RETURN VRET;
    ELSE
      IF V_MA_QH IN ('151','131','132') THEN
       RETURN ' Ch?a co';
      END IF;
     RETURN '';
    END IF;
   END;
