   FUNCTION GET_HPBS_CONLAI (VPN_ID VARCHAR2) RETURN VARCHAR2 IS
    VRET VARCHAR2(2000);
    I NUMBER:=0;
    --V_HPBS_CHUNG VARCHAR2(2000);
   BEGIN
  FOR J IN (SELECT T.MA_HINH_PHAT,T.HINH_PHAT_BS,T.NOI_DUNG_PHAT,T.MA_MUC_THOI_HAN,T.MUC_THOI_HAN,
                   T.GHI_CHU_HPBS,
                   T.TONG_TIEN_PHAT TONG_TIEN_PHAT,
                   DECODE(T.MA_HE_SO_TIEN,'10','d?ng',T.HE_SO_TIEN) HE_SO_TIEN,
                   T.SO_TIEN_NOP,
                   TRANSLATE(TO_CHAR(T.TONG_TIEN_PHAT-NVL(T.SO_TIEN_NOP,0),'999G999G999G999'),', ','.') CON_LAI,
                   DECODE(T.SO_TIEN_NOP,NULL,' (Ch?a n?p)',
                   ' (T?ng ti?n: '||TRANSLATE(TO_CHAR(T.TONG_TIEN_PHAT,'999G999G999G999'),', ','.')||' '
                   ||DECODE(T.MA_HE_SO_TIEN,'10','d?ng',T.HE_SO_TIEN)||', d? n?p: '
                   ||TRANSLATE(TO_CHAR(T.SO_TIEN_NOP,'999G999G999G999'),', ','.')
                   ||' '||DECODE(T.MA_HE_SO_TIEN,'10','d?ng',T.HE_SO_TIEN)) NOP_TIEN
                   FROM V_HPBS_GON T WHERE PN_ID=VPN_ID
                   AND (T.TONG_TIEN_PHAT-NVL(T.SO_TIEN_NOP,0)>0))
  LOOP
    I:=I+1;
    IF J.MA_HINH_PHAT LIKE '2%' THEN
       VRET:=VRET||'; '||J.HINH_PHAT_BS||': '||J.CON_LAI||' '||J.HE_SO_TIEN||J.NOP_TIEN||' '||J.GHI_CHU_HPBS;
    ELSE
      IF J.MA_MUC_THOI_HAN='000000' THEN
       VRET:=VRET||'; '||J.HINH_PHAT_BS||': '||J.TONG_TIEN_PHAT||' '||J.HE_SO_TIEN||' '||J.GHI_CHU_HPBS;
      ELSE
       VRET:=VRET||'; '||J.HINH_PHAT_BS||': '||J.MUC_THOI_HAN||' '||J.GHI_CHU_HPBS;
      END IF;
    END IF;
  END LOOP;
 IF I>0 THEN
    RETURN SUBSTR(VRET,2);
 END IF;
    RETURN ' Khong';
 END;
