 FUNCTION GET_HPBS_KHAC (VPN_ID VARCHAR2) RETURN VARCHAR2 IS
  VRET VARCHAR2(2000);
  I NUMBER:=0;
 BEGIN
  FOR J IN (SELECT T.MA_HINH_PHAT,T.HINH_PHAT_BS,T.NOI_DUNG_PHAT,T.MUC_THOI_HAN,T.TONG_TIEN_PHAT,T.GHI_CHU_HPBS
                   FROM V_HPBS_GON T WHERE PN_ID=VPN_ID AND (T.MA_HINH_PHAT LIKE '1%' or T.MA_HINH_PHAT LIKE '3%'))
  LOOP
        I:=I+1;
       IF J.MA_HINH_PHAT LIKE '1%' or J.MA_HINH_PHAT LIKE '3%' THEN
      ----  VRET:=VRET||'; '||'Hinh ph?t b? sung: '||J.HINH_PHAT_BS||' '||J.MUC_THOI_HAN||' '||J.GHI_CHU_HPBS;
        VRET:=VRET||'; '||J.HINH_PHAT_BS||' '||J.MUC_THOI_HAN||' '||J.GHI_CHU_HPBS;
       ELSE
       ---   VRET:=VRET||'; '||'Hinh ph?t b? sung: '||J.HINH_PHAT_BS||' '||J.GHI_CHU_HPBS;
       VRET:=VRET||'; '||J.HINH_PHAT_BS||' '||J.GHI_CHU_HPBS;
       END IF;
  END LOOP;
  IF I>0 THEN
   RETURN SUBSTR(VRET,2);
  ELSE
   RETURN ' Khong';
 END IF;
 END;
---------------------------------
 FUNCTION GET_HPBS_TONG (VPN_ID VARCHAR2) RETURN VARCHAR2 IS
  VRET VARCHAR2(4000);
  I NUMBER:=0;
  --V_CHUA_NOP NUMBER;
 BEGIN
  FOR J IN (SELECT TRANSLATE(TO_CHAR(SUM(NVL(T.TONG_TIEN_PHAT,0)),'999G999G999G999'),', ','.') TONG_TIEN_PHAT,
                   TRANSLATE(TO_CHAR(SUM(NVL(T.SO_TIEN_NOP,0)),'999G999G999G999'),', ','.') SO_TIEN_NOP,
                   TRANSLATE(TO_CHAR(SUM(NVL(T.TONG_TIEN_PHAT,0)-NVL(T.SO_TIEN_NOP,0)),'999G999G999G999'),', ','.') TONG_CHUA_NOP
                   FROM V_HPBS_GON T WHERE PN_ID=VPN_ID)
  LOOP
    I:=I+1;
    VRET:= '- T?ng s?: '||J.TONG_TIEN_PHAT||'d'||CHR(10)||'- D? n?p: '||J.SO_TIEN_NOP||'d'||CHR(10)||'- Ch?a n?p: '||J.TONG_CHUA_NOP||'d';
  END LOOP;
 IF I>0 THEN
   RETURN VRET;
 ELSE
   RETURN '';
 END IF;
 END;
---------------------------------
 FUNCTION GET_HPBS_CONTIEN (VPN_ID VARCHAR2) RETURN NUMBER IS
  VRET NUMBER;
  --I NUMBER:=0;
 BEGIN
  SELECT SUM(T.TONG_TIEN_PHAT-NVL(T.SO_TIEN_NOP,0)) INTO VRET
         FROM V_HPBS_GON T WHERE PN_ID=VPN_ID;
   RETURN VRET;
 END;

 PROCEDURE GET_TIEN_HPBS (VPN_ID VARCHAR2,V_PHAI_NOP OUT NUMBER,V_DA_NOP OUT NUMBER,V_CHUA_NOP OUT NUMBER) IS
  --PHAI_NOP NUMBER;
  --DA_NOP   NUMBER;
  --CHUA_NOP NUMBER;
  --I NUMBER:=0;
  BEGIN
    BEGIN
   SELECT SUM(TONG_TIEN_PHAT),SUM(SO_TIEN_NOP),SUM(T.TONG_TIEN_PHAT-NVL(T.SO_TIEN_NOP,0))
     INTO V_PHAI_NOP,V_DA_NOP,V_CHUA_NOP
       FROM V_HPBS_GON T WHERE PN_ID=VPN_ID;
    EXCEPTION
      WHEN OTHERS THEN V_CHUA_NOP:=NULL;V_PHAI_NOP:=NULL;V_DA_NOP:=NULL;
   END;
 END;
---------------------------------
 FUNCTION GET_MIEN_HINH_PHAT (VPN_ID VARCHAR2,VNGAY_XET DATE DEFAULT SYSDATE) RETURN VARCHAR2 IS
  VRET VARCHAR2(2000);
  I NUMBER:=0;
 BEGIN
  FOR J IN (SELECT T.TOI_DANH_MIEN, T.THOI_GIAN_MIEN, T.TOA_QD,
                   DECODE(T.QD_MIEN_SO,NULL,'',' s? '||T.QD_MIEN_SO) SO_QD,
                   DECODE(T.QD_MIEN_NGAY,NULL,'',' ngay '||TO_CHAR(T.QD_MIEN_NGAY,'dd/mm/yyyy')) NGAY_QD
            FROM V_PN_MIEN_HINH_PHAT T
           WHERE PN_ID=VPN_ID AND NVL(QD_MIEN_NGAY,VNGAY_XET-1)<VNGAY_XET
             ORDER BY QD_MIEN_NGAY)
  LOOP
    I:=I+1;
    VRET:=VRET||CHR(10)||'D??c mi?n t?i danh: '||J.TOI_DANH_MIEN||', th?i h?n '||J.THOI_GIAN_MIEN||
                         ' theo QD'||J.SO_QD||J.NGAY_QD||' c?a '||J.TOA_QD||';';
  END LOOP;
  IF I>0 THEN
  RETURN SUBSTR(VRET,2);
  END IF;
  RETURN NULL;
 END;
---------------------------------
 FUNCTION GET_PLGG(VPN_ID VARCHAR2,NGAY_XET DATE DEFAULT SYSDATE) RETURN VARCHAR2 IS
  VRET VARCHAR2(2000);
 BEGIN
   FOR J IN (SELECT TO_CHAR(T.NGAY_PHAN_LOAI,'dd/mm/yyyy') NGAY_PHAN_LOAI, T.ND_DEN_LOAI
              FROM DS_PHAN_LOAI T
              WHERE T.PN_ID=VPN_ID
              AND T.NGAY_PHAN_LOAI<=NGAY_XET
              ORDER BY T.NGAY_PHAN_LOAI)
   LOOP
         VRET:=VRET||CHR(10)||J.NGAY_PHAN_LOAI||' - '||J.ND_DEN_LOAI;
   END LOOP;
   RETURN REPLACE(SUBSTR(VRET,2),CHR(10)||CHR(10),CHR(10));
 END;
---------------------------------
 FUNCTION GET_QD_AN_GIAM (VPN_ID VARCHAR2,V_TIEUDE VARCHAR2 DEFAULT NULL) RETURN VARCHAR2 IS
  VRET VARCHAR2(2000);
  I NUMBER:=0;
  TIEUDE VARCHAR2(200);
 BEGIN
  IF V_TIEUDE IS NULL THEN
     TIEUDE:='Quy?t d?nh an gi?m c?a Ch? t?ch n??c ';
   ELSE
     TIEUDE:=V_TIEUDE;
   END IF;
  FOR J IN (SELECT T.SO_QD, T.NGAY_QD NGAY_QD
            FROM PN_QD_AN_GIAM T
            WHERE PN_ID=VPN_ID)
  LOOP
    I:=I+1;
    VRET:=CHR(10)||TIEUDE||' s? '||J.SO_QD||' ngay '||TO_CHAR(J.NGAY_QD,'dd/mm/yyyy');
  END LOOP;
  IF I>0 THEN
  RETURN VRET;
  END IF;
  RETURN NULL;
 END;
---------------------------------
END;

