/************ In_One_Number function *********************
 Date:    Sat, Dec 2nd, 2006
 Function: Return 1 if the the number in in the range of two values
*/
Function In_One_Number(The_Number number,Value_from number,Value_to number) RETURN number IS
Begin
  if The_Number>=Value_from and The_Number<=Value_to then
 		return 1;
  end if;
  return 0;
End;
/************ In_One_Number function *********************
 Date:    Sat, Dec 2nd, 2006
 Function: Return 1 if the two numbers in in the ranges of two correlative values
*/
Function In_Two_Number(The_Number1 number,Value_from1 number,Value_to1 number,The_Number2 number,Value_from2 number,Value_to2 number) RETURN number IS
Begin
  if The_Number1>=Value_from1 and The_Number1<=Value_to1 and The_Number2>=Value_from2 and The_Number2<=Value_to2 then
 		return 1;
  end if;
  return 0;
End;

/************ In_One_Date function *********************
 Date:    Sat, Dec 2nd, 2006
 Function: Return 1 if the Date in in the ranges of two values
*/
Function In_One_Date(The_Date date,Value_from Date,Value_to date) RETURN number IS
Begin
	if the_date is null then return 0;end if;
  if The_Date>=Value_from and The_Date<=Value_to then
	 return 1;
  end if;
  return 0;
End;

/************ In_Two_Date function *********************
 Date:    Sat, Dec 2nd, 2006
 Function: Return 1 if the two numbers in in the ranges of two correlative values
*/
Function In_Two_Date(The_Date1 date,Value_from1 Date,Value_to1 date,The_Date2 date,Value_from2 date,Value_to2 date) RETURN number IS
Begin
  if The_Date1>=Value_from1 and The_Date1<=Value_to1 and The_Date2>=Value_from2 and The_Date2<=Value_to2 then
 return 1;
  end if;
  return 0;
End;
/************ In_One_Date_And_One_Number *********************
 Date:    Sat, Oct 24th, 2007
 Function: Return 1 if the one Date and one number in in the ranges of two correlative values
*/

Function In_One_Date_And_One_Number(The_Date date,Date_Value_from date,Date_Value_to date,The_Number number,Number_Value_from number,Number_Value_to number) RETURN number is
Begin
  if The_Date>=Date_Value_from and The_Date<=Date_Value_to and The_Number>=Number_Value_from and The_Number<=Number_Value_to then
	 return 1;
  end if;
  return 0;
End;

/************ In_String function *********************
 Date:    Sat, Dec 2nd, 2006
 Function: Return 1 if the checked string in  the source string
*/
Function In_String(Checked_String varchar2, Source_String varchar2,p_toan_tu number default 0) RETURN number IS
p_ketqua number(4);
p_WORD varchar2(200);
p_Data varchar2(2000);
i number(4);
LenStr number(4);
Begin
	p_ketqua:=0;
	if Checked_String is null then return 0;end if;
	if Source_String is null then return 0;end if;
	if nvl(p_toan_tu,0)<>0 then
		Lenstr:=length(Checked_String);
		p_data:=Checked_String||';';
	  for i in 1..LenStr+1
	  loop
	  	if substr(p_data,i,1)=';' then
	  		if instr(Source_String,p_word)>0 then
	  			return 1;
	  		else
	  			p_word:=null;
	  		end if;
	  	else
	  		p_word:=p_word||substr(p_data,i,1);
	  	end if;
	  end loop;
	  if instr(Source_String,p_word)>0 then
	  	p_ketqua:=1;
	  else
	  	p_ketqua:=0;
	  end if;
  else
  	if checked_string=source_string then
	  	p_ketqua:=1;
	  else
	  	p_ketqua:=0;
	  end if;
  end if;
  return p_ketqua;
End;
END; --- of PN_RANGE BODY: odified on 17/10/2011

