Function Get_ho_ten_chuan(p_ho_ten varchar2) RETURN varchar2 is
	strList    varchar2(100):=lower(p_ho_ten)||' ';
	i          number;
	pos        number;
	currstr    varchar2(100);
	the_return varchar2(100);
	TerminateChars varchar2(100):=' ,.;:-!()?"<>/';
begin
	for i in 1..length(strList) loop
			pos:=instr(strList,' ');
		if pos>0  then
			currstr:=substr(strList,1,pos);
			currstr:=upper(substr(currstr,1,1))||substr(currstr,2);
			the_return:=the_return||currstr||'';
			strList:=ltrim(substr(strList,pos+1));
		end if;
	end loop;
	return the_return;
end; -- of Get_ho_ten_chuan

