Function get_nd_from_ma(p_Table_Name varchar2, p_ma_col varchar2,p_nd_col varchar2,p_ma_value varchar2) RETURN varchar2 IS
  str				varchar2(2000):=p_ma_value||';';
	curr      varchar2(20);
	pos       number;
	lst       varchar2(2000);
	nName     varchar2(2000);
	strSql    varchar2(2000);
Begin
	loop
		pos:=instr(str,';');
		curr:=substr(str,1,pos-1);
		strSql:='select '||p_nd_col||' from '||p_Table_Name||' where upper('||p_ma_col||')=upper('''||curr||''')';
		execute immediate strSql into nName;
		lst:=lst||nName||';';
		str:=substr(str,pos+1);
		if str is null then exit; end if;
	end loop;
	if pos>0 then
		lst:=substr(lst,1,length(lst)-1);
	end if;
	return lst;
	exception
		when no_data_found then return null;
		when others then return null;
End; --- of get_nd_from_ma


/************ Get_Gia_Tri_Mac_Dinh function *********************
 Function: L?y gia tr? m?c ??nh trong b?ng PN_DEFAULT values
*/
--BEGIN
Function Get_Gia_Tri_Mac_Dinh(P_Field_Code varchar2) RETURN varchar2 IS
   p_ketqua varchar2(5000);
Begin
	  select field_value into p_ketqua from PN_DEFAULT_VALUES where Field_Code=P_FIELD_CODE;
	  return p_ketqua;
	exception
		when no_data_found then return null;
		when others then return null;
End;
/************ Get_The_Where_In_Text function *********************
 Function: L?y Query theo tr??ng TEXT
*/
Function Get_The_Where_In_Text(Field_Name varchar2,Field_Value_Name varchar2) RETURN char IS
	the_where varchar2(500);
Begin
  if to_number(substr(nvl(Field_Value_Name,'000'),1,1))=0 then
  	the_where:=null;
  else
  	the_where:='to_number('||Field_Name||') in ('||replace(Field_Value_Name,';',',')||')';
  end if;
  return the_where;
End;
/************ Get_The_Where_In_Date function *********************
 Function: L?y Query theo tr??ng Date
*/
Function Get_The_Where_In_Date(Field_Name varchar2,Date_From date,Date_To date) RETURN char IS
	the_where varchar2(500);
Begin
  if Date_From is null then
  	if Date_To is null then
  		the_where:=null;
  	else
  		the_where:=Field_Name||'<='||chr(39)||to_char(Date_To,'DD-MON-YYYY')||chr(39);
  	end if;
  else
  	if Date_To is null then
  		the_where:=Field_Name||'>='||chr(39)||to_char(Date_From,'DD-MON-YYYY')||chr(39);
  	else
  		the_where:=Field_Name||'>='||chr(39)||to_char(Date_From,'DD-MON-YYYY')||chr(39)||' and '||Field_Name||'<='||chr(39)||to_char(Date_To,'DD-MON-YYYY')||chr(39);
  	end if;
  end if;
  return the_where;
End;
/************ Get_The_Where_In_Number function *********************
 Function: L?y Query theo tr??ng Number
*/
Function Get_The_Where_In_Number(Field_Name varchar2,Num_From number,Num_To number) RETURN char IS
	the_where varchar2(500);
Begin
  if nvl(Num_From,0)=0 then
  	if nvl(Num_To,0)=0 then
  		the_where:=null;
  	else
  		the_where:=Field_Name||'<='||to_Char(Num_To);
  	end if;
  else
  	if nvl(Num_To,0)=0 then
  		the_where:=Field_Name||'>='||to_Char(Num_From);
  	else
  		the_where:=Field_Name||'>='||to_Char(Num_From)||' and '||Field_Name||'<='||to_Char(Num_To);
  	end if;
  end if;
  return the_where;
End;
/************ Get_The_Where_In_Where function *********************
 Function: L?y Query theo m?t Query khac
*/
Function Get_The_Where_In_Where(Main_Where varchar2, Sub_Where varchar2) RETURN char IS
	the_where varchar2(1000);
Begin
	if Sub_Where is not null then
		if Main_Where is null then
			the_where:=Sub_Where;
		else
			the_where:=Main_Where||' and '||Sub_Where;
		end if;
	else
		the_where:=Main_Where;
	end if;
	return the_where;
End;
/************ Get_String_Number function *********************
 Function: L?y k?t qu? m?t s? theo xau ky t?
*/
Function Get_String_Number(The_Num Number) RETURN char IS
LenStr number(4);
Rem_num number(4);
Num number(4);
p_data varchar2(100);
p_ketqua varchar2(100);
Begin
	if The_Num=0 then return null;end if;
  p_Data:=to_char(The_Num);
  Lenstr:=length(p_data);
  if Lenstr>3 then
  	Rem_num:=mod(Lenstr,3);
	  p_data:=lpad(p_Data,lenstr+(3-rem_num),'@');
	  Lenstr:=length(p_data);
	  	for num in 1..Lenstr
		  loop
		  	if mod(num,3)=0 and num<lenstr then
		  			p_ketqua:=p_ketqua||substr(p_data,num,1)||'.';
		  	else
			  	p_ketqua:=p_ketqua||substr(p_data,num,1);
		  	end if;
		  end loop;
	  num:=1;
	  loop
	  	if num>=lenstr or substr(p_ketqua,num,1)<>'@' then
	  		exit;
	  	else
	  		num:=num+1;
	  	end if;
	  end loop;
	  P_ketqua:=substr(p_ketqua,num);
	  if substr(p_ketqua,1,1)='.' then 	p_ketqua:=substr(p_ketqua,2);end if;
	else
		p_ketqua:=p_data;
	end if;

  return p_ketqua;
End; --- of get_string_number

/************ Get_Number_From_Ma_String function *********************
 Function:
*/
Function Get_Number_From_Ma_String(p_ma_string varchar2, p_loai_kq char default 'M') RETURN number IS
so_nam number(10);
so_thang number(10);
so_ngay number(10);
Begin
	so_nam:=to_number(substr(p_ma_string,1,2));
	so_thang:=to_number(substr(p_ma_string,3,2));
	so_ngay:=to_number(substr(p_ma_string,5,2));
	--return so_thang;
	if upper(p_loai_kq)='Y' then
		return so_nam;
	end if;
	if upper(p_loai_kq)='M' then
		return so_nam*12+so_thang;
	end if;
	if upper(p_loai_kq)='D' then
		return so_ngay;
	end if;
	if upper(p_loai_kq)='SD' then -- tong so ngay
		return (so_nam*12+so_thang)*30+so_ngay;
	end if;
 return 0;
End;  --- of Get_Number_From_Ma_String

/************ Get_Number_From_Ma_String function *********************
 Function:
*/
Function Get_Ma_String_From_Numbers(p_so_thang number,p_so_ngay number) RETURN char IS
i number(4):=0;
so_nam number(10);
so_thang number(10);
so_ngay number(10);
Begin
	so_thang:=nvl(p_so_thang,0)+trunc(nvl(p_so_ngay,0)/30);
	so_ngay:=mod(nvl(p_so_ngay,0),30);
	i:=0;
	while so_ngay<0 loop
		i:=i-1;
		so_ngay:=so_ngay+30;
	end loop;
	while so_ngay>=30 loop
		i:=i+1;
		so_ngay:=so_ngay-30;
	end loop;

	so_thang:=so_thang+i;

	so_nam:=trunc(so_thang/12);
	so_thang:=mod(so_thang,12);
	--if so_nam>30 then so_nam:=30;so_ngay:=0;end if;

	if so_thang<0 or so_ngay<0 then return '000000';end if;

 	return lpad(to_char(so_nam),2,'0')||lpad(to_char(so_thang),2,'0')||lpad(to_char(so_ngay),2,'0');
End;  --- of Get_Ma_String_From_Numbers
