Function GET_ERROR_ON_WARD(Ward_string varchar2,Disc_code number) RETURN number IS
-- Created:  Nguyen Van Khuyen
-- Date:     Wed, Sep 5th, 2007
-- Function: Get ERROR on WARD
Cursor PX_CUR is select nd NAME_WARD from ma_dp_xa_phuong where ma_qh=Disc_code;
PX_REC PX_CUR%rowtype;
P_WARD varchar2(100);
P_WARD_DIST varchar2(100);
P_ketqua number(4);
FUNCTION GET_NARROW_WARD2(WARD_STRING2 varchar2) RETURN varchar2 IS
		-- Created:  Nguyen Van Khuyen
		-- Date:     Sun, Jul 8, 2006
		-- Function: Get narrow form of Ward of Prison
		p_char2 varchar2(2);
		p_data2 varchar2(200);
		p_ketqua2 varchar2(200);
		BEGIN
			p_data2:=WARD_STRING2;
			if substr(p_data2,1,1)=' ' then p_data2:=substr(p_data2,2);end if;
			if substr(p_Data2,1,1)='F' then
				p_Data2:=replace(p_Data2,'F. ','Ph??ng ');
				p_Data2:=replace(p_Data2,'F.','Ph??ng ');
				p_Data2:=replace(p_Data2,'F ','Ph??ng ');
				p_Data2:=replace(p_Data2,'F . ','Ph??ng ');
				p_Data2:=replace(p_Data2,'F.','Ph??ng ');
			end if;
			if substr(p_Data2,1,1)='P' then
				p_Data2:=replace(p_Data2,'P . ','Ph??ng ');
				p_Data2:=replace(p_Data2,'P. ','Ph??ng ');
				p_Data2:=replace(p_Data2,'P.','Ph??ng ');
				p_Data2:=replace(p_Data2,'P ','Ph??ng ');
				p_Data2:=replace(p_Data2,'P. ','Ph??ng ');
				p_Data2:=replace(p_Data2,'P: ','Ph??ng ');
				p_Data2:=replace(p_Data2,'P:','Ph??ng ');
			end if;
			if substr(p_Data2,1,1)='T' then
				p_Data2:=replace(p_Data2,'TT. ','Th? tr?n ');
				p_Data2:=replace(p_Data2,'TT.','Th? tr?n ');
				p_Data2:=replace(p_Data2,'TT ','Th? tr?n ');
				p_Data2:=replace(p_Data2,'T,T','Th? tr?n ');
				p_Data2:=replace(p_Data2,'T T','Th? tr?n ');
				p_Data2:=replace(p_Data2,'TT','Th? tr?n ');
				p_Data2:=replace(p_Data2,'Th? Tr?n ','Th? tr?n ');
			end if;
			if substr(p_Data2,1,1)='X' then
				p_Data2:=replace(p_Data2,'X. ','X? ');
				p_Data2:=replace(p_Data2,'X, ','X? ');
				p_Data2:=replace(p_Data2,'X.','X? ');
				p_Data2:=replace(p_Data2,'X,','X? ');
				p_Data2:=replace(p_Data2,'X?. ','X? ');
				p_Data2:=replace(p_Data2,'X?, ','X? ');
				p_Data2:=replace(p_Data2,'X?.','X? ');
				p_Data2:=replace(p_Data2,'X?,','X? ');
			end if;
			p_Data2:=replace(p_Data2,'Th? tr?n ',' ');
			p_Data2:=replace(p_Data2,'Ph??ng ',' ');
			p_Data2:=replace(p_Data2,'X? ',' ');
			if p_Data2 is not null then
				if substr(p_Data2,1,1)=' ' then
					p_data2:=substr(p_Data2,2);
				end if;
				if substr(p_Data2,1,1)='0' then
					p_ketqua2:=substr(p_Data2,2);
				else
					p_ketqua2:=p_data2;
				end if;
			end if;
		  p_ketqua2:=replace(p_ketqua2,'oe','oe');
		  p_ketqua2:=replace(p_ketqua2,'oa','oa');
		  p_ketqua2:=replace(p_ketqua2,'oa','oa');
		  p_ketqua2:=replace(p_ketqua2,'?y','u?');
		  p_ketqua2:=replace(p_ketqua2,'uy','u?');
		  p_ketqua2:=replace(p_ketqua2,'uy','uy');
		  p_ketqua2:=replace(p_ketqua2,'?y','u?');
--		  p_ketqua2:=replace(p_ketqua2,'o5','_a');
--		  p_ketqua2:=replace(p_ketqua2,'o9','da');
---		  p_ketqua2:=replace(p_ketqua2,'?k','?c');

			if substr(p_data2,1,1) in ('P','F') and substr(p_data2,2,1) in ('1','2','3','4','5','6','7','8','9') then p_data2:='Ph??ng '||substr(p_data2,2);end if;
		  return P_KETQUA2;
		END GET_NARROW_WARD2;
BEGIN
	P_WARD:=GET_NARROW_WARD2(WARD_STRING);
	P_Ketqua:=0; -- ERROR
	for PX_REC in PX_CUR
	loop
		P_WARD_DIST:=GET_NARROW_WARD2(PX_REC.NAME_WARD);
		if upper(P_WARD)=upper(P_WARD_DIST) then P_KETQUA:=1;exit;end if;
	end loop;
	return p_ketqua;
END; -- of GET_ERRORS_ON_WARDS
/************ Get_DO_TUOI function *********************
 Function: Tinh ?? tu?i ph?m nhan va ng??i khac
*/
Function Get_Do_Tuoi(Ngay_Sinh number,Thang_Sinh number,Nam_Sinh number,Ngay_Moc date,FM varchar2) RETURN number IS
so_thang number(10):=0;
so_ngay number(10):=0;
p_Ngay_Thang date;
Begin
 if nvl(Ngay_Sinh,0)>0 and nvl(Thang_Sinh,0)>0 then
 	p_ngay_thang:=to_date(to_Char(Ngay_Sinh)||'/'||to_Char(Thang_Sinh)||'/'||to_Char(Nam_Sinh),'DD/MM/YYYY');
	so_thang:=pn_date.date_minus(p_ngay_Thang,Ngay_Moc,'MF');
	so_ngay:=pn_date.date_minus(p_ngay_Thang,Ngay_Moc,'D');
 else
 	so_thang:=(to_number(to_char(Ngay_Moc,'yyyy'))-Nam_Sinh)*12;
 	so_ngay:=0;
 end if;
  if upper(FM)='DD' then -- so ngay le cua tuoi
  	return nvl(SO_NGAY,0);
  elsif upper(FM)='MM' then
  	return nvl(SO_THANG,0); -- so thang tuoi
  elsif upper(FM)='MD' then -- so ngay tuoi
  	return nvl(SO_THANG,0)*30+nvl(SO_ngay,0);
  end if;
 return 0;
End;  --- of GET_DO_TUOI

/************ Get_DO_TUOI_From_char_date function *********************
 Function: Tinh do tuoi PN tu truogn text
*/
Function Get_Do_Tuoi_From_CharDate(p_Birthdate varchar2,p_Ngay_Moc date,FM varchar2 default 'MD') RETURN number IS
p_ngay_sinh varchar2(10);
p_ngay_thang date;
p_ngay number(10):=0;
p_thang number(10):=0;
p_nam number(10):=0;
so_thang number(10):=0;
so_ngay number(4):=0;
Begin
 p_ngay_sinh:=lpad(p_birthdate,10,'0');
 p_ngay:=to_number(substr(p_ngay_sinh,1,2));
 p_thang:=to_number(substr(p_ngay_sinh,4,2));
 p_nam:=to_number(substr(p_ngay_sinh,7));

 if p_ngay>0 then  --- Neu co ngay
 	if p_thang=0 then
	 	so_thang:=(to_number(to_char(p_Ngay_Moc,'yyyy'))-p_nam)*12;
	 	so_ngay:=0;
 	else
		p_ngay_thang:=to_date(to_Char(p_ngay)||'/'||to_Char(p_thang)||'/'||to_Char(p_nam),'DD/MM/YYYY');
		so_thang:=pn_date.date_minus(p_ngay_Thang,p_Ngay_Moc,'MF');
		so_ngay:=pn_date.date_minus(p_ngay_Thang,p_Ngay_Moc,'D');
 	end if;
 else -- Neu khong co ngay
 	if p_thang=0 then
	 	so_thang:=(to_number(to_char(p_Ngay_Moc,'yyyy'))-p_nam)*12;
	 	so_ngay:=0;
 	else
		p_ngay_thang:=to_date('15/'||to_Char(p_thang)||'/'||to_Char(p_nam),'DD/MM/YYYY');
		so_thang:=pn_date.date_minus(p_ngay_Thang,p_Ngay_Moc,'MF');
		so_ngay:=pn_date.date_minus(p_ngay_Thang,p_Ngay_Moc,'D');
 	end if;
 end if;

  if upper(FM)='DD' then -- so ngay le cua tuoi
  	return nvl(SO_NGAY,0);
  elsif upper(FM)='MM' then
  	return nvl(SO_THANG,0); -- so thang tuoi
  elsif upper(FM)='MD' then -- Tong so ngay tuoi
  	return nvl(SO_THANG,0)*30+nvl(SO_ngay,0);
  end if;
 return 0;
End;  --- of GET_DO_TUOI



/************ Get_DO_TUOI_VTN function *********************
 Function: Tinh ?? tu?i ph?m nhan va ng??i khac
*/
Function Get_Do_Tuoi_VTN(Ngay_Sinh number,Thang_Sinh number,Nam_Sinh number,Ngay_Moc date,FM varchar2 default 'MD') RETURN number IS
so_thang number(10):=0;
so_ngay number(10):=0;
p_ngay number(4);
p_thang number(4);

p_Ngay_Thang date;
Begin
 if nvl(ngay_sinh,0)=0 then 	-- Neu ngay sinh trong
 	if nvl(thang_sinh,0)=0 then -- Neu khong co thang sinh thi =31/12 hang nam
 		p_ngay:=31;
 		p_thang:=12;
 	else  -- Neu co thang thi lay ngay cuoi cung cua thang
 		--p_ngay:=lastday('15/'||to_Char(Thang_Sinh)||'/'||to_Char(Nam_Sinh),'DD/MM/YYYY'));
 		p_ngay:=to_char(last_day(to_date('15/'||to_Char(thang_sinh)||'/'||to_Char(Nam_Sinh),'DD/MM/YYYY')),'dd');
 		p_thang:=thang_sinh;
 	end if;
 else -- Neu ngay sinh khong trong
 	if nvl(thang_sinh,0)=0 then -- Neu thang sinh cung trong thi
 		p_ngay:=31;
 		p_thang:=12;
 	else
 		p_ngay:=ngay_sinh;
 		p_thang:=thang_sinh;
 	end if;
 end if;

 	p_ngay_thang:=to_date(to_Char(p_ngay)||'/'||to_Char(p_thang)||'/'||to_Char(Nam_Sinh),'DD/MM/YYYY');
	so_thang:=pn_date.date_minus(p_ngay_Thang,Ngay_Moc,'MF');
	so_ngay:=pn_date.date_minus(p_ngay_Thang,Ngay_Moc,'D');

  if upper(FM)='DD' then -- so ngay le cua tuoi
  	return nvl(SO_NGAY,0);
  elsif upper(FM)='MM' then
  	return nvl(SO_THANG,0); -- so thang tuoi
  elsif upper(FM)='MD' then -- tong so ngay tuoi
  	return nvl(SO_THANG,0)*30+nvl(SO_ngay,0);
  end if;
 return 0;
 End;  --- of GET_DO_TUOI_VTN

