FUNCTION get_nd_from_ma_cq_dp(p_ma varchar2) RETURN varchar2 IS
p_ma_cq varchar2(7);
p_ma_dp varchar2(7);
p_ketqua varchar2(100);
BEGIN
  if p_ma is null then return null;end if;
  if p_ma='-' then return null;end if;
  p_ma_cq:=substr(p_ma,1,instr(p_ma,'-')-1);
  p_ma_dp:=substr(p_ma,instr(p_ma,'-')+1);
  if nvl(p_ma_dp,'99998')='99998' then
  	p_ketqua:=u_count_mas('ma_cq',p_ma_cq);
  else
  	p_ketqua:=u_count_mas('ma_cq',p_ma_cq)||' '||u_count_mas('ma_dp',p_ma_dp);
  end if;
  p_ketqua:=replace(p_ketqua,'Toa an nhan dan','TAND');
  p_ketqua:=replace(p_ketqua,'Vi?n ki?m sat nhan dan','VKSND');
  p_ketqua:=replace(p_ketqua,'Cong an','CA');
  p_ketqua:=replace(p_ketqua,'T?nh','t?nh');
  p_ketqua:=replace(p_ketqua,'Thanh ph?','TP');
  return p_ketqua;
END;

