  CREATE OR REPLACE EDITIONABLE PACKAGE BODY "QLPN_SUOI_HAI"."PN_TDL" IS
/*=========================================*/
 procedure lai_lich(dblink varchar2) is
    TYPE CsrType  IS REF CURSOR;
    v_csr    CsrType;
    csr pn_lai_lich%rowtype;
    csr_str VARCHAR2(200);
 begin
    csr_str:='select * from pn_lai_lich@'||dblink||' minus select * from pn_lai_lich';
    OPEN v_csr FOR csr_str;
    loop
      fetch v_csr into csr;
      EXIT WHEN v_csr%NOTFOUND;
      begin
        insert into pn_lai_lich values csr;
      exception
        when dup_val_on_index then
        update pn_lai_lich b set row = csr where pn_id=csr.pn_id;
      end;
      commit;
    end loop;
 end;
/*=========================================*/
 procedure sub_tab(tabname varchar2, dblink varchar2) is
    TYPE CsrType  IS REF CURSOR;
    v_csr    CsrType;
    v_pn_id varchar2(20);
    csr_str VARCHAR2(200);
 begin
    csr_str:='select distinct pn_id from (select * from '||tabname||'@'||dblink||' minus select * from '||tabname||')';
    --csr_str:='select distinct pn_id from '||tabname||'@'||dblink;
    OPEN v_csr FOR csr_str;
    loop
      fetch v_csr into v_pn_id;
      EXIT WHEN v_csr%NOTFOUND;
      begin
        EXECUTE IMMEDIATE 'Delete '||tabname||' where pn_id = :x'  USING v_pn_id;
        EXECUTE IMMEDIATE 'insert into '||tabname||' select * from '||tabname||'@'||dblink||
                          ' where pn_id = :x'  USING v_pn_id;
      end;
      commit;
    end loop;
 end;
/*=========================================*/
 procedure sub_sub_tab(tabname varchar2, dblink varchar2, colname varchar2) is
    TYPE CsrType  IS REF CURSOR;
    v_csr    CsrType;
    v_col_id varchar2(20);
    csr_str VARCHAR2(200);
 begin
    csr_str:='select distinct '||colname||' from (select * from '||tabname||'@'||dblink||' minus select * from '||tabname||')';
    --csr_str:='select distinct pn_id from '||tabname||'@'||dblink;
    OPEN v_csr FOR csr_str;
    loop
      fetch v_csr into v_col_id;
      EXIT WHEN v_csr%NOTFOUND;
      begin
        EXECUTE IMMEDIATE 'Delete '||tabname||' where '||colname||' = :x'  USING v_col_id;
        EXECUTE IMMEDIATE 'insert into '||tabname||' select * from '||tabname||'@'||dblink||
                          ' where '||colname||' = :x'  USING v_col_id;
      end;
      commit;
    end loop;
 end;
/*=========================================*/
procedure all_tab(dblink varchar2) is
Begin
  lai_lich(dblink);
  sub_tab('PN_BAN_AN',dblink);
  sub_tab('PN_CAI_TAO_KEM',dblink);
  sub_tab('PN_CHUA_BENH_BAT_BUOC',dblink);
  sub_tab('PN_CHUYEN_TRAI',dblink);
  sub_tab('PN_CON_PHAM_NHAN',dblink);
