 procedure lai_lich(dblink varchar2) is
    TYPE CsrType  IS REF CURSOR;
    v_csr    CsrType;
    csr pn_lai_lich%rowtype;
    csr_str VARCHAR2(200);
 begin
    csr_str:='select * from pn_lai_lich@'||dblink||' where pn_id in (select pn_id from v_tong_hop_dx@'||dblink||')';
    OPEN v_csr FOR csr_str;
    loop
      fetch v_csr into csr;
      EXIT WHEN v_csr%NOTFOUND;
