  CREATE OR REPLACE EDITIONABLE PACKAGE BODY "QLPN_SUOI_HAI"."SORT_X" IS
  function sort(cSohsld varchar2,cCol varchar2,cType varchar2) return varchar2 is
  	cRet varchar2(200);
  begin
  	if instr(cCol,'HOTEN')>0 or instr(cCol,'HO_TEN')>0 then
  		execute immediate 'Select order_hoten('||cCol||') from tv_trai_vien where so_hsld='''||cSohsld||'''' into cRet;
  	else
  		execute immediate 'Select '||cCol||' from tv_trai_vien where so_hsld='''||cSohsld||'''' into cRet;
  	end if;
  	return cRet;
  end;
  function sort(cSohsld varchar2,cCol varchar2,cType number) return number is
  	cRet number;
  begin
  	execute immediate 'Select '||cCol||' from tv_trai_vien where so_hsld='''||cSohsld||'''' into cRet;
  	return cRet;
  end;
  function sort(cSohsld varchar2,cCol varchar2,cType date) return date is
    cRet date;
  begin
  	execute immediate 'Select '||cCol||' from tv_trai_vien where so_hsld='''||cSohsld||'''' into cRet;
  	return cRet;
  end;
END;

