Procedure sync_danh_muc(ten_dm varchar2) is
str varchar2(2000);
Begin
begin
 str:='update '||ten_dm||' t set nd=(select nd from '||ten_dm||'@v26 where ma=t.ma)';
 execute immediate str;
 exception
   when others then null;
end;
 str:='insert into '||ten_dm||'(ma,nd) select ma,nd from '||ten_dm||'@v26 '||
      'where ma in (select ma from '||ten_dm||'@v26 '||
                    'minus '||
                    'select ma from '||ten_dm||')';
 execute immediate str;
end;
------------
Procedure sync_all_danh_muc is
Begin
for dm in (select table_name from user_tables where table_name like 'MA_%')
loop
Begin
if dm.table_name not in ('MA_MUC_THOI_GIAN','MA_XEP_LOAI') then
if check_danh_muc(dm.table_name)>0 then
   sync_danh_muc(dm.table_name);
end if;
end if;
exception
    when dup_val_on_index then null;
    when others then
      display_error;
end;
end loop;
End;
--------------------------------
Procedure sync_ini_tab is
matrai varchar2(5);
Begin
for j in (select t.var_name,t.var_value,var_comment from ini_tab@v26 t)
 loop
 Begin
   update ini_tab set var_value=j.var_value where var_name=j.var_name;
   exception
   when no_data_found then null;
   when others then null;
 End;
 end loop;
 delete pn_default_values;
 insert into pn_default_values select * from pn_default_values@v26;
 update ini_tab set var_value=pn_sys.Get_Gia_Tri_Mac_Dinh('CAP_TREN') where var_name='CO_QUAN';
 update ini_tab set var_value=pn_sys.Get_Gia_Tri_Mac_Dinh('DON_VI') where var_name='DON_VI';
 update ini_tab set var_value=pn_sys.Get_Gia_Tri_Mac_Dinh('DIA_CHI') where var_name='DIA_CHI';
 update ini_tab set var_value=pn_sys.Get_Gia_Tri_Mac_Dinh('DD_BC') where var_name='DIA_DANH_BC';
 update ini_tab set var_value=pn_sys.Get_Gia_Tri_Mac_Dinh('TEN_TTP') where var_name='DP_TRAI_GIAM';
 matrai:=pn_sys.Get_Gia_Tri_Mac_Dinh('MA_DV');
 if length(matrai)>4 then
   matrai:=substr(matrai,2);
 end if;
 update ini_tab set var_value=matrai where var_name='MA_TRAI';
end;
-------------------------------
Procedure sync_all_data is
Begin
   delete_all_data;
   sync_all_danh_muc;
   sync_ini_tab;
   sync_pn_lai_lich;
   sync_pn_giam_an;
   sync_pn_chet;
   sync_pn_xlct;
   sync_pn_plgg;
   sync_pn_tien_an;
   sync_pn_hpbs;
   sync_pn_qhgd;
   sync_pn_con_pn;
   sync_pn_khen_thuong;
   sync_pn_ky_luat;
