    conv_ma_thoi_gian(ma_muc_tg_con_lai),
    nhan_xet_tg,
    conv_ma_thoi_gian(nvl(ma_muc_dn_giam_v26,ma_muc_dn_giam_tg)),
    ma_ld_v26_doi_muc_giam,
    nhan_xet_giam_v26,
    ngay_qd_giam,
    so_qd_giam,
    ma_cq_toa_qd_giam,
    ma_dp_toa_qd_giam,
    conv_ma_thoi_gian(ma_muc_qd_giam_toa_an),
    ma_ld_toa_doi_muc_giam,
    ngay_tha_giam_het_an,
    ghi_chu_gth,
    so_nam_cai_tao,
    kqct_phieu_giam,
    kqct_ds_giam
    from pn_giam_thoi_han@v26;
    count_convert_record('PN_GIAM_THOI_HAN');
exception
    when dup_val_on_index then null;
    when others then
      display_error;
end;
