Procedure sync_pn_trich_xuat is
begin
 insert into pn_tx_trich_xuat(
  ma_pn_tx,
  pn_id,
  so_lenh_tx,
  ngay_lenh_tx,
  so_cv_dn_tx,
  ngay_cv_dn_tx,
  ma_cq_dn_tx,
  ma_dp_dn_tx,
  ma_ly_do_tx,
  ly_do_tx,
  ma_muc_thoi_han_tx,
  tu_ngay_tx,
  ngay_tx,
  ngay_tra_lai,
  ghi_chu_tx,
  ma_trai_giam_ve,
  ma_cq_rl_tx,
  ma_dp_rl_tx,
  ma_cq_tx_ve,
  ma_dp_tx_ve)
 select ma_pn_tx,
  pn_id,
  so_lenh_tx,
  ngay_lenh_tx,
  so_cv_dn_tx,
  ngay_cv_dn_tx,
  ma_cq_dn_tx,
  ma_dp_dn_tx,
  ma_ly_do_tx,
  ly_do_tx,
  conv_ma_thoi_gian(ma_muc_thoi_han_tx),
  tu_ngay_tx,
  ngay_tx,
  ngay_tra_lai,
  ghi_chu_tx,
  ma_trai_giam_ve,
  ma_cq_rl_tx,
  ma_dp_rl_tx,
  ma_cq_tx_ve,
  ma_dp_tx_ve
 from pn_tx_trich_xuat@v26;
 -----
 insert into pn_tx_gia_han(
  ma_pn_tx,
  so_lenh_txgh,
  ngay_lenh_txgh,
  so_cv_dn_txgh,
  ngay_cv_dn_txgh,
  ma_muc_thoi_han_txgh,
  tu_ngay_txgh,
  ghi_chu_txgh)
 select ma_pn_tx,
  so_lenh_txgh,
  ngay_lenh_txgh,
  so_cv_dn_txgh,
  ngay_cv_dn_txgh,
  conv_ma_thoi_gian(ma_muc_thoi_han_txgh),
  tu_ngay_txgh,
  ghi_chu_txgh
 from pn_tx_gia_han@v26;
 -------------------
 for j in (
select
g.ma_pn_tx,
t.pn_id,
g.so_lenh_txgh,
g.ngay_lenh_txgh,
g.so_cv_dn_txgh,
g.ngay_cv_dn_txgh,
t.ma_cq_dn_tx,
t.ma_dp_dn_tx,
t.ma_ly_do_tx,
g.ma_muc_thoi_han_txgh,
g.tu_ngay_txgh,
g.ghi_chu_txgh,
t.ma_trai_giam_ve,
t.ma_cq_rl_tx,
t.ma_dp_rl_tx,
t.ma_cq_tx_ve,
t.ma_dp_tx_ve,
'2' ma_lenh_tx
from pn_tx_trich_xuat t, pn_tx_gia_han g
where t.ma_pn_tx=g.ma_pn_tx)
loop
begin
insert into pn_tx_trich_xuat
(ma_pn_tx,pn_id,so_lenh_tx,ngay_lenh_tx,so_cv_dn_tx,ngay_cv_dn_tx,ma_cq_dn_tx,ma_dp_dn_tx
,ma_ly_do_tx,ma_muc_thoi_han_tx,tu_ngay_tx,ghi_chu_tx,ma_trai_giam_ve,ma_cq_rl_tx,
ma_dp_rl_tx,ma_cq_tx_ve,ma_dp_tx_ve,ma_lenh_tx,ngay_tx)
values
(j.ma_pn_tx,j.pn_id,j.so_lenh_txgh,j.ngay_lenh_txgh,j.so_cv_dn_txgh,j.ngay_cv_dn_txgh,j.ma_cq_dn_tx,j.ma_dp_dn_tx
,j.ma_ly_do_tx,j.ma_muc_thoi_han_txgh,j.tu_ngay_txgh,j.ghi_chu_txgh,j.ma_trai_giam_ve,j.ma_cq_rl_tx,
j.ma_dp_rl_tx,j.ma_cq_tx_ve,j.ma_dp_tx_ve,j.ma_lenh_tx,j.tu_ngay_txgh);
exception
    when dup_val_on_index then null;
    when others then
      display_error;
end;
end loop;
count_convert_record('pn_tx_trich_xuat');
exception
    when dup_val_on_index then null;
    when others then
      display_error;
end;
