procedure sync_pn_tdc is
Begin
 insert into pn_tdc_tam_dinh_chi(
  ma_pn_tdc,
  pn_id,
  so_qd,
  ngay_qd,
  ma_cq_cua_toa,
  ma_dp_cua_toa,
  ma_ly_do_tdc,
  ly_do_tdc,
  ma_muc_thoi_han_tdc,
  tu_ngay,
  noi_ve_thon,
  noi_ve_xa,
  ma_dp_noi_ve,
  ngay_tdc,
  ngay_lai,
  ghi_chu_tdc)
 select ma_pn_tdc,
  pn_id,
  so_qd_tdc,
  ngay_qd_tdc,
  ma_cq_toa_qd_tdc,
  ma_dp_toa_qd_tdc,
  ma_ly_do_tdc,
  ly_do_tdc,
  conv_ma_thoi_gian(ma_muc_thoi_han_tdc),
  tu_ngay_tdc,
  noi_ve_thon,
  noi_ve_xa,
  ma_dp_noi_ve,
  ngay_tdc,
  ngay_lai,
  ghi_chu_tdc
 from pn_tdc_tam_dinh_chi@v26;
 ---------
 for j in (select
            g.ma_pn_tdcgh ma_pn_tdc,
            t.pn_id,
            g.so_qd_tdcgh so_qd,
            g.ngay_qd_tdcgh ngay_qd,
            t.ma_cq_cua_toa,
            t.ma_dp_cua_toa,
            g.ma_ly_do_tdcgh ma_ly_do_tdc,
            g.ma_muc_thoi_han_tdcgh ma_muc_thoi_han_tdc,
            g.tu_ngay_tdcgh tu_ngay,
            g.ghi_chu_tdcgh ghi_chu_tdc,
            '2' ma_lenh_tdc
         from pn_tdc_tam_dinh_chi t, pn_tdc_gia_han g where t.ma_pn_tdc=g.ma_pn_tdc)
  loop
  Begin
  insert into pn_tdc_tam_dinh_chi(
    ma_pn_tdc,
    pn_id,
    so_qd,
    ngay_qd,
    ma_cq_cua_toa,
    ma_dp_cua_toa,
    ma_ly_do_tdc,
    ma_muc_thoi_han_tdc,
    tu_ngay,
    ghi_chu_tdc,
    ma_lenh_tdc)
    values
    (j.ma_pn_tdc,
    j.pn_id,
    j.so_qd,
    j.ngay_qd,
    j.ma_cq_cua_toa,
    j.ma_dp_cua_toa,
    j.ma_ly_do_tdc,
    j.ma_muc_thoi_han_tdc,
    j.tu_ngay,
    j.ghi_chu_tdc,
    j.ma_lenh_tdc);
exception
    when dup_val_on_index then null;
    when others then
      display_error;
 end;
end loop;
 count_convert_record('pn_tdc_tam_dinh_chi');
exception
    when dup_val_on_index then null;
    when others then
      display_error;
end;
