Function check_danh_muc(ten_dm varchar2) return number is
 str varchar2(1000);
 cCount number(10);
Begin
 str:='select count(*) from (select ma from '||ten_dm||'@v26 minus select ma from '||ten_dm||')';
 execute immediate str into cCount;
 return cCount;
end;
----------------------
Procedure count_convert_record(tabname varchar2) is
   before_rec number;
   after_rec  number;
   sqltxt     varchar2(1000);
Begin
  sqltxt:='select count(*) from '||tabname||'@v26';
  execute immediate sqltxt into before_rec;
  sqltxt:='select count(*) from '||tabname;
  execute immediate sqltxt into after_rec;
  dbms_output.put_line('========================================');
  dbms_output.put_line(upper(tabname)||': Da chuyen doi: '||after_rec||'('||before_rec||') records');
End;
-----------------------
Procedure display_error is
  err_num NUMBER;
  err_msg VARCHAR2(500);
Begin
  err_num := SQLCODE;
  err_msg := SUBSTR(SQLERRM, 1, 100);
  dbms_output.put_line(err_num||' - '||err_msg);
end;
end;

