--------------------------------------------------------
--  DDL for Function CONVERT_ARAB
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN_SUOI_HAI"."CONVERT_ARAB" (so number) RETURN varchar2 IS
type strarr is table of varchar2(50);
tab1 strarr:=strarr('khong','m?t','hai','ba','b?n','nam','sau','b?y','tam','chin','m??i');
tab2 strarr:=strarr('','m?t','hai','ba','t?','lam','sau','b?y','tam','chin','m??i');
n number;
m number;
temp varchar(1000);
BEGIN
 n:=so;
 if n<0 then
 	 n:=-n;
 end if;
 if n<=10 then temp:=tab1(n+1)||' ';
 elsif n<20 then
   if n=15 then
       temp:=tab1(11)||' '||tab2(6)||' ';
   else
   	   temp:=tab1(11)||' '||tab1((n mod 10)+1)||' ';
   end if;
 elsif n<100 then
   temp:=tab1(trunc(n/10)+1)||' m??i '||tab2((n mod 10)+1)||' ';
 elsif n<1000 then
      temp:=tab1(trunc(n/100)+1)||' tram ';
      n:=n mod 100;
      if n>0 then
           if n<10 then
            if n=4 then
               temp:=temp||'linh '||tab2(5)||' ';
            else
               temp:=temp||'linh '||tab1(n+1)||' ';
            end if;
           elsif n<20 then
                temp:=temp||'m??i ';
                if n=15 then
                 temp:=temp||tab2(6)||' ';
                elsif n<>10 then
                 temp:=temp||tab1((n mod 10)+1)||' ';
           			end if;
           else
