--------------------------------------------------------
--  DDL for Function CONVERT_HOTEN
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN_SUOI_HAI"."CONVERT_HOTEN" (str varchar2) return varchar2 is
	strList    varchar2(1000):=str;
	i          number;
	j          number;
	pos        number;
	currstr    varchar2(1000);
	the_return varchar2(1000);
	TerminateChars varchar2(100):=' ,.;:-!()?"<>/';
	curChar   varchar2(4);
begin
 if strList is null then
 	return null;
 end if;
	for i in 1..length(strList) loop
			curChar:=substr(strList,i,1);
		if curChar in (' ',',','.',';',':','-','!','(',')','?','"','<','>','/')  then
			currstr:=substr(strList,1,i)||upper(substr(strList,i+1,1))||substr(strList,i+2);
			the_return:=initcap(currstr);
		else
			the_return:=initcap(strList);
		end if;
  end loop;
	 return the_return;
end;
		
		/*
		-- for j in 1..length(TerminateChars) loop
--	TermChar:=substr(TerminateChars,j,1);
TermChar:=' ';
	for i in 1..length(strList) loop
			pos:=instr(strList,TermChar);
		if pos>0  then
			currstr:=substr(strList,1,pos);
			currstr:=upper(substr(currstr,1,1))||substr(currstr,2);
			the_return:=the_return||currstr||'';
			strList:=ltrim(substr(strList,pos+1));
		end if;
  end loop;
-- end loop;
	return the_return;
