--  DDL for Function CONVERT_NTOL
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN_SUOI_HAI"."CONVERT_NTOL" (vNumber number) Return varchar Is
Begin
  if vNumber=1 then return 'I'; end if;
  if vNumber=2 then return 'II'; end if;
  if vNumber=3 then return 'III'; end if;
  if vNumber=4 then return 'IV'; end if;
  if vNumber=5 then return 'V'; end if;
  if vNumber=6 then return 'VI'; end if;
  if vNumber=7 then return 'VII'; end if;
  if vNumber=8 then return 'VIII'; end if;
  if vNumber=9 then return 'IX'; end if;
  if vNumber=10 then return 'X'; end if;
  if vNumber=11 then return 'XI'; end if;
  if vNumber=12 then return 'XII'; end if;
  if vNumber=13 then return 'XIII'; end if;
  if vNumber=14 then return 'XIV'; end if;
  if vNumber=15 then return 'XV'; end if;
  if vNumber=16 then return 'XVI'; end if;
  if vNumber=17 then return 'XVII'; end if;
  if vNumber=18 then return 'XVIII'; end if;
  if vNumber=19 then return 'XIX'; end if;
  if vNumber=20 then return 'XX'; end if;
  if vNumber=0 then return '0'; end if;
  return '...';
End;

