--  DDL for Function CONV_MA_TG_GIAM
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN_SUOI_HAI"."CONV_MA_TG_GIAM" (vma varchar2) return varchar2 is
vRet varchar2(7);
Begin
if instr(vma,'@')=0 then
 return substr(vma,2);
else
 if substr(vma,3,1)='9' then
  return substr(vma,1,2)||substr(vma,3,6);
 else 
  return substr(vma,1,2)||substr(vma,4);
 end if;
end if;
exception
when no_data_found then return null;
end;

