--  DDL for Function COUNTCHAR
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN_SUOI_HAI"."COUNTCHAR" (str varchar2,s char) RETURN number IS
 cCount number:=0;
BEGIN
if str is not null then
 for i in 1..length(str) loop
 	if substr(str,i,1)=s then
 		cCount:=cCount+1;
 	end if;
 end loop;
 return cCount;
end if;
 return null;
END;

