  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN_SUOI_HAI"."F_PT80" (V_TU_NGAY DATE, V_DEN_NGAY DATE) RETURN T_PT80 AS
       TRET T_PT80;
       I NUMBER; TS_TMP NUMBER;
       TYPE COLVAL IS TABLE OF NUMBER(10) INDEX BY BINARY_INTEGER;
       COLV COLVAL;
BEGIN

  TRET:=T_PT80();
  -----TANG-----
  TRET.EXTEND;
  SELECT COUNT(*) INTO I FROM PN_LAI_LICH L WHERE pn_get.ma_tinh_trang(pn_id,V_TU_NGAY-1) in (111,112);
  COLV(1):=I;
  TRET(TRET.COUNT):=O_PT80(1,'S? thang tr??c chuy?n sang',I);
  -----* ----
  TRET.EXTEND;
  SELECT COUNT(*) INTO I FROM PN_LAI_LICH L WHERE L.MA_LOAI_DOI_TUONG in (110,120,20211,20212)
  AND L.NGAY_DEN_TRAI BETWEEN V_TU_NGAY AND V_DEN_NGAY;
  COLV(2):=I;
  TRET(TRET.COUNT):=O_PT80(2,'Tr?i t?m giam chuy?n d?n',I);
  -----*
    TRET.EXTEND;
  --SELECT COUNT(*) INTO I FROM (
  SELECT COUNT(*) INTO I FROM PN_LAI_LICH L WHERE L.MA_LOAI_DOI_TUONG='20221' AND L.NGAY_DEN_TRAI BETWEEN V_TU_NGAY AND V_DEN_NGAY;
    --union
    --SELECT PN_ID FROM PN_CHUYEN_TRAI CT WHERE CT.NGAY_TRO_LAI BETWEEN V_TU_NGAY AND V_DEN_NGAY);
  COLV(3):=I;
  TRET(TRET.COUNT):=O_PT80(3,'Tr?i giam khac chuy?n d?n',I);
  -----*
  TRET.EXTEND;
  SELECT COUNT(*) INTO I FROM PN_TT_TRON_TRAI T WHERE T.NGAY_BAT_LAI BETWEEN V_TU_NGAY AND V_DEN_NGAY
  and pn_id in (select pn_id from pn_lai_lich LL where to_date(T.ngay_tron)>=LL.ngay_den_trai);
  COLV(4):=I;
  TRET(TRET.COUNT):=O_PT80(4,'Tr?n b?t l?i',I);
  -----
  TRET.EXTEND;
  SELECT COUNT(*) INTO I FROM PN_TDC_TAM_DINH_CHI D WHERE D.NGAY_LAI BETWEEN V_TU_NGAY AND V_DEN_NGAY AND D.MA_LENH_TDC='1'
  and pn_id in (select pn_id from pn_lai_lich LL where d.ngay_tdc>LL.ngay_den_trai);
  COLV(5):=I;
  TRET(TRET.COUNT):=O_PT80(5,'T?m dinh ch? tr? l?i',I);
  -----*
  TRET.EXTEND;
  SELECT COUNT(*) INTO I FROM PN_TX_TRICH_XUAT X WHERE X.NGAY_TRA_LAI BETWEEN V_TU_NGAY AND V_DEN_NGAY AND X.MA_LENH_TX='1'
  and pn_id in (select pn_id from pn_lai_lich LL where x.ngay_tx>LL.ngay_den_trai);
  COLV(6):=I;
  TRET(TRET.COUNT):=O_PT80(6,'Trich xu?t tr? l?i',I);
  -----*
  TRET.EXTEND; -- Chuyen giao, tha_co_dk, BBCB,huy_an
  SELECT count(*) into TS_TMP FROM PN_LAI_LICH L WHERE L.MA_LOAI_DOI_TUONG in (20241,20231)
  AND L.NGAY_DEN_TRAI BETWEEN V_TU_NGAY AND V_DEN_NGAY;
  I:=TS_TMP;
  SELECT count(*) into TS_TMP FROM pn_huy_an WHERE ngay_lai BETWEEN V_TU_NGAY AND V_DEN_NGAY;
  I:=I+TS_TMP;
  SELECT count(*) into TS_TMP FROM pn_tha_co_dk WHERE ngay_tro_lai_trai BETWEEN V_TU_NGAY AND V_DEN_NGAY;
  I:=I+TS_TMP;
  Select count(*) into TS_TMP from pn_chua_benh_bat_buoc where ngay_ket_thuc BETWEEN V_TU_NGAY AND V_DEN_NGAY;
  I:=I+TS_TMP;
  COLV(7):=I;
  TRET(TRET.COUNT):=O_PT80(7,'Tang khac',I);
  -----*
  TRET.EXTEND;
  COLV(8):=COLV(2)+COLV(3)+COLV(4)+COLV(5)+COLV(6)+COLV(7);
  TRET(TRET.COUNT):=O_PT80(8,'C?ng',COLV(8));
  -----GIAM-----*
  TRET.EXTEND;
  SELECT COUNT(*) INTO I FROM (
    SELECT PN_ID FROM PN_LAI_LICH R WHERE R.NGAY_RA_TRAI BETWEEN V_TU_NGAY AND V_DEN_NGAY ---- dac xa, giam het, CHX, tha cdk
    MINUS (
    --SELECT PN_ID FROM PN_HUY_AN HU WHERE  HU.NGAY_TRA_TUDO BETWEEN V_TU_NGAY AND V_DEN_NGAY --B? vi H?y an ngay ra tr?i null
    --UNION
    --SELECT PN_ID FROM PN_HOAN_THI_HANH_AN HO WHERE HO.NGAY_HOAN BETWEEN V_TU_NGAY AND V_DEN_NGAY --B? vi Ho?n ngay ra tr?i null
    --UNION
