  COLV(9):=I;
  TRET(TRET.COUNT):=O_PT80(9,'Tha',I);
  -----*
  TRET.EXTEND;
  SELECT COUNT(*) INTO I FROM PN_TT_TRON_TRAI T WHERE to_date(T.NGAY_TRON) BETWEEN V_TU_NGAY AND V_DEN_NGAY
  and pn_id in (select pn_id from pn_lai_lich LL where to_date(T.ngay_tron)>=LL.ngay_den_trai);
  COLV(10):=I;
  TRET(TRET.COUNT):=O_PT80(10,'Tr?n',I);
  -----*
  TRET.EXTEND;
  SELECT COUNT(*) INTO I FROM PN_PNC_CHET C WHERE to_date(C.NGAY_CHET) BETWEEN V_TU_NGAY AND V_DEN_NGAY
  AND nvl(C.MA_TH_CHET,10) NOT IN (30,40,50);
  COLV(11):=I;
  TRET(TRET.COUNT):=O_PT80(11,'Ch?t',I);
  -----*
  TRET.EXTEND;
  SELECT COUNT(*) INTO I FROM PN_TX_TRICH_XUAT X WHERE X.NGAY_TX BETWEEN V_TU_NGAY AND V_DEN_NGAY AND X.MA_LENH_TX='1'
  and pn_id in (select pn_id from pn_lai_lich LL where x.ngay_tx>LL.ngay_den_trai);
  COLV(12):=I;
  TRET(TRET.COUNT):=O_PT80(12,'Trich xu?t',I);
  -----*
  TRET.EXTEND;
  SELECT COUNT(*) INTO I FROM PN_TDC_TAM_DINH_CHI D WHERE D.NGAY_TDC BETWEEN V_TU_NGAY AND V_DEN_NGAY AND D.MA_LENH_TDC='1'
  and pn_id in (select pn_id from pn_lai_lich LL where d.ngay_tdc>LL.ngay_den_trai);
