  COLV(14):=I;
  TRET(TRET.COUNT):=O_PT80(14,'Chuy?n tr?i',I);
  -----*
  TRET.EXTEND;
  SELECT COUNT(*) into TS_TMP FROM PN_HUY_AN HU WHERE HU.NGAY_TRA_TUDO BETWEEN V_TU_NGAY AND V_DEN_NGAY
  and pn_id not in
  (select pn_id from pn_tx_trich_xuat TX where TX.MA_LENH_TX='1' and (TX.ngay_tra_lai is null or TX.ngay_tra_lai>V_DEN_NGAY));
  I:=TS_TMP;
  SELECT COUNT(*) into TS_TMP FROM PN_HOAN_THI_HANH_AN HO WHERE HO.NGAY_HOAN BETWEEN V_TU_NGAY AND V_DEN_NGAY;
  I:=I+TS_TMP;
  SELECT COUNT(*) into TS_TMP FROM PN_MIEN_HINH_PHAT M WHERE M.NGAY_TRA_TU_DO BETWEEN V_TU_NGAY AND V_DEN_NGAY;
  I:=I+TS_TMP;
  Select count(*) into TS_TMP from pn_chua_benh_bat_buoc CB where CB.ngay_bat_dau BETWEEN V_TU_NGAY AND V_DEN_NGAY;
  I:=I+TS_TMP;
  Select count(*) into TS_TMP from pn_chuyen_giao CG where CG.ngay_chuyen_giao BETWEEN V_TU_NGAY AND V_DEN_NGAY
  and cg.ma_quoc_gia_cg<>250;
  I:=I+TS_TMP;
  COLV(15):=I;
  TRET(TRET.COUNT):=O_PT80(15,'Gi?m khac',I);
  -----*
  TRET.EXTEND;
  COLV(16):=COLV(9)+COLV(10)+COLV(11)+COLV(12)+COLV(13)+COLV(14)+COLV(15);
  TRET(TRET.COUNT):=O_PT80(16,'C?ng',COLV(16));
  -----*
  TRET.EXTEND;
