  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN_SUOI_HAI"."F_PT80_NU" (V_TU_NGAY DATE, V_DEN_NGAY DATE) RETURN T_PT80 AS
       TRET T_PT80;
       I NUMBER; TS_TMP NUMBER;
       TYPE COLVAL IS TABLE OF NUMBER(10) INDEX BY BINARY_INTEGER;
       COLV COLVAL;
BEGIN

  TRET:=T_PT80();
  -----TANG-----
  TRET.EXTEND;
  SELECT COUNT(*) INTO I FROM PN_LAI_LICH L WHERE pn_get.ma_tinh_trang(pn_id,V_TU_NGAY-1) like '11%'
  AND MA_GIOI_TINH=2;
  COLV(1):=I;
  TRET(TRET.COUNT):=O_PT80(1,'S? thang tr??c chuy?n sang',I);
  -----* ----
  TRET.EXTEND;
  SELECT COUNT(*) INTO I FROM PN_LAI_LICH L WHERE L.MA_LOAI_DOI_TUONG in (110,120,20211,20212)
  AND L.NGAY_DEN_TRAI BETWEEN V_TU_NGAY AND V_DEN_NGAY AND MA_GIOI_TINH=2;
  COLV(2):=I;
  TRET(TRET.COUNT):=O_PT80(2,'Tr?i t?m giam chuy?n d?n',I);
  -----*
    TRET.EXTEND;
  SELECT COUNT(*) INTO I FROM (
    SELECT PN_ID FROM PN_LAI_LICH L WHERE L.MA_LOAI_DOI_TUONG='20221'
    AND L.NGAY_DEN_TRAI BETWEEN V_TU_NGAY AND V_DEN_NGAY AND MA_GIOI_TINH=2
    union
    SELECT PN_ID FROM PN_CHUYEN_TRAI CT WHERE CT.NGAY_TRO_LAI BETWEEN V_TU_NGAY AND V_DEN_NGAY
    AND PN_ID IN (SELECT PN_ID FROM PN_LAI_LICH WHERE MA_GIOI_TINH=2));
  COLV(3):=I;
  TRET(TRET.COUNT):=O_PT80(3,'Tr?i giam khac chuy?n d?n',I);
  -----*
  TRET.EXTEND;
  SELECT COUNT(*) INTO I FROM PN_TT_TRON_TRAI T WHERE T.NGAY_BAT_LAI BETWEEN V_TU_NGAY AND V_DEN_NGAY
  and pn_id in (select pn_id from pn_lai_lich LL where to_date(T.ngay_tron)>=LL.ngay_den_trai AND MA_GIOI_TINH=2);
  COLV(4):=I;
  TRET(TRET.COUNT):=O_PT80(4,'Tr?n b?t l?i',I);
  -----
  TRET.EXTEND;
  SELECT COUNT(*) INTO I FROM PN_TDC_TAM_DINH_CHI D WHERE D.NGAY_LAI BETWEEN V_TU_NGAY AND V_DEN_NGAY AND D.MA_LENH_TDC='1'
  and pn_id in (select pn_id from pn_lai_lich LL where d.ngay_tdc>LL.ngay_den_trai AND MA_GIOI_TINH=2);
  COLV(5):=I;
  TRET(TRET.COUNT):=O_PT80(5,'T?m dinh ch? tr? l?i',I);
  -----*
  TRET.EXTEND;
  SELECT COUNT(*) INTO I FROM PN_TX_TRICH_XUAT X WHERE X.NGAY_TRA_LAI BETWEEN V_TU_NGAY AND V_DEN_NGAY AND X.MA_LENH_TX='1'
  and pn_id in (select pn_id from pn_lai_lich LL where x.ngay_tx>LL.ngay_den_trai AND MA_GIOI_TINH=2);
  COLV(6):=I;
  TRET(TRET.COUNT):=O_PT80(6,'Trich xu?t tr? l?i',I);
  -----*
  TRET.EXTEND;
  SELECT COUNT(*) INTO I FROM (
  SELECT PN_ID FROM PN_LAI_LICH L WHERE L.MA_LOAI_DOI_TUONG in (20241,20212,20231)
  AND L.NGAY_DEN_TRAI BETWEEN V_TU_NGAY AND V_DEN_NGAY AND MA_GIOI_TINH=2-- Chuyen giao, nha t?m gi? chuy?n d?n
  Union
  SELECT PN_ID FROM pn_tha_co_dk  WHERE ngay_tro_lai_trai BETWEEN V_TU_NGAY AND V_DEN_NGAY
  AND PN_ID IN (SELECT PN_ID FROM PN_LAI_LICH WHERE MA_GIOI_TINH=2));
  COLV(7):=I;
  TRET(TRET.COUNT):=O_PT80(7,'Tang khac',I);
  -----*
  TRET.EXTEND;
  COLV(8):=COLV(2)+COLV(3)+COLV(4)+COLV(5)+COLV(6)+COLV(7);
  TRET(TRET.COUNT):=O_PT80(8,'C?ng',COLV(8));
  -----GIAM-----*
  TRET.EXTEND;
  SELECT COUNT(*) INTO I FROM (
    SELECT PN_ID FROM PN_LAI_LICH R WHERE R.NGAY_RA_TRAI BETWEEN V_TU_NGAY AND V_DEN_NGAY AND MA_GIOI_TINH=2---- dac xa, giam het, CHX, tha cdk
    MINUS (
    SELECT PN_ID FROM PN_MIEN_HINH_PHAT M WHERE M.NGAY_TRA_TU_DO BETWEEN V_TU_NGAY AND V_DEN_NGAY
    Union
    Select PN_ID from pn_chua_benh_bat_buoc CB where CB.ngay_ket_thuc is null or CB.ngay_ket_thuc>V_DEN_NGAY
    Union
    Select PN_ID from pn_tx_trich_xuat TX where TX.MA_LENH_TX='1' and (TX.ngay_tra_lai is null or TX.ngay_tra_lai>V_DEN_NGAY)));
  COLV(9):=I;
  TRET(TRET.COUNT):=O_PT80(9,'Tha',I);
  -----*
  TRET.EXTEND;
  SELECT COUNT(*) INTO I FROM PN_TT_TRON_TRAI T WHERE to_date(T.NGAY_TRON) BETWEEN V_TU_NGAY AND V_DEN_NGAY
  and pn_id in (select pn_id from pn_lai_lich LL where to_date(T.ngay_tron)>=LL.ngay_den_trai AND MA_GIOI_TINH=2);
  COLV(10):=I;
  TRET(TRET.COUNT):=O_PT80(10,'Tr?n',I);
  -----*
  TRET.EXTEND;
  SELECT COUNT(*) INTO I FROM PN_PNC_CHET C WHERE to_date(C.NGAY_CHET) BETWEEN V_TU_NGAY AND V_DEN_NGAY
  AND nvl(C.MA_TH_CHET,10) NOT IN (30,40,50) AND PN_ID IN (SELECT PN_ID FROM PN_LAI_LICH WHERE MA_GIOI_TINH=2);
  COLV(11):=I;
  TRET(TRET.COUNT):=O_PT80(11,'Ch?t',I);
  -----*
  TRET.EXTEND;
  SELECT COUNT(*) INTO I FROM PN_TX_TRICH_XUAT X WHERE X.NGAY_TX BETWEEN V_TU_NGAY AND V_DEN_NGAY AND X.MA_LENH_TX='1'
  and pn_id in (select pn_id from pn_lai_lich LL where x.ngay_tx>LL.ngay_den_trai AND MA_GIOI_TINH=2);
  COLV(12):=I;
  TRET(TRET.COUNT):=O_PT80(12,'Trich xu?t',I);
  -----*
  TRET.EXTEND;
  SELECT COUNT(*) INTO I FROM PN_TDC_TAM_DINH_CHI D WHERE D.NGAY_TDC BETWEEN V_TU_NGAY AND V_DEN_NGAY AND D.MA_LENH_TDC='1'
  and pn_id in (select pn_id from pn_lai_lich LL where d.ngay_tdc>LL.ngay_den_trai AND MA_GIOI_TINH=2);
  COLV(13):=I;
  TRET(TRET.COUNT):=O_PT80(13,'T?m dinh ch?',I);
  -----*
  TRET.EXTEND;
  SELECT COUNT(*) INTO I FROM PN_CHUYEN_TRAI CT WHERE CT.NGAY_CHUYEN BETWEEN V_TU_NGAY AND V_DEN_NGAY
