  TRET(TRET.COUNT):=O_PT80(18,'N?',I);
  -----*
  TRET.EXTEND;
  SELECT COUNT(*) INTO I FROM TK_PT80 LL WHERE MA_GIOI_TINH='3';
  COLV(19):=I;
  TRET(TRET.COUNT):=O_PT80(19,'Gi?i tinh khac',I);
  -----*
  TRET.EXTEND;
  SELECT COUNT(*) INTO I FROM TK_PT80;
  COLV(20):=I;
  TRET(TRET.COUNT):=O_PT80(20,'C?ng',I);
  -----*
  TRET.EXTEND;
  SELECT COUNT(*) INTO I FROM TK_PT80 LL WHERE getstr(ma_toi_danh,1) in (select ma from ma_toi_danh where chuong_2015=13);
