--------------------------------------------------------
--  DDL for Function GETSTR
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN_SUOI_HAI"."GETSTR" (str varchar2,pos number) RETURN varchar2 IS
 cCount number:=0;
 Result varchar2(1000);
 s      varchar2(2000):=str||';';
begin
	 	if pos>0 then
		 if instr(s,';',1,pos)>0 then
		 	if pos>1 then
		 		s:=substr(s,instr(s,';',1,pos-1)+1,instr(s,';',1,pos)-instr(s,';',1,pos-1)-1);
		 	else
		 		s:=substr(s,1,instr(s,';')-1);
		 	end if;
		 		return s;
		 	end if;
		end if;
	 return null;
end;

/
--------------------------------------------------------
--  DDL for Function GETSTR_SPACE
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN_SUOI_HAI"."GETSTR_SPACE" (vstr varchar2) RETURN varchar2 IS
 str varchar2(2000);
begin
 if substr(vstr,1,1) is null or substr(vstr,1,1) like ' ' then
   str:=substr(vstr,2);
 else
   str:=vstr;
 end if;
 return str;
end;

