end;


/
--------------------------------------------------------
--  DDL for Function GET_DEN_NGAY
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN_SUOI_HAI"."GET_DEN_NGAY" (v_tu_ngay date,v_thoi_han varchar2) Return date is
v_nam   number;
v_thang number;
v_ngay  number;
v_den_ngay date;
Begin
  select ngay,thang,nam into v_ngay,v_thang,v_nam from ma_muc_thoi_gian where ma=v_thoi_han;
  if v_ngay is not null and v_thang is not null and v_nam is not null then
  	v_den_ngay:=add_months(v_tu_ngay,v_nam*12+v_thang)+v_ngay;
  	return v_den_ngay;
  else
  	return null;
  end if;
end;


/
--------------------------------------------------------
--  DDL for Function GET_DIA_CHI
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN_SUOI_HAI"."GET_DIA_CHI" (str1 varchar2,str2 varchar2,str3 varchar2) return varchar2 Deterministic is
str varchar2(1000);
begin
	str:=nvl(str1,'@')||', '||nvl(str2,'@')||', '||nvl(str3,'@');
	str:=replace(str,'@,','');
	str:=replace(str,', @','');
	str:=replace(str,'  ',' ');
	return ltrim(rtrim(str));
end;


