--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN_SUOI_HAI"."GET_DIEU_KIEN_GTH" (v_ngay_xet date) Return varchar2 is
strSQL 			  varchar2(3000);
dkQuy  				varchar2(100);
dk6Thang  		varchar2(100);
dkNam  				varchar2(100);
vNam					number:=to_char(v_ngay_xet,'yyyy');
dkXL          varchar2(100):=' in (110,120)';
Nam_1					varchar2(1000);
Nam_2					varchar2(1000);
Nam_3					varchar2(1000);
Nam_4					varchar2(1000);
tabAlias			varchar2(100);
Function Trans_SQL(Str varchar2) return varchar2 is
vStr varchar2(4000);
vAlias varchar2(100);
begin
		if instr(str,'[NamXL-1]')>0 and instr(dkNam,'[NamXL]')>0  then
			vAlias:='c';
		else
			vAlias:='a';
		end if;
		vStr:=str;
	  vStr:=replace(vStr,'[NamXL]','a.nam_xl='||vNam||' and a.');
		 vStr:=replace(vStr,'[NamXL-1]',vAlias||'.nam_xl+1='||vNam||' and '||vAlias||'.');
	  vStr:=replace(vStr,'[Q1]','ma_xep_loai_q1'||dkXL);            VStr:=replace(vStr,'[Q2]','ma_xep_loai_q2'||dkXL);
	  vStr:=replace(vStr,'[Q3]','ma_xep_loai_q3'||dkXL);            vStr:=replace(vStr,'[Q4]','ma_xep_loai_q4'||dkXL);
	  vStr:=replace(vStr,'[6thangdau]','ma_xep_loai_dau'||dkXL);    vStr:=replace(vStr,'[canam]','ma_xep_loai_ca'||dkXL);
	  vStr:=replace(vStr,'[6thangcuoi]','ma_xep_loai_cuoi'||dkXL);
	  vStr:=replace(vStr,':',' and ');
		if instr(str,'[NamXL-1]')>0 and instr(str,'[NamXL]')>0 and instr(str,':')>0 then
		  vStr:='select a.pn_id from pn_ket_qua_cai_tao a,pn_lai_lich b,pn_ket_qua_cai_tao c where a.pn_id=b.pn_id and b.pn_id=c.pn_id and ma_tinh_trang like ''11%'''||
			  ' and get_thang(pn_get.ma_tg_chap_hanh(a.pn_id,'''||v_ngay_xet||'''))>=(get_thang(ma_muc_an_phat)/3)+nvl(so_tien_an,0)*6 ' ||' and '||vStr||'';
		else
		  vStr:='select a.pn_id from pn_ket_qua_cai_tao a,pn_lai_lich b where a.pn_id=b.pn_id and ma_tinh_trang like ''11%'''||
			  ' and get_thang(pn_get.ma_tg_chap_hanh(a.pn_id,'''||v_ngay_xet||'''))>=(get_thang(ma_muc_an_phat)/3)+nvl(so_tien_an,0)*6 ' ||' and '||vStr||'';
		end if;
  return Vstr;
end;
Begin
	Select dk_quy,dk_6thang,dk_nam into dkQuy,dk6thang,dkNam from ma_dk_gth where thang=to_number(to_char(v_ngay_xet,'mm'));
  strSQL:=Trans_SQL(dkQuy)||' and get_thang(ma_muc_an_phat)<=3*12'||chr(10)||'union all'||chr(10)||Trans_SQL(dk6Thang)||' and get_thang(ma_muc_an_phat) between 4*12 and 5*12';
	if instr(dkNam,'[NamXL-1]')>0 and instr(dkNam,'[NamXL]')>0  then
		tabAlias:='c';
	else
		tabAlias:='a';
	end if;
	Nam_1:='and '||tabAlias||'.nam_xl = '||to_char(vNam-1)||' and '||tabAlias||'.ma_xep_loai_ca'||dkXL;
	Nam_2:='and '||tabAlias||'.nam_xl between '||to_char(vNam-2)||' and '||to_char(vNam-1)||' and '||tabAlias||'.ma_xep_loai_ca'||dkXL;
	Nam_3:='and '||tabAlias||'.nam_xl between '||to_char(vNam-3)||' and '||to_char(vNam-1)||' and '||tabAlias||'.ma_xep_loai_ca'||dkXL;
	Nam_4:='and '||tabAlias||'.nam_xl between '||to_char(vNam-4)||' and '||to_char(vNam-1)||' and '||tabAlias||'.ma_xep_loai_ca'||dkXL;
 	StrSQL:=StrSQL||chr(10)||'union all'||chr(10)||Trans_SQL(dkNam)||' and get_thang(ma_muc_an_phat) between 6*12 and 10*12 '|| Nam_1;
 	StrSQL:=StrSQL||chr(10)||'union all'||chr(10)||Trans_SQL(dkNam)||' and get_thang(ma_muc_an_phat) between 11*12 and 15*12 '|| Nam_2;
	StrSQL:=StrSQL||chr(10)||'union all'||chr(10)||Trans_SQL(dkNam)||' and get_thang(ma_muc_an_phat) between 16*12 and 30*12 '|| Nam_2;
	StrSQL:=StrSQL||chr(10)||'union all'||chr(10)||trans_SQL(dkNam)||' and ma_muc_an_phat=911000 '|| Nam_4;
 	strSQL:=replace(strSQL,'and  and','and');
  return strSQL;
End;


