/
--------------------------------------------------------
--  DDL for Function GET_DK_GTH_TG
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN_SUOI_HAI"."GET_DK_GTH_TG" (v_pn_id varchar2,v_ngay_xet date default sysdate)
return number is
vNgayBat date;
vAnPhat varchar2(10);
vDaCh   varchar2(10);
vNgayHetHan date;
cGth number(2):=0;
cGth1 number(2):=0;
vma_gcr varchar2(100);
dac_biet number:=0;
lastdate date;
Begin
select l.ngay_bat,l.ma_muc_an_phat,l.ma_ghi_chu_rieng,ngay_ra_trai
  into vNgayBat,vAnPhat,vma_gcr,vNgayHetHan from pn_lai_lich l where pn_id=v_pn_id;
--- L?y ngay xet gi?m cung d?t nam tr??c
select max(ngay_xet) into lastdate from pn_giam_thoi_han
       where ngay_xet between add_months(v_ngay_xet,-14) and add_months(v_ngay_xet,-9);
---
---
select count(*) into cGth from pn_giam_thoi_han where pn_id=v_pn_id and ngay_xet<v_ngay_xet;
IF cGth>0 THEN --- D? d??c gi?m
   select count(*) into cGth1 from pn_giam_thoi_han where pn_id=v_pn_id and ngay_xet between lastdate+1 and v_ngay_xet-1;
   If cGth1>0 then
      --- D?y d?t
      if vNgayHetHan between v_ngay_xet and v_ngay_xet+45 and add_months(lastdate,+7)<v_ngay_xet then
        return 12;
      else
        return -10; --- D? d??c gi?m 2 d?t g?n day
      end if;
   Else
      return 11;  --- D? d??c gi?m cung d?t nam tr??c => D? di?u ki?n
   End if;
ELSE --- Ch?a d??c gi?m l?n nao
  vDaCh:=pn_get.Ma_tg_chap_hanh(v_pn_id,v_ngay_xet);
---------------
 if substr(vma_gcr,1,2) in ('13','16','17','19')
    or vma_gcr like '%;13%'
     or vma_gcr like '%;16%'
      or vma_gcr like '%;17%'
       or vma_gcr like '%;19%' then
    dac_biet:=1;
 end if;
---------------
  If vAnPhat in ('911000','912000') then -- An phat chung than, tu hinh an giam xuong chung than
    If dac_biet=1 then
      if get_thang(vDaCh)>=10*12 then -- Thoi gian chap hanh it nhat la 10 nam
         Return 22; --- D? dk d?c bi?t
      else
         Return -10;
      end if;
    Else
      if get_thang(vDaCh)>=12*12 then -- Thoi gian chap hanh it nhat la 12 nam
         Return 21; --- D? dk th??ng
      else
         Return -10;
      end if;
    End If;
  Elsif vAnPhat < '911000' then
   If dac_biet=1 then
     if get_ngay(vDaCh)/get_ngay(vAnPhat)>=1/4 then -- Da chap hanh dung 1/4
       Return 22;
     else
       Return -10;
     end if;
   else
     if get_ngay(vDaCh)/get_ngay(vAnPhat)>=1/3 then -- Da chap hanh dung 1/3
       Return 21;
     else
       Return -10;
     end if;
   end if;
  End if;
  ---------
END IF;
 return 0;
End;

/
--------------------------------------------------------
--  DDL for Function GET_DK_GTH_XL
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN_SUOI_HAI"."GET_DK_GTH_XL" (vpn_id varchar2, vNgay_xet date)  return number is
 ma_muc_an varchar2(10);
 muc_an_thang number;
 ma_gcr varchar2(100);
 so_ta number:=0;
 dac_biet number:=0;
 so_ky number;
 so_ky_ut number;
 so_ky_ta number;
 loai_ky varchar2(3);
 so_ky_thuc number;
 so_ky_xl number;
 cGth number:=0;
 vNgayXetGth date;
Begin
select count(*),max(ngay_xet) into cGth,vNgayXetGth
       from pn_giam_thoi_han g
            where pn_id=vpn_id and g.ngay_xet<vngay_xet;
--==========================
-- Chua duoc giam lan nao --
--==========================
IF cGth=0 THEN
     select t.ma_muc_an_phat, nvl(t.so_tien_an,0), get_thang(t.ma_muc_an_phat), t.ma_ghi_chu_rieng
       into ma_muc_an,so_ta,muc_an_thang, ma_gcr
         from pn_lai_lich t,ma_muc_thoi_gian m
           where t.ma_muc_an_phat=m.ma and pn_id=vpn_id;
--------------
    if substr(ma_gcr,1,2) in ('13','16','17','19')
        or ma_gcr like '%;13%'
         or ma_gcr like '%;16%'
          or ma_gcr like '%;17%'
           or ma_gcr like '%;19%' then -- Khoan 2 Dieu 6
        dac_biet:=1;
     end if;
--------------
     if ma_muc_an='912000' then -- Tu hinh an giam xuong Chung than
        so_ky:=10; loai_ky:='K_'; so_ky_ut:=2; so_ky_ta:=1;
     elsif ma_muc_an='911000' then -- Chung than
        so_ky:=8; loai_ky:='K_'; so_ky_ut:=2; so_ky_ta:=1;
     elsif muc_an_thang between 20*12+0.01 and 30*12 then -- Tu tren 20N den 30N
        so_ky:=7; loai_ky:='K_'; so_ky_ut:=2; so_ky_ta:=1;
     elsif muc_an_thang between 15*12+0.01 and 20*12 then -- Tu tren 15N den 20N
        so_ky:=6; loai_ky:='K_'; so_ky_ut:=2; so_ky_ta:=1;

     elsif muc_an_thang between 10*12+0.01 and 15*12 then -- Tu tren 10N den 15N
        so_ky:=4; loai_ky:='K_'; so_ky_ut:=1; so_ky_ta:=1;
     elsif muc_an_thang between 5*12+0.01 and 10*12 then -- Tu tren 5N den 10N
        so_ky:=4; loai_ky:='Q_'; so_ky_ut:=2; so_ky_ta:=2;

     elsif muc_an_thang between 3*12+0.01 and 5*12 then -- Tu tren 3N den 5N
        so_ky:=2; loai_ky:='Q_'; so_ky_ut:=1; so_ky_ta:=2;
     elsif muc_an_thang<=3*12  then -- Tu 3N tro xuong
        so_ky:=1; loai_ky:='Q_'; so_ky_ut:=1; so_ky_ta:=1;
     end if;
 -------------------------------
    if dac_biet=1 then -- Khoan 2 Dieu 6
       so_ky:=so_ky-so_ky_ut;
    end if;
    so_ky:=so_ky+so_ta*so_ky_ta; -- Khoan 4 Dieu 6
 --------------------------------
 select count(decode(ma_xep_loai,'A',1,null)), count(*) into so_ky_thuc, so_ky_xl
    from (select *
        from (select * from V_PN_KQKT_DOC t
                            where pn_id=vpn_id
                             and t.KY_XL like loai_ky
                              and t.ngay_xl<vNgay_xet
                                order by ngay_xl desc)
        where rownum<=so_ky);
 --------------------------------
   If so_ky_thuc>=so_ky then
      if dac_biet=1 then
        return 12; -- Du dieu kien dac biet
      else
        return 11; -- Du dieu kien thuong
      end if;
   Else
      return -10; -- Khong du DK
   End if;
--==========================
-- DUOC GIAM LAN 2 TRO DI --
--==========================
ELSE
  so_ky:=2; -- So ky kha tinh t? lan giam xet truoc
  loai_ky:='Q_';
  select count(decode(ma_xep_loai,'A',1,null)) into so_ky_thuc
      from (select *
                from (select * from V_PN_KQKT_DOC t
                            where pn_id=vpn_id
                             and t.KY_XL like loai_ky
                              and t.ngay_xl between vNgayXetGth and vNgay_xet
                                order by ngay_xl desc)
                 where rownum<=so_ky);
   If so_ky_thuc>=so_ky then
      return 13; -- Du 4 quy gan nhat
   Else
      return -10; -- Khong du DK
   End if;

END IF;
End;

/
--------------------------------------------------------
--  DDL for Function GET_DK_KQCT_KEM
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN_SUOI_HAI"."GET_DK_KQCT_KEM" (v_pn_id varchar2) return number is
 countQ number;
 countK number;
 countC number;
 countAQ number;
 countAK number;
 countAC number;
 lastXL number;
 lastKL number;
Begin
 select count(decode(t.MA_XEP_LOAI,'A',1,null)), count(decode(t.MA_XEP_LOAI,'B',1,null)) into countAQ,countQ
   from v_pn_kqkt_doc t where pn_id=v_pn_id and ky_xl like 'Q_';
 --------------
 select count(decode(t.MA_XEP_LOAI,'A',1,null)), count(decode(t.MA_XEP_LOAI,'B',1,null)) into countAK,countK
   from v_pn_kqkt_doc t where pn_id=v_pn_id and ky_xl like 'K_';
 --------------
 select count(decode(t.MA_XEP_LOAI,'A',1,null)), count(decode(t.MA_XEP_LOAI,'B',1,null)) into countAC,countC
   from v_pn_kqkt_doc t where pn_id=v_pn_id and ky_xl like 'C_';
 ---------------
 select count(*) into lastXL from
(select * from (
select * from v_pn_kqkt_doc where pn_id=v_pn_id and ky_xl<>'Q3' order by nam_xl desc,tt desc)
where rownum<2) where ma_xep_loai='B';
 ---------------
 select count(*) into lastKL from pn_kl_ky_luat k, pn_lai_lich l
 where k.pn_id=v_pn_id and k.pn_id=l.pn_id
 and k.ngay_qd_kl>=add_months(l.ngay_ra_trai,-2) and to_number(k.ma_hinh_thuc_kl)>=200;
 ---------------
 if countC+countK+countQ>=countAC+countAK+countAQ and countAQ>0 then
   return 1; -- Tong cac ky kem> Tong cac ky kha
 elsif countC+countK>=countAC+countAK and countAC>0 then
   return 2; -- Tong ca nam kem>= Tong ca nam kha
 elsif countK+countQ>=countAK+countAQ and countAK>0 then
   return 3; -- Tong ky 6 thang kem >= Tong ky 6 thang kha
 elsif countQ>=countAQ and countAQ>0 then
   return 4; -- Tong Quy kem >= Tong Quy kha
 elsif lastXL>0 then
   return 5; -- Ky cuoi cung kem
 elsif lastKL>0 then
   return 6; -- Ky luat canh cao
 else
   return -1;
 end if;
exception
 when no_data_found then return -10;
 when others then return -10;
end;

/
--------------------------------------------------------
--  DDL for Function GET_DK_THA_CO_DK_TG
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN_SUOI_HAI"."GET_DK_THA_CO_DK_TG" (v_pn_id varchar2,v_ngay_xet date default sysdate)
return number is
vNgayBat date;
vAnPhat varchar2(10);
vDaCh   varchar2(10);
vma_gcr varchar2(100);
v_ngaysinh varchar2(100);
dac_biet number:=0;

BEGIN
select l.ngay_bat,l.ma_muc_an_phat,l.ma_ghi_chu_rieng,l.ngay_sinh_pn into vNgayBat,vAnPhat,vma_gcr,v_ngaysinh
from pn_lai_lich l where pn_id=v_pn_id and pn_get.ma_tinh_trang(v_pn_id,v_ngay_xet) in (111,141,142);
  vDaCh:=pn_get.Ma_tg_chap_hanh(v_pn_id,v_ngay_xet);
------------
if substr(vma_gcr,1,2) in ('24')
 or substr(vma_gcr,1,4) in ('2500','9925','1600','1601','1380','1381')
  or vma_gcr like '%;2500%' or vma_gcr like '%;9925%' or vma_gcr like '%;1600%'
   or vma_gcr like '%;1601%' or vma_gcr like '%;138%'
    or vma_gcr like '%;24%'
     or MONTHS_BETWEEN(v_ngay_xet,get_ngay_sinh(v_ngaysinh)) < 216 then
 dac_biet:=1;
end if;
------------
If vAnPhat in ('911000') then -- An phat chung than (tu hinh an giam khong xet)
    If dac_biet=1 then
      if get_thang(vDaCh)>=12*12 then -- Thoi gian chap hanh it nhat la 12 nam
         Return 12;
      else
         Return -10;
      end if;
    Else
      if get_thang(vDaCh)>=15*12 then -- Thoi gian chap hanh it nhat la 15 nam
         Return 11;
      else
         Return -10;
      end if;
    End If;
Elsif vAnPhat < '911000' then
   If dac_biet=1 then
     if get_ngay(vDaCh)/get_ngay(vAnPhat)>=1/3 then -- Da chap hanh it nhat 1/3
       Return 12;
     else
       Return -10;
     end if;
   else
   if get_ngay(vDaCh)/get_ngay(vAnPhat)>=1/2 then -- Da chap hanh dung 1/2
       Return 11;
    else
       Return -10;
     end if;
   end if;
End if;
---------
return -10;
END;

/
--------------------------------------------------------
--  DDL for Function GET_DK_THA_CO_DK_XL
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN_SUOI_HAI"."GET_DK_THA_CO_DK_XL" (vpn_id varchar2, vNgay_xet date)  return number is
 ma_muc_an varchar2(10);
 muc_an_thang number;
 ma_gcr varchar2(100);
 so_ta number:=0;
 dac_biet number:=0;
 v_ngaysinh varchar2(100);
 so_ky number;
 so_ky_ut number:=0;
 loai_ky varchar2(3);
 ------
 so_ky_thuc number;
 ------
 so_ky_xl number;

Begin

select t.ma_muc_an_phat,nvl(t.so_tien_an,0),get_thang(t.ma_muc_an_phat),t.ma_ghi_chu_rieng,t.ngay_sinh_pn
   into ma_muc_an,so_ta,muc_an_thang, ma_gcr, v_ngaysinh
      from pn_lai_lich t,ma_muc_thoi_gian m
         where t.ma_muc_an_phat=m.ma and pn_id=vpn_id;
-----------
if substr(ma_gcr,1,2) in ('24')
 or substr(ma_gcr,1,4) in ('2500','9925','1600','1601','1380','1381')
  or ma_gcr like '%;2500%' or ma_gcr like '%;9925%' or ma_gcr like '%;1600%'
   or ma_gcr like '%;1601%' or ma_gcr like '%;138%'
    or ma_gcr like '%;24%'
     or MONTHS_BETWEEN(vngay_xet,get_ngay_sinh(v_ngaysinh)) < 216 then
 dac_biet:=1;
end if;
------------
     if ma_muc_an in ('911000') then -- Chung than
        so_ky:=20; loai_ky:='Q_';
     elsif muc_an_thang between 20*12+0.01 and 30*12 then -- Tu tren 20N den 30N
        so_ky:=16; loai_ky:='Q_';
     elsif muc_an_thang between 15*12+0.01 and 20*12 then -- Tu tren 15N den 20N
        so_ky:=12; loai_ky:='Q_';
     elsif muc_an_thang between 10*12+0.01 and 15*12 then -- Tu tren 10N den 15N
        so_ky:=8; loai_ky:='Q_';
     elsif muc_an_thang between 5*12+0.01 and 10*12 then -- Tu tren 5N den 10N
        so_ky:=6; loai_ky:='Q_';
     elsif muc_an_thang between 3*12+0.01 and 5*12 then -- Tu tren 3N den 5N
        so_ky:=4; loai_ky:='Q_';
     elsif muc_an_thang <= 3*12 then -- Tu 3N tro xuong
        so_ky:=2; loai_ky:='Q_';
     end if;
 -------------------------------
 if dac_biet=1 then  -- Tru di so Quy doi voi Tinh tiet dac biet vcbvcb
    so_ky:=so_ky-so_ky_ut;
 end if;
 --------------------------------
 select count(decode(ma_xep_loai,'A',1,null)), count(*) into so_ky_thuc, so_ky_xl
      from (select *
           from (select * from V_PN_KQKT_DOC t
                            where pn_id=vpn_id
                             and t.KY_XL like loai_ky
                              and t.ngay_xl<vNgay_xet
                                order by ngay_xl desc)
         where rownum<=so_ky);
 --------------------------------
 If so_ky_thuc>=so_ky then
     return 10;       -- Du dieu kien xl
 else
     return -10;      -- Khong du dieu kien xl

 End if;

end;

