/
--------------------------------------------------------
--  DDL for Function GET_DOT_GIAM
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN_SUOI_HAI"."GET_DOT_GIAM" (v_pn_id varchar2) return varchar2 is
str     varchar2(2000);
cCount  number;
Begin
	Select count(*) into cCount from pn_giam_thoi_han where pn_id=v_pn_id and ngay_qd_giam is not null and ma_muc_qd_giam_toa_an is not null;
  for obj in (select ngay_qd_giam,ma_muc_qd_giam_toa_an from pn_giam_thoi_han where pn_id=v_pn_id and ngay_qd_giam is not null and ma_muc_qd_giam_toa_an is not null) loop
  	if cCount=1 then
  		str:=str||u_date(obj.ngay_qd_giam)||chr(10);
  	else
  		str:=str||'- '||u_date(obj.ngay_qd_giam)||': Gi?m '||countma('ma_muc_thoi_gian',obj.ma_muc_qd_giam_toa_an)||chr(10);
  	end if;
  end loop;
  return substr(str,1,length(str)-1);
  exception
  	when others then return null;
End;


/
--------------------------------------------------------
--  DDL for Function GET_DUMP
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN_SUOI_HAI"."GET_DUMP" return varchar2 is
	t varchar2(4000);
	str varchar2(4000);
begin
	str:='select dump(ho_ten) from pham_nhan@qlpn where rownum<2';
	--select dump(ho_ten) into t from pham_nhan@qlpn where rownum<2;
	--return t;
	execute immediate str into t;
	return t;
