  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN_SUOI_HAI"."GET_GN_ID" Return varchar2 is
v_id number;
Begin
  select max(to_number(substr(id_bb_gn,5))) into v_id from pn_bien_ban;
  v_id:=nvl(v_id,0)+1;
  Return to_char(sysdate,'yyyy')||lpad(v_id,8,'0');--para_ma_trai_giam||
End;

