--------------------------------------------------------
--  DDL for Function GET_HPBS_TONG_TIEN
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN_SUOI_HAI"."GET_HPBS_TONG_TIEN" (v_pn_id varchar2,v_ngay_nop date default null,v_type varchar2 default null) RETURN number IS -- <;>
v_tong 		number;
v_da_nop 	number;

BEGIN
  Select sum(nvl(tong_tien_phat,0)) into v_tong from pn_hpbs_hinh_phat where pn_id= v_pn_id;
	if v_ngay_nop is not null then
	begin
	if v_type='<' then
  	Select sum(nvl(so_tien_nop,0)) into v_da_nop from pn_hpbs_thuc_hien a,pn_hpbs_hinh_phat b  where a.ma_pn_hpbshp=b.ma_pn_hpbshp and b.pn_id= v_pn_id and ngay_nop<=v_ngay_nop;
	elsif v_type='>' then
  	Select sum(nvl(so_tien_nop,0)) into v_da_nop from pn_hpbs_thuc_hien a,pn_hpbs_hinh_phat b  where a.ma_pn_hpbshp=b.ma_pn_hpbshp and b.pn_id= v_pn_id and ngay_nop>v_ngay_nop;
	else
  	Select sum(nvl(so_tien_nop,0)) into v_da_nop from pn_hpbs_thuc_hien a,pn_hpbs_hinh_phat b  where a.ma_pn_hpbshp=b.ma_pn_hpbshp and b.pn_id= v_pn_id;
	end if;
	exception
		when no_data_found then v_da_nop:=0;
		when others then v_da_nop:=0;
  end;
	end if;
	return v_tong-v_da_nop;
	exception
		when no_data_found then v_tong:=0;
		when others then v_tong:=0;
  return v_tong;
END;

