 elsif ma_muc_an between '200001' and '300000' then -- Tu tren 20N den 30N
    so_ky:=7; loai_ky:='K_'; so_ky_ut:=2; so_ky_ta:=1; chia_ky:=2;
 elsif ma_muc_an between '150001' and '200000' then -- Tu tren 15N den 20N
