--  DDL for Function GET_KY_THA_CDK_XL
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN_SUOI_HAI"."GET_KY_THA_CDK_XL" (vpn_id varchar2, vNgay_xet date,loai number default 0)  return varchar2 is
 ma_muc_an varchar2(10);
 muc_an_thang number;
 ma_gcr varchar2(100);
 so_ta number:=0;
 so_ky number:=0;
 so_ky_ut number:=0;
 so_ky_ta number:=0;
 loai_ky varchar2(3);
 chia_ky number:=0;
 so_ky_thuc varchar2(2000);
 so_ky_thuc_dai varchar2(2000);
 ----
 -- Cac bien danh cho dot 02/09 hoac tet nguyen dan
 so_ky2 number:=0;
 --so_ky_ut2 number:=0;
 --so_ky_ta2 number:=0;
 loai_ky2 varchar2(3);
 chia_ky2 number:=0;
 so_ky_thuc2 varchar2(2000);
 so_ky_thuc_dai2 varchar2(2000);
 ----
 vnam_xl number;
 vNgayQDGth date;
 cGth number;
 vNgay_25_03 date:=to_date('25-MAR-'||to_char(vNgay_xet,'YYYY'),'DD-MON-YYYY');
 --vNgay_25_07 date:=to_date('25-JUL-'||to_char(vNgay_xet,'YYYY'),'DD-MON-YYYY');
 vNgay_25_12 date:=to_date('25-DEC-'||to_char(vNgay_xet,'YYYY'),'DD-MON-YYYY');
 vQuy_cuoi varchar2(200);
 vQuy_cuoi_dai varchar2(200);
Begin
select count(*),max(g.ngay_xet) into cGth,vNgayQDGth
       from pn_giam_thoi_han g
            where pn_id=vpn_id and g.ngay_qd_giam<vngay_xet;
--==========================
 select t.ma_muc_an_phat, nvl(t.so_tien_an,0), get_thang(t.ma_muc_an_phat), t.ma_ghi_chu_rieng
   into ma_muc_an,so_ta,muc_an_thang, ma_gcr
     from pn_lai_lich t
       where pn_id=vpn_id;
 -----
 if ma_muc_an in ('912000','911000') then -- Chung than
    so_ky:=20; loai_ky:='Q_'; so_ky_ut:=2; so_ky_ta:=1; chia_ky:=2;
 elsif muc_an_thang between 20*12+0.01 and 30*12 then -- Tu tren 20N den 30N
    so_ky:=16; loai_ky:='Q_'; so_ky_ut:=2; so_ky_ta:=1; chia_ky:=2;
 elsif muc_an_thang between 15*12+0.01 and 20*12 then -- Tu tren 15N den 20N
    so_ky:=12; loai_ky:='Q_'; so_ky_ut:=2; so_ky_ta:=1; chia_ky:=2;
 elsif muc_an_thang between 10*12+0.01 and 15*12 then -- Tu tren 10N den 15N
    so_ky:=8; loai_ky:='Q_'; so_ky_ut:=2; so_ky_ta:=2; chia_ky:=4;
 elsif muc_an_thang between 5*12+0.01 and 10*12 then -- Tu tren 5N den 10N
    so_ky:=6; loai_ky:='Q_'; so_ky_ut:=2; so_ky_ta:=2; chia_ky:=4;
 elsif muc_an_thang between 3*12+0.01 and 5*12 then -- Tu tren 3N den 5N
    so_ky:=4; loai_ky:='Q_'; so_ky_ut:=1; so_ky_ta:=2; chia_ky:=4;
 elsif muc_an_thang<=3*12 then -- Tu 3N tro xuong
    so_ky:=2; loai_ky:='Q_'; so_ky_ut:=1; so_ky_ta:=2; chia_ky:=4;
 end if;
 --------------------------------
 if so_ky=0 then so_ky:=1; end if;
   --if so_ky2=0 then so_ky2:=1; end if;
 --------------------------------
 -- Cong them Quy gan nhat neu lay ky xep loai 6 thang
 -- va ngay xet trong khoang le 30/4 va le 2/9
 --------------------------------

 if vNgay_xet=vNgay_25_03 and loai_ky='K_' then
   select chr(10)||to_char(nam_xl)||':Q1:'||countma('ma_xep_loai',ct.ma_xep_loai_q1),
          chr(10)||'+ Nam '||to_char(nam_xl)||': Quy I:'||countma('ma_xep_loai',ct.ma_xep_loai_q1)
   into vQuy_cuoi, vQuy_cuoi_dai
   from pn_ket_qua_cai_tao ct where pn_id=vpn_id and ct.nam_xl=to_char(vNgay_xet,'YYYY');
 elsif (loai_ky2='K_' or loai_ky='K_') and vNgay_xet=vNgay_25_12 then
   select ';Q3:'||countma('ma_xep_loai',ct.ma_xep_loai_q3),
   '; Quy III:'||countma('ma_xep_loai',ct.ma_xep_loai_q3)
   into vQuy_cuoi,vQuy_cuoi_dai
   from pn_ket_qua_cai_tao ct where pn_id=vpn_id and ct.nam_xl=to_char(vNgay_xet,'YYYY');
 end if;

 --------------------------------
    for j in (select * from (select *
           from (select t.nam_xl,t.xl,t.KY,t.KY_XEP_LOAI,t.xep_loai,t.ngay_xl from V_PN_KQKT_DOC t
                            where pn_id=vpn_id
                             and t.KY_XL like loai_ky
                              and t.ngay_xl<vNgay_xet and nam_xl>=to_number(to_char(vNgay_xet,'YYYY'))- round(so_ky/chia_ky+0.5)
                                order by ngay_xl desc)
         where rownum<=so_ky) order by ngay_xl
         )
    loop
     if vnam_xl<>j.nam_xl or vnam_xl is null then
      so_ky_thuc:=so_ky_thuc||chr(10)||j.nam_xl||': '||j.ky||': '||j.xl;
      so_ky_thuc_dai:=so_ky_thuc_dai||chr(10)||'+ Nam '||j.nam_xl||': '||j.ky_xep_loai||': '||j.xep_loai;
     else
      so_ky_thuc:=so_ky_thuc||';'||j.ky||':'||j.xl;
      so_ky_thuc_dai:=so_ky_thuc_dai||'; '||j.ky_xep_loai||': '||j.xep_loai;
     end if;
     vnam_xl:=j.nam_xl;
    end loop;
   ---
   vnam_xl:=null;
   if so_ky2 > 0 then
    for k in (select * from (select *
           from (select t.nam_xl,t.xl,t.KY,t.KY_XEP_LOAI,t.xep_loai,t.ngay_xl from V_PN_KQKT_DOC t
                            where pn_id=vpn_id
                             and t.KY_XL like loai_ky2
                              and t.ngay_xl<vNgay_xet and nam_xl>=to_number(to_char(vNgay_xet,'YYYY'))- round(so_ky2/chia_ky2+0.5)
                                order by ngay_xl desc)
         where rownum<=so_ky2) order by ngay_xl
         )
   loop
     if vnam_xl<>k.nam_xl or vnam_xl is null then
      so_ky_thuc2:=so_ky_thuc2||chr(10)||k.nam_xl||':'||k.ky||': '||k.xl;
      so_ky_thuc_dai2:=so_ky_thuc_dai2||chr(10)||'+ Nam '||k.nam_xl||': '||k.KY_XEP_LOAI||': '||k.xep_loai;
     else
      so_ky_thuc2:=so_ky_thuc2||';'||k.ky||':'||k.xl;
      so_ky_thuc_dai2:=so_ky_thuc_dai2||'; '||k.KY_XEP_LOAI||': '||k.xep_loai;
     end if;
     vnam_xl:=k.nam_xl;
   end loop;
 --------------------------------
  if loai=1 then
   return substr(so_ky_thuc_dai2,2)||vQuy_cuoi_dai;
  end if;
   return substr(so_ky_thuc2,2)||vQuy_cuoi;
 end if;
  if loai=1 then
   return substr(so_ky_thuc_dai,2)||vQuy_cuoi_dai;
  end if;
   return substr(so_ky_thuc,2)||vQuy_cuoi;

exception
     when others then return null;
end;

