--------------------------------------------------------
--  DDL for Function GET_KY_XL_KEM
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN_SUOI_HAI"."GET_KY_XL_KEM" (vpn_id varchar2, kq number default 0) return varchar2 is
 s_kqct varchar2(4000);
 n_kqct varchar2(200);
 n_kqct1 varchar2(200);
 n_kqct2 varchar2(200);
 soquykem number:=0;
 tgchkem varchar2(10);
Begin
for n in (select distinct nam_xl from v_pn_kqkt_doc t
                 where ma_xep_loai='B' and pn_id=vpn_id
                       order by nam_xl)
loop
n_kqct:='';
for j in (select * from v_xlct
                 where pn_id=vpn_id and nam_xl=n.nam_xl)
loop
  if j.ma_xep_loai_ca in ('130','140') then
    n_kqct:=' x?p lo?i '||j.xep_loai_ca||';';
    soquykem:=soquykem+4;
  else
    if j.ma_xep_loai_cuoi in ('130','140') then
       n_kqct2:=' 6 thang cu?i nam x?p lo?i '||j.xep_loai_cuoi||';';
       soquykem:=soquykem+2;
    else
       if j.ma_xep_loai_q3 in ('130','140') then
         n_kqct2:=' Quy III x?p lo?i '||j.xep_loai_q3||';';
         soquykem:=soquykem+1;
       end if;
       if j.ma_xep_loai_q3 in ('130','140') then
         n_kqct2:=n_kqct2||' Quy IV x?p lo?i '||j.xep_loai_q4||';';
         soquykem:=soquykem+1;
       end if;
    end if;
    if j.ma_xep_loai_dau in ('130','140') then
       n_kqct1:=' 6 thang d?u nam x?p lo?i '||j.xep_loai_dau||';';
       soquykem:=soquykem+2;
    else
       if j.ma_xep_loai_q1 in ('130','140') then
         n_kqct1:=' Quy I x?p lo?i '||j.xep_loai_q1||';';
         soquykem:=soquykem+1;
       end if;
       if j.ma_xep_loai_q2 in ('130','140') then
         n_kqct1:=n_kqct1||' Quy II x?p lo?i '||j.xep_loai_q2||';';
         soquykem:=soquykem+1;
       end if;
    end if;
    n_kqct:=n_kqct1||n_kqct2;
  end if;
end loop;
  s_kqct:=s_kqct||chr(10)||' Nam '||to_char(n.nam_xl)||n_kqct;
end loop;
tgchkem:=lpad(to_char(floor(soquykem/4)),2,'0')||lpad(to_char(mod(soquykem,4)*3),2,'0')||'00';
if kq=0 then
return substr(s_kqct,2);
end if;
 return tgchkem;
end;

/
--------------------------------------------------------
--  DDL for Function GET_LAP_HS_ID
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN_SUOI_HAI"."GET_LAP_HS_ID" Return varchar2 is
v_id number;
Begin
  select max(to_number(substr(id_bb_gn,5))) into v_id from pn_ho_so_nghiep_vu;
  v_id:=nvl(v_id,0)+1;
  Return to_char(sysdate,'yyyy')||lpad(v_id,8,'0');--para_ma_trai_giam||
End;

/
--------------------------------------------------------
--  DDL for Function GET_LAST_MA_PLGG
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN_SUOI_HAI"."GET_LAST_MA_PLGG" (v_pn_id varchar2,vngay_xet date default sysdate)  return varchar2 is
v_ma_pl varchar2(50);
begin
	select ma_den_loai into v_ma_pl
  from pn_phan_loai_giam_giu a
  where pn_id=v_pn_id
  and a.ngay_phan_loai =
    (select max(b.ngay_phan_loai)
         from pn_phan_loai_giam_giu b
            where b.pn_id=a.pn_id and b.ngay_phan_loai<vngay_xet);
     return v_ma_pl;
exception
	when no_data_found then return null;
	when others then return null;
end;

/
--------------------------------------------------------
--  DDL for Function GET_LAST_PLGG
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN_SUOI_HAI"."GET_LAST_PLGG" (v_pn_id varchar2,vngay_xet date default sysdate)  return varchar2 is
v_ma_pl varchar2(50);
begin
	select  to_char(ngay_phan_loai,'dd/mm/yyyy')||' - '||countma('ma_phan_loai_giam_giu',ma_den_loai) into v_ma_pl
  from pn_phan_loai_giam_giu a
  where pn_id=v_pn_id
  and a.ngay_phan_loai =
    (select max(b.ngay_phan_loai)
         from pn_phan_loai_giam_giu b
            where b.pn_id=a.pn_id and a.ngay_phan_loai<=vngay_xet);
     return v_ma_pl;
exception
	when no_data_found then return null;
	when others then return null;
end;

/
--------------------------------------------------------
--  DDL for Function GET_LAST_XLCT
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN_SUOI_HAI"."GET_LAST_XLCT" (v_pn_id varchar2, v_year number) Return varchar2 is
v_xlct varchar2(50);
cCount number;
Begin
select count(*) into cCount from pn_ket_qua_cai_tao where nam_xl=v_year and pn_id=v_pn_id;
if cCount>0 then
  for obj in (select a.ma_xep_loai_q1,a.ma_xep_loai_q2,a.ma_xep_loai_dau,a.ma_xep_loai_q3,a.ma_xep_loai_q4,a.ma_xep_loai_cuoi,a.ma_xep_loai_ca from pn_ket_qua_cai_tao a where nam_xl=v_year and pn_id=v_pn_id)
  loop
    if obj.ma_xep_loai_ca in ('110','120','130','140') then
       if obj.ma_xep_loai_ca in ('110','120') then
          return obj.ma_xep_loai_ca;
       elsif obj.ma_xep_loai_ca='130' then
          return '120';
       else
          return '130';
       end if;
    elsif obj.ma_xep_loai_cuoi in ('110','120','130','140') then
      if obj.ma_xep_loai_cuoi in ('110','120') then
          return obj.ma_xep_loai_cuoi;
       elsif obj.ma_xep_loai_cuoi='130' then
          return '120';
       else
          return '130';
       end if;
    elsif obj.ma_xep_loai_q4 in ('110','120','130','140') then
      if obj.ma_xep_loai_q4 in ('110','120') then
          return obj.ma_xep_loai_q4;
       elsif obj.ma_xep_loai_q4='130' then
          return '120';
       else
          return '130';
       end if;
    elsif obj.ma_xep_loai_q3 in ('110','120','130','140') then
      if obj.ma_xep_loai_q3 in ('110','120') then
          return obj.ma_xep_loai_q3;
       elsif obj.ma_xep_loai_q3='130' then
          return '120';
       else
          return '130';
       end if;
    elsif obj.ma_xep_loai_dau in ('110','120','130','140') then
