--------------------------------------------------------
--  DDL for Function GET_MULTI_CONDITION
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN_SUOI_HAI"."GET_MULTI_CONDITION" (dieukien varchar2, giatri varchar2, toantu varchar2) RETURN varchar2 IS
	vdk varchar2(4000):=dieukien||';';
	vgt varchar2(4000):=giatri||';';
	gt  varchar2(4000);
	dk	varchar2(4000);
	pos1 number;
	pos2 number;
	sReturn varchar2(4000):='';
BEGIN
  loop
  	pos1:=instr(vdk,';');
  	dk:=substr(vdk,1,pos1-1);
  	vgt:=giatri||';';
  	loop
  		pos2:=instr(vgt,';');
  		gt:=substr(vgt,1,pos2-1);
  		if gt is not null then
  		 	sReturn:=sReturn||' or '||dk||' '||toantu||' '''||gt||'''';
  		end if;
  		vgt:=substr(vgt,pos2+1);
  		exit when vgt is null;
  	end loop;
  	vdk:=substr(vdk,pos1+1);
  	exit when vdk is null;
  end loop;
  return substr(sReturn,5);
END;

/
--------------------------------------------------------
--  DDL for Function GET_NAM_SX
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN_SUOI_HAI"."GET_NAM_SX" (v_pn_id varchar2, xq1 out varchar2,tq1 out varchar2,xq2 out varchar2,tq2 out varchar2,
										xq3 out varchar2,tq3 out varchar2,xq4 out varchar2,tq4 out varchar2,tcn out varchar2, tongt out number) RETURN varchar2 IS
  namRet varchar2(1000);
  xq1Ret varchar2(1000);
  tq1Ret varchar2(1000);
  xq2Ret varchar2(1000);
  tq2Ret varchar2(1000);
  xq3Ret varchar2(1000);
  tq3Ret varchar2(1000);
  xq4Ret varchar2(1000);
  tq4Ret varchar2(1000);
  tcnRet varchar2(1000);
  tongtien number(10):=0;
BEGIN
  for c in (select pn_id, nam_sx, xl_q1, tien_q1, xl_q2, tien_q2, xl_q3, tien_q3, xl_q4, tien_q4, tien_cn
  						from v_tong_hop_tien_ldsx where pn_id=v_pn_id order by nam_sx)
  loop
			namRet:=namRet||'<br>'||c.nam_sx;
			xq1Ret:=xq1Ret||'<br>'||c.xl_q1;
			tq1Ret:=tq1Ret||'<br>'||c.tien_q1;
			xq2Ret:=xq2Ret||'<br>'||c.xl_q2;
			tq2Ret:=tq2Ret||'<br>'||c.tien_q2;
			xq3Ret:=xq3Ret||'<br>'||c.xl_q3;
			tq3Ret:=tq3Ret||'<br>'||c.tien_q3;
			xq4Ret:=xq4Ret||'<br>'||c.xl_q4;
			tq4Ret:=tq4Ret||'<br>'||c.tien_q4;
			tcnRet:=tcnRet||'<br>'||c.tien_cn;
			tongtien:=tongtien+nvl(c.tien_cn,0);
  end loop;
  xq1:=substr(xq1Ret,5);
  xq2:=substr(xq2Ret,5);
  xq3:=substr(xq3Ret,5);
  xq4:=substr(xq4Ret,5);

  tq1:=substr(tq1Ret,5);
  tq2:=substr(tq2Ret,5);
  tq3:=substr(tq3Ret,5);
  tq4:=substr(tq4Ret,5);
  tongt:=tongtien;
  tcn:=substr(tcnRet,5);

  return substr(namRet,5);
END;

/
--------------------------------------------------------
--  DDL for Function GET_NAM_XLCT
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN_SUOI_HAI"."GET_NAM_XLCT" (vpn_id varchar2, vNgay_xet date)  return number is
 ma_muc_an varchar2(10);
 muc_an_thang number;
 ma_gcr varchar2(100);
 cMucan number;
 so_ta number:=0;
 so_ky number:=0;
 so_ky_ut number:=0;
 so_ky_ta number:=0;
 loai_ky varchar2(3);
 chia_ky number:=0;
 so_ky_thuc varchar2(2000);
 so_ky_thuc_dai varchar2(2000);
 ----
 -- Cac bien danh cho dot 02/09 hoac tet nguyen dan
 so_ky2 number:=0;
 so_ky_ut2 number:=0;
 so_ky_ta2 number:=0;
 loai_ky2 varchar2(3);
 chia_ky2 number:=0;
 so_ky_thuc2 varchar2(2000);
 so_ky_thuc_dai2 varchar2(2000);
 ----
 vnam_xl number;
 vNgayQDGth date;
 cGth number;
 vNgay_30_04 date:=to_date('30-APR-'||to_char(vNgay_xet,'YYYY'),'DD-MON-YYYY');
 vNgay_25_08 date:=to_date('25-AUG-'||to_char(vNgay_xet,'YYYY'),'DD-MON-YYYY');
 vNgay_02_09 date:=to_date('02-SEP-'||to_char(vNgay_xet,'YYYY'),'DD-MON-YYYY');
 vQuy_cuoi varchar2(200);
 vQuy_cuoi_dai varchar2(200);
Begin
 select t.ma_muc_an_phat, nvl(t.so_tien_an,0), get_thang(t.ma_muc_an_phat), t.ma_ghi_chu_rieng
   into ma_muc_an,so_ta,muc_an_thang, ma_gcr
     from pn_lai_lich t
       where pn_id=vpn_id;
 -----
 if ma_muc_an='912000' then -- Tu hinh an giam xuong Chung than
    so_ky:=5*2; loai_ky:='K_'; so_ky_ut:=2; so_ky_ta:=1; chia_ky:=2;
 elsif ma_muc_an='911000' then -- Chung than
    so_ky:=4*2; loai_ky:='K_'; so_ky_ut:=2; so_ky_ta:=1; chia_ky:=2;
 elsif muc_an_thang between 20*12+0.01 and 30*12 then -- Tu tren 20N den 30N
    so_ky:=7; loai_ky:='K_'; so_ky_ut:=2; so_ky_ta:=1; chia_ky:=2;
 elsif muc_an_thang between 15*12+0.01 and 20*12 then -- Tu tren 15N den 20N
    so_ky:=6; loai_ky:='K_'; so_ky_ut:=2; so_ky_ta:=1; chia_ky:=2;
 elsif muc_an_thang between 10*12+0.01 and 15*12 then -- Tu tren 10N den 15N
    so_ky:=8; loai_ky:='Q_'; so_ky_ut:=2; so_ky_ta:=2; chia_ky:=4;
    if vNgay_xet>to_date('25-JUN-'||to_char(vNgay_xet,'YYYY'),'DD-MON-YYYY') then
       so_ky2:=4; loai_ky2:='K_'; so_ky_ut2:=1; so_ky_ta2:=1; chia_ky2:=2;
    end if;
 elsif muc_an_thang between 5*12+0.01 and 10*12 then -- Tu tren 5N den 10N
    so_ky:=4; loai_ky:='Q_'; so_ky_ut:=2; so_ky_ta:=2; chia_ky:=4;
    if vNgay_xet>to_date('25-JUN-'||to_char(vNgay_xet,'YYYY'),'DD-MON-YYYY') then
       so_ky2:=2; loai_ky2:='K_'; so_ky_ut2:=1; so_ky_ta2:=1; chia_ky2:=2;
    end if;
 elsif muc_an_thang between 3*12+0.01 and 5*12 then -- Tu tren 3N den 5N
    so_ky:=4; loai_ky:='Q_'; so_ky_ut:=0; so_ky_ta:=2; chia_ky:=4;
    if vNgay_xet>to_date('25-JUN-'||to_char(vNgay_xet,'YYYY'),'DD-MON-YYYY') then
       so_ky2:=2; loai_ky2:='K_'; so_ky_ut2:=0; so_ky_ta2:=1; chia_ky2:=2;
    end if;
 elsif muc_an_thang<=3*12  then -- Tu 3N tro xuong
    so_ky:=4; loai_ky:='Q_'; so_ky_ut:=0; so_ky_ta:=1; chia_ky:=4;
 end if;
 -------------------------------
 if substr(ma_gcr,1,2) in ('13','16','17','19')
    or ma_gcr like '%;13%'
     or ma_gcr like '%;16%'
      or ma_gcr like '%;17%'
       or ma_gcr like '%;19%' then -- Khoan 2 Dieu 6
    so_ky:=so_ky-so_ky_ut;
    so_ky2:=so_ky2-so_ky_ut2;
 end if;
 --------------------------------
   so_ky:=so_ky+so_ta*so_ky_ta; -- Khoan 4 Dieu 6
   so_ky2:=so_ky2+so_ta*so_ky_ta2;
   if so_ky=0 then so_ky:=1; end if;
 --------------------------------
   if so_ky2 > 0 then
    return to_number(to_char(vNgay_xet,'YYYY'))- round(so_ky2/chia_ky2);
   end if;
 ----------------------------------------
return to_number(to_char(vNgay_xet,'YYYY'))- round(so_ky/chia_ky);
end;

/
--------------------------------------------------------
--  DDL for Function GET_NANG_HA_PLGG
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN_SUOI_HAI"."GET_NANG_HA_PLGG" (v_pn_id varchar2,v_ma_loai_plgg varchar2,v_ngay_plgg date default sysdate) return varchar2 is
 ma_last_plgg varchar2(10);
 v_ma_plgg varchar2(10);
Begin
 ma_last_plgg:=get_last_ma_plgg(v_pn_id,v_ngay_plgg);
 if ma_last_plgg is not null then
   if v_ma_loai_plgg='2' then
     select max(ma) into v_ma_plgg from ma_phan_loai_giam_giu where ma<ma_last_plgg;
   elsif v_ma_loai_plgg='3' then
     select min(ma) into v_ma_plgg from ma_phan_loai_giam_giu where ma>ma_last_plgg;
   else
     v_ma_plgg:=ma_last_plgg;
   end if;
 end if;
 return v_ma_plgg;
exception
 when no_data_found then return null;
 when others then return null;
End;

