--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN_SUOI_HAI"."GET_NGAY_CHU" (v_date date, type_ngay varchar2 default 'T') Return varchar2 is
Begin
	if v_date is null then
		Return 'ngay .... thang .... nam ....';
	end if;
	if type_ngay='T' then
  	return 'ngay '||to_char(v_date,'dd')||' thang '||to_char(v_date,'mm')||' nam '||to_char(v_date,'yyyy');
	elsif type_ngay='H' then
  	return 'Ngay '||to_char(v_date,'dd')||' thang '||to_char(v_date,'mm')||' nam '||to_char(v_date,'yyyy');
	end if;
End;

/
--------------------------------------------------------
--  DDL for Function GET_NGAY_SINH
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN_SUOI_HAI"."GET_NGAY_SINH" (v_ngay_sinh varchar2 ) return date is
begin
  if length(v_ngay_sinh)=4 then
    return to_date('31/12/'||v_ngay_sinh,'dd/mm/yyyy');
  elsif length(v_ngay_sinh)=7 then
    return last_day(to_date('15/'||v_ngay_sinh,'dd/mm/yyyy'));
  elsif length(v_ngay_sinh)=10 then
    return to_date(v_ngay_sinh,'dd/mm/yyyy');
  else
    return to_date('31/12/'||substr(v_ngay_sinh,length(v_ngay_sinh)-3),'dd/mm/yyyy');
  end if;
  exception
    when others then
         return null;
end;

