/
--------------------------------------------------------
--  DDL for Function GET_PN_ID_TT
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN_SUOI_HAI"."GET_PN_ID_TT" (vDenngay date default sysdate)
  RETURN rec_tbl
IS
  l_pn_id rec_tbl;
BEGIN
  SELECT pn_id
    BULK COLLECT INTO l_pn_id
    FROM (select pn_id from v_pn_tinh_trang where ngay1<=vDenngay and (tinh_trang='Vao_TTG' or tinh_trang='Vao_TRG')
          minus
          select pn_id from v_pn_tinh_trang where ngay1<=vDenngay and tinh_trang='Ra'
          minus
          select pn_id from v_pn_tinh_trang where ngay1<=vDenngay and tinh_trang='Chet'
          minus
          select pn_id from v_pn_tinh_trang where ngay1<=vDenngay and ngay2>sysdate and tinh_trang='Tdc'
          minus
          select pn_id from v_pn_tinh_trang where ngay1<=vDenngay and ngay2>sysdate and tinh_trang='Tron'
          minus
          select pn_id from v_pn_tinh_trang where ngay1<=vDenngay and ngay2>sysdate and tinh_trang='Tx'
          minus
          select pn_id from v_pn_tinh_trang where ngay1<=vDenngay and tinh_trang='Chuyen'
          minus
          select pn_id from v_pn_tinh_trang where ngay1<=vDenngay and tinh_trang='Mien'
          minus
          select pn_id from v_pn_tinh_trang where ngay1<=vDenngay and ngay2>vDenngay and tinh_trang='Hoan');
  RETURN l_pn_id;
END;

/
--------------------------------------------------------
--  DDL for Function GET_PRIMARY_KEY
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN_SUOI_HAI"."GET_PRIMARY_KEY" (tab_name varchar2) return varchar2 is
 str_col varchar2(2000);
begin
 for obj in 
 		(select cc.column_name col_name
      	from user_constraints uc, user_cons_columns cc
					where cc.constraint_name=uc.constraint_name
						and uc.constraint_type='P'
							and cc.table_name=upper(tab_name))
 loop
 		str_col:=str_col||';'||obj.col_name;
 end loop;
  str_col:=substr(str_col,2);
 	return str_col;
 exception
 	when no_data_found then return null;
 	when others then return null;
end; 

/
