  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN_SUOI_HAI"."GET_QUY_XEP_LOAI" (v_ngay_xet date) Return varchar is
Begin
  if to_char(v_ngay_xet,'mm') in ('12','01','02') then
  	return 'ma_xep_loai_q4 in (''110'',''120'') and nam_xl='||to_char(to_number(to_char(v_ngay_xet,'yyyy'))-1);
  elsif to_char(v_ngay_xet,'mm') in ('03','04','05') then
  	return 'ma_xep_loai_q1 in (''110'',''120'') and nam_xl='||to_char(v_ngay_xet,'yyyy');
  elsif to_char(v_ngay_xet,'mm') in ('06','07','08') then
  	return 'ma_xep_loai_q2 in (''110'',''120'') and nam_xl='||to_char(v_ngay_xet,'yyyy');
  elsif to_char(v_ngay_xet,'mm') in ('09','10','11') then
  	return 'ma_xep_loai_q3 in (''110'',''120'') and nam_xl='||to_char(v_ngay_xet,'yyyy');
  end if;
End;

