--------------------------------------------------------
--  DDL for Function GET_RTAB
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN_SUOI_HAI"."GET_RTAB" (TAB VARCHAR2,COL VARCHAR2) return varchar2 is
 	rTab varchar2(200);
begin
select  c.table_name into rTab
	from      user_constraints a,
						user_cons_columns b,
						user_cons_columns c
		where
				a.constraint_name=b.constraint_name
				and a.table_name=b.table_name
				and c.table_name<>b.table_name
				and a.r_constraint_name=c.constraint_name
				and constraint_type='R'
				and a.table_name=TAB
				and b.column_name=COL;
return rTab;
exception
	when no_data_found then return null;
	when others then return null;
end;

/
--------------------------------------------------------
--  DDL for Function GET_R_TABLE
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN_SUOI_HAI"."GET_R_TABLE" (TAB VARCHAR2,COL VARCHAR2,iLike varchar2) RETURN VARCHAR2 IS
 	vLike   varchar2(2000):=upper(iLike);
 	str    	long;
 	rTab   	varchar2(50);
 	rType number;
 	nLoop  	number;
 	Colsql 	long;
 	vCol   	varchar2(1000) :=col;
BEGIN
	begin
	 	select distinct lov_name, lov_type
	 		into rTab, rType
	 			from s_lov 
	 				where upper(block_name)=upper(tab) 
	 						and upper(item_name)=upper(col);
	 	exception
	 		when no_data_found then null;
	end;
	if rType=1 then
/*		vCol:=' getStr('||col||',1) ';
	end if;
	if countStr(vLike)>0 then
		for nLoop in 1..countStr(vLike)+1 loop
			str:=str||vCol||' in (select ma from '||rTab||' where nd like ''%'||getStr(vLike,nLoop)||'%'' or ma like ''%'||getStr(vLike,nLoop)||'%'') or ';
		end loop;
		str:='('||substr(str,1,length(str)-4)||')';*/
		str:=get_multi_condition(col,vLike,'like')||' or '||get_multi_condition('upper(U_Count_Mas('''||rTab||''','||col||'))',vLike,'like');
		str:='('||str||')';
	else
		--str:=vCol||' in (select ma from '||rTab||' where upper(nd) like ''%'||vLike||'%'' or upper(ma) like ''%'||vLike||'%'')';
		str:=get_multi_condition(col,vLike,'like')||' or '||get_multi_condition('upper(CountMa('''||rTab||''','||col||'))',vLike,'like');
		str:='('||str||')';
	end if;
	return str;
END;

/
--------------------------------------------------------
--  DDL for Function GET_R_TABLE_OLD
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN_SUOI_HAI"."GET_R_TABLE_OLD" (TAB VARCHAR2,COL VARCHAR2,vLike varchar2) RETURN VARCHAR2 IS
 	str    long;
 	rTab   varchar2(50);
 	nLoop  number;
 	Colsql long;
 	vCol   varchar2(1000) :=col;
BEGIN
	if instr(upper(COL),'TOI_DANH')>0 then
		rTab:='MA_TOI_DANH';
    vCol:=' getStr(MA_TOI_DANH,1)';
	elsif instr(upper(COL),'MGCR_GHICHU')>0 then
		rTab:='MA_GHI_CHU_RIENG';
		vCol:=' getStr(MGCR_GHICHU,1)';
	elsif instr(upper(COL),'MA_CHUC_VU')>0 then
		rTab:='MA_CHUC_VU';
		vCol:=' getStr(MA_CHUC_VU,1)';
	else
		select distinct c.table_name
			into rTab
				from 	user_constraints a,
							user_cons_columns b,
							user_cons_columns c
					where
							a.constraint_name=b.constraint_name
							and a.table_name=b.table_name
							and a.r_constraint_name=c.constraint_name
							and constraint_type='R'
							and a.table_name=UPPER(TAB)
							and b.column_name=UPPER(COL);
	end if;
	if countStr(vLike)>0 then
		for nLoop in 1..countStr(vLike)+1 loop
			str:=str||vCol||' in (select ma from '||rTab||' where nd like ''%'||getStr(vLike,nLoop)||'%'' or ma like ''%'||getStr(vLike,nLoop)||'%'') or ';
		end loop;
		str:=substr(str,1,length(str)-4);
	else
		str:=vCol||' in (select ma from '||rTab||' where nd like ''%'||vLike||'%'' or ma like ''%'||vLike||'%'')';
	end if;
	return str;
END;

