--------------------------------------------------------
--  DDL for Function GET_STR_250
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN_SUOI_HAI"."GET_STR_250" (i_str in varchar2, vpos number
                                       ,o_str1 out varchar2,o_str2 out varchar2
                                       ,o_str3 out varchar2,o_str4 out varchar2
                                       ,o_str5 out varchar2,o_str6 out varchar2
                                       ,o_str7 out varchar2,o_str8 out varchar2
                                       ) return varchar2 IS
str varchar2(4000);
v_num number:=250;
vitri1 number;
vitri2 number;
vitri3 number;
vitri4 number;
vitri5 number;
vitri6 number;
vitri7 number;
vitri8 number;
ostr1 varchar2(500);
ostr2 varchar2(500);
ostr3 varchar2(500);
ostr4 varchar2(500);
ostr5 varchar2(500);
ostr6 varchar2(500);
ostr7 varchar2(500);
ostr8 varchar2(500);
begin
 	str:=substr(i_str,1,v_num);
  if length(str)=250 then
   for i in 1..10 loop
    if substr(str,250-i,1)<>' ' and substr(str,250-i-1,1)<>' ' then
    str:=substr(i_str,1,250-i-1);
    vitri1:=250-i-1;
    exit;
    end if;
   end loop;
  end if;
  ostr1:=str;
  ------------------------------------------------------------------
  str:=substr(i_str,vitri1+1,v_num);
  if length(str)=250 then
   for i in 1..10 loop
    if substr(str,250-i,1)<>' ' and substr(str,250-i-1,1)<>' ' then
    str:=substr(str,1,250-i-1);
    vitri2:=250-i-1;
    exit;
    end if;
   end loop;
  end if;
  ostr2:=str;
  ------------------------------------------------------------------
  str:=substr(i_str,vitri1+vitri2+1,v_num);
  if length(str)=250 then
   for i in 1..10 loop
    if substr(str,250-i,1)<>' ' and substr(str,250-i-1,1)<>' ' then
    str:=substr(str,1,250-i-1);
    vitri3:=250-i-1;
    exit;
    end if;
   end loop;
  end if;
  ostr3:=str;
  ------------------------------------------------------------------
  str:=substr(i_str,vitri1+vitri2+vitri3+1,v_num);
  if length(str)=250 then
   for i in 1..10 loop
    if substr(str,250-i,1)<>' ' and substr(str,250-i-1,1)<>' ' then
    str:=substr(str,1,250-i-1);
    vitri4:=250-i-1;
    exit;
    end if;
   end loop;
  end if;
  ostr4:=str;
  ------------------------------------------------------------------
  str:=substr(i_str,vitri1+vitri2+vitri3+vitri4+1,v_num);
  if length(str)=250 then
   for i in 1..10 loop
    if substr(str,250-i,1)<>' ' and substr(str,250-i-1,1)<>' ' then
    str:=substr(str,1,250-i-1);
    vitri5:=250-i-1;
    exit;
    end if;
   end loop;
  end if;
  ostr5:=str;
  ------------------------------------------------------------------
  str:=substr(i_str,vitri1+vitri2+vitri3+vitri4+vitri5+1,v_num);
  if length(str)=250 then
   for i in 1..10 loop
    if substr(str,250-i,1)<>' ' and substr(str,250-i-1,1)<>' ' then
    str:=substr(str,1,250-i-1);
    vitri6:=250-i-1;
    exit;
    end if;
   end loop;
  end if;
  ostr6:=str;
  ------------------------------------------------------------------
  str:=substr(i_str,vitri1+vitri2+vitri3+vitri4+vitri5+vitri6+1,v_num);
  if length(str)=250 then
   for i in 1..10 loop
    if substr(str,250-i,1)<>' ' and substr(str,250-i-1,1)<>' ' then
    str:=substr(str,1,250-i-1);
    vitri7:=250-i-1;
    exit;
    end if;
   end loop;
  end if;
  ostr7:=str;
  ------------------------------------------------------------------
  str:=substr(i_str,vitri1+vitri2+vitri3+vitri4+vitri5+vitri6+vitri7+1,v_num);
  if length(str)=250 then
   for i in 1..10 loop
    if substr(str,250-i,1)<>' ' and substr(str,250-i-1,1)<>' ' then
    str:=substr(str,1,250-i-1);
    vitri8:=250-i-1;
    exit;
    end if;
   end loop;
  end if;
  ostr8:=str;
  -------------------------------------------------------------------
  o_str1:=ostr1;
  o_str2:=ostr2;
  o_str3:=ostr3;
  o_str4:=ostr4;
  o_str5:=ostr5;
  o_str6:=ostr6;
  o_str7:=ostr7;
  o_str8:=ostr8;

  if vPos=1 then 
    return ostr1;
  elsif vPos=2 then 
    return ostr2;
  elsif vPos=3 then 
    return ostr3;
  elsif vPos=4 then 
    return ostr4;
  elsif vPos=5 then 
    return ostr5;
  elsif vPos=6 then 
    return ostr6;
  elsif vPos=7 then 
    return ostr7;
  elsif vPos=8 then 
    return ostr8;
  else
    return '&nbsp;';
  end if;
end;

