--------------------------------------------------------
--  DDL for Function GET_TIEN_HPBS
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN_SUOI_HAI"."GET_TIEN_HPBS" (v_pn_id varchar2) RETURN number IS
ts_tien number;
ts_nop  number;
BEGIN

begin
    select sum(nvl(a.tong_tien_phat,0)) into ts_tien
    from pn_hpbs_hinh_phat a
    where pn_id=v_pn_id
    group by pn_id;
exception
when no_data_found then ts_tien:=0;
when others then ts_tien:=0;
end;

begin
    select sum(nvl(so_tien_nop,0)) into ts_nop
    from pn_hpbs_hinh_phat a,pn_hpbs_thuc_hien b
    where a.ma_pn_hpbshp=b.ma_pn_hpbshp and pn_id=v_pn_id
    group by pn_id;
exception
when no_data_found then ts_nop:=0;
when others then ts_nop:=0;
end;

return ts_tien-ts_nop;

END;

