/
--------------------------------------------------------
--  DDL for Function GET_TONG_TIEN_LDSX
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN_SUOI_HAI"."GET_TONG_TIEN_LDSX" (v_pn_id varchar2) return number is
 tongthu number:=0;
 tongchi number:=0;
 tongtien number:=0;
begin
begin
 select nvl(sum(nvl(tien_q1,0)+nvl(tien_q2,0)+nvl(tien_q3,0)+nvl(tien_q4,0)+nvl(tien_khac,0)),0) into tongthu
 from pn_tien_cong_sx where pn_id=v_pn_id;
 exception
   when no_data_found then tongthu:=0;
end;
 begin
   select nvl(sum(nvl(so_tien_chi,0)),0) into tongchi
   from pn_tien_chi_tieu where pn_id=v_pn_id;
 exception
   when no_data_found then tongchi:=0;
 end;
 tongtien:=tongthu-tongchi;
 if tongtien>0 then
   return tongtien;
 end if;
 return null;
exception
 when no_data_found then return null;
 when others then return null;
end;

