--  DDL for Function HPBS_CON_LAI
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN_SUOI_HAI"."HPBS_CON_LAI" (v_pn_id varchar2) RETURN number IS
ts_tien number;
ts_nop  number;
begin

begin
select sum(nvl(a.tong_tien_phat,0)) into ts_tien from pn_hpbs_hinh_phat a where a.pn_id=v_pn_id;
exception
when no_data_found then ts_tien:=0;
when others then ts_tien:=0;
end;

begin
   select sum(nvl(so_tien_nop,0)) into ts_nop
    from pn_hpbs_hinh_phat a,pn_hpbs_thuc_hien b
    where a.ma_pn_hpbshp=b.ma_pn_hpbshp and pn_id=v_pn_id
    group by pn_id;
exception
when no_data_found then ts_nop:=0;
when others then ts_nop:=0;
end;
return ts_tien-ts_nop;
END;

/
--------------------------------------------------------
--  DDL for Function ORDER_HOTEN
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN_SUOI_HAI"."ORDER_HOTEN" (vName varchar2) RETURN Varchar2 Deterministic IS
   oStr  varchar2(100);
   vTen varchar2(50);
   vHo   varchar2(50);
   vDem  varchar2(50);
	Function Conv(iStr varchar2) return varchar2 is
		 c varchar2(5);
		 n number(3);
		 l number(3);
		 i number(3);
	   vStr varchar2(50);
     str1 varchar2(500):='A a a a ? ? ? A a ? ? ? ? ? A a ? ? ? ? ? U u u u ? ? ? ? ? ? ? ? ? ? E e e e ? ? ? E e ? ? ? ? ? O o o o ? ? ? O o ? ? ? ? ? ? ? ? ? ? ? ? I i i i ? ? ? y ? y ? ? ? D D';
     str2 varchar2(500):='AAAAABACADAEAFAGAGAHAHAKALAMANANAOAPAQARASUAUAUBUCUDUEUFUGUGUHUIUKULUME0E0E1E2E3E4E5EAEAEBECEDEEEFO0O0O1O2O3O4O5OBOBOCODOEOFOGOHOIOKOLOMONOMIAIAIBICICIEIFYAYBYCYDYEYFD0D1';
	Begin
		 if iStr is null then return ''; end if;
		 l:=length(iStr);
		 vStr:='';
		 for i in 1..l loop
			 c:=upper(substr(iStr,i,1));
			 n:=instr(upper(str1),c);
			 if n>0 then
			   c:=substr(str2,n,2);
			 end if;
			 vStr:=vStr||c;
		 end loop;
		 vStr:=upper(vStr);
		 Return vStr;
	End Conv;
Begin
	vTen:=substr(vName,instr(vName,' ',-1)+1);
	vDem:=substr(vName,1,instr(vName,' ',-1)-1);
	vDem:=substr(vDem,instr(vName,' ')+1);
	vHo:=substr(vName,1,instr(vName,' ')-1);
  oStr:=conv(vTen)||conv(vHo)||conv(vDem);
  return oStr;
 End;


