--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN_SUOI_HAI"."P_COLUMN_REF" (tab_name varchar2) return varchar2 is
 str_col varchar2(2000);
begin
 for obj in
 		(select cc.column_name col_name
      	from user_constraints uc, user_cons_columns cc
					where cc.constraint_name=uc.constraint_name
						and uc.constraint_type='P'
							and cc.table_name=tab_name)
 loop
 		str_col:=str_col||'||''**''||'||obj.col_name;
 end loop;
  str_col:=substr(str_col,9);
 	return str_col;
end;

/
--------------------------------------------------------
--  DDL for Function SUBSTR_250
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN_SUOI_HAI"."SUBSTR_250" (v_str varchar2,i number, s out number) return varchar2 IS
str varchar2(4000);
v_number number:=250;
j number;
n number;
vitri number;
begin
for j in 0..9 loop
  if substr(v_str,i,1) is not null and substr(v_str,i+250+j,1)<>' ' and substr(v_str,i+250+j+1,1)<>' ' then
    vitri:=i+250+j;
    n:=j;
    exit;
  else
    vitri:=i+250;
  end if;
end loop;
  str:=substr(v_str,i+1,250+n);
  s:=vitri;
  return str;
end;

