--  DDL for Function TRANS_WHERE
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN_SUOI_HAI"."TRANS_WHERE" (strWhere long) return varchar2 IS
 pos       number;
 currValue varchar2(2000);
 strMa     varchar2(2000):=bo_dau(strWhere);
 strND     varchar2(2000);
 str       varchar2(2000);
BEGIN
	strMa:=';'||strMa||';';
	strMa:=replace(strMa,';',''')>0 or instr(bo_dau(dm),''');
	strMA:=substr(strMa,9);
	strMa:=substr(strMa,1,length(strMa)-22);
	strMa:=rtrim(ltrim(strMa));
	strND:=replace(strMa,'dm','nd');
	strMa:=replace(strMa,'dm','ma');
	str:=strMa||' or '||strNd;
	return str;
end;


