--------------------------------------------------------
--  DDL for Function U_COUNT_MAS
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN_SUOI_HAI"."U_COUNT_MAS" (TabName varchar2, lstName varchar2) RETURN varchar2 Deterministic IS
  str				varchar2(2000):=lstName||';';
	curr      varchar2(50);
	pos       number;
	lst       varchar2(2000);
	nName     varchar2(2000);
	strSql    varchar2(2000);
begin
	loop
		pos:=instr(str,';');
		curr:=substr(str,1,pos-1);
		strSql:='select nd from '||TabName||' where upper(ma)=upper('''||curr||''')';
		execute immediate strSql into nName;
		lst:=lst||nName||';';
		str:=substr(str,pos+1);
		if str is null then exit; end if;
	end loop;
	if pos>0 then
		lst:=substr(lst,1,length(lst)-1);
	end if;
	return lst;
	exception
		when no_data_found then return null;
		when others then return null;
end;

/
--------------------------------------------------------
--  DDL for Function U_COUNT_NDS
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN_SUOI_HAI"."U_COUNT_NDS" (TABNAME VARCHAR2, LSTNAME VARCHAR2) RETURN VARCHAR2 IS
  STR				VARCHAR2(2000):=REPLACE(LSTNAME||';','''','_');
	CURR      VARCHAR2(2000);
	POS       NUMBER;
	LST       VARCHAR2(2000);
	NNAME     VARCHAR2(2000);
	STRSQL    VARCHAR2(2000);
BEGIN
	LOOP
		POS:=INSTR(STR,';');
		CURR:=SUBSTR(STR,1,POS-1);
		STRSQL:='select ma from '||TABNAME||' where upper(nd) like upper('''||CURR||''')';
		EXECUTE IMMEDIATE STRSQL INTO NNAME;
		LST:=LST||NNAME||';';
		STR:=SUBSTR(STR,POS+1);
		IF STR IS NULL THEN EXIT; END IF;
	END LOOP;
	IF POS>0 THEN
		LST:=SUBSTR(LST,1,LENGTH(LST)-1);
	END IF;
	RETURN LST;
	EXCEPTION
		WHEN NO_DATA_FOUND THEN RETURN NULL;
		WHEN OTHERS THEN RETURN NULL;
END;

