/
--------------------------------------------------------
--  DDL for Function VALID_DATE
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN_SUOI_HAI"."VALID_DATE" (date_str varchar2) return varchar2 IS
  vret varchar2(10);
BEGIN
  if length(date_str)=6 then
  vret:=to_char(to_date(date_str,'ddmmrr'),'dd/mm/rrrr');
elsif length(date_str)=8 then
  vret:=to_char(to_date(date_str,'ddmmyyyy'),'dd/mm/yyyy');
elsif length(date_str)=10 then
  vret:=to_char(to_date(date_str,'dd/mm/yyyy'),'dd/mm/yyyy');
elsif length(date_str)=4 then
  if to_number(substr(date_str,1,2))>18 then
    vret:=date_str;
  else
    vret:=to_char(to_date('01'||date_str,'ddmmrr'),'mm/rrrr');
  end if;
elsif length(date_str)=5 then
  vret:=to_char(to_date('01/'||date_str,'dd/mm/rr'),'mm/rrrr');
elsif length(date_str)=2 then
  vret:=to_char(to_date('01/01/'||date_str,'dd/mm/rr'),'YYYY');
end if;
return vret;
END;

